local config = {
  ui_story_5084_50840100_1_dialog_content = "¿Esto es... una tumba?",
  ui_story_5084_50840100_2_dialog_content = "\"Varaki, tu destino ha sido revelado, y sin embargo tu corazón aún alberga dudas.\"",
  ui_story_5084_50840100_3_dialog_content = "Es porque entiendo el precio a pagar. Obtener poder es convertirse en su prisionero y renunciar a cualquier sentido de paz por el resto de la vida.",
  ui_story_5084_50840100_4_dialog_content = "No deseo ser como mis padres y sufrir por mi fuerza. Solo encontraron descanso una vez que cada última gota de Varaki desapareció de sus cuerpos.",
  ui_story_5084_50840100_5_dialog_content = "\"No eres un discípulo de los Varaki. Como yo, solo adoras al Señor de la Verdad.\"",
  ui_story_5084_50840100_6_dialog_content = "\"Como discípulo de La Verdad, has viajado por este mundo y descubierto un gran poder.\"",
  ui_story_5084_50840100_7_dialog_content = "\"Si tu corazón realmente anhela la llegada del Señor de la Verdad, entonces no tienes ninguna razón para temer ningún sacrificio.\"",
  ui_story_5084_50840100_8_dialog_content = "¿Qué quieres que haga?",
  ui_story_5084_50840100_9_dialog_content = "\"Ayúdame a recuperar mi poder y mi forma física. A cambio, extraeré el poder de tu cuerpo y te concederé el descanso eterno.\"",
  ui_story_5084_50840100_10_dialog_content = "\"Encuentro el sabor del peligro muy emocionante.\"",
  ui_story_5084_50840100_11_dialog_content = "\"Porque me permite saborear La Verdad por mí mismo.\"",
  ui_story_5084_50840100_12_dialog_content = "¿Qué viste, Dama Victoria?",
  ui_story_5084_50840100_13_dialog_content = "El momento en que formé un pacto con la Bloody Bible. En ese momento, no me reveló el futuro de este anillo.",
  ui_story_5084_50840100_14_dialog_content = "Pero ahora está de nuevo en mis manos... Incluso antes de poner los ojos en él, sentí un antiguo poder llamándome.",
  ui_story_5084_50840100_15_dialog_content = "Una sensación de hormigueo familiar me persigue cada vez que lo sostengo....",
  ui_story_5084_50840100_16_dialog_content = "¿Compartes una conexión con este anillo?",
  ui_story_5084_50840100_17_dialog_content = "Sí. Es una reliquia de los antiguos Varaki, transmitida a través de las generaciones por los líderes de la Orden Verdadera.",
  ui_story_5084_50840100_18_dialog_content = "Que vuelva a su dueño original es motivo de celebración.",
  ui_story_5084_50840100_19_dialog_content = "Lo más importante no es el anillo en sí, sino el momento de su aparición.",
  ui_story_5084_50840100_20_dialog_content = "A medida que se acerca el Advenimiento de la Verdad, encuentro este anillo hasta ahora perdido en mi posesión una vez más.",
  ui_story_5084_50840100_21_dialog_content = "¡...!",
  ui_story_5084_50840100_22_dialog_content = "¡Dama Victoria!",
  ui_story_5084_50840100_23_dialog_content = "Jajajaja... Varaki...",
  ui_story_5084_50840100_24_dialog_content = "¡Tú! Agh... ¡Argh!",
  ui_story_5084_50840100_25_dialog_content = "¡¡¡Ahhhhhhhhh—!!!",
  ui_story_5084_50840100_26_dialog_content = "¡Dama Victoria!",
  ui_story_5084_50840100_27_dialog_content = "Lo que acabo de ver...",
  ui_story_5084_50840100_28_dialog_content = "Se sintió como una profecía... Y sin embargo, parecía haber sucedido en el pasado...",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>Fwoosh—!</color>",
  ui_story_5084_50840100_30_dialog_content = "\"El catalizador ha sido invocado.\"",
  ui_story_5084_50840100_31_dialog_content = "\"La tumba espera su llegada.\"",
  ui_story_5084_50840100_32_dialog_content = "\"El conocimiento de La Verdad debe ser probado y verificado.\"",
  ui_story_5084_50840100_33_dialog_content = "\"Una gran ceremonia celebrada bajo la vieja luna.\"",
  ui_story_5084_50840100_34_dialog_content = "\"Ha llegado el momento.\"",
  ui_story_5084_50840100_35_dialog_content = "...",
  ui_story_5084_50840100_36_dialog_content = "Esta revelación parece algo oscura, Lady Victoria.",
  ui_story_5084_50840100_37_dialog_content = "Cuando se combina con sus predicciones pasadas, la revelación del anillo es en realidad bastante clara.",
  ui_story_5084_50840100_38_dialog_content = "\"Finalmente ha llegado el momento. Un encuentro inesperado ocurrirá durante el Advenimiento de la Verdad.\"",
  ui_story_5084_50840100_39_dialog_content = "\"Para confirmar nuestra comprensión de La Verdad, debemos buscar al guardián de la Cripta Estrellada.\"",
  ui_story_5084_50840100_40_dialog_content = "\"Para esta empresa, requerimos la ayuda del Caelestita.\"",
  ui_story_5084_50840100_41_dialog_content = "Esta es la primera vez que la Biblia Sangrienta ha intentado ofuscar una de sus profecías.",
  ui_story_5084_50840100_42_dialog_content = "Parece que las revelaciones ofrecidas por este anillo perdido hace mucho tiempo conectarán días y eventos que nunca se presenciaron.",
  ui_story_5084_50840100_43_dialog_content = "Creo que entiendo ahora.",
  ui_story_5084_50840100_44_dialog_content = "Te dejo con la tarea de reclutar a nuestro amigo de sangre fresca.",
  ui_story_5084_50840100_45_dialog_content = "Sí, Lady Victoria.",
  ui_story_5084_50840100_46_dialog_content = "Sé que ya explicaste todo, pero aún no tiene sentido para mí. ¿Por qué tengo que participar en la celebración de True Order?",
  ui_story_5084_50840100_47_dialog_content = "Perdóname, pero simplemente estoy atendiendo los deseos de Lady Victoria y el Señor de la Verdad.",
  ui_story_5084_50840100_48_dialog_content = "Suspiro, ustedes son tan vagos como siempre, veo...",
  ui_story_5084_50840100_49_dialog_content = "Estamos bastante lejos de Umbraton ahora. ¿Exactamente a dónde me llevas?",
  ui_story_5084_50840100_50_dialog_content = "¡Guau—",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5084_50840100_52_dialog_content = "¿Qué es esta cosa que parece oscura... Y por qué se está moviendo?!",
  ui_story_5084_50840100_53_dialog_content = "Oh, así que tú eres el que perturbó mi sueño, Bola de Nieve.",
  ui_story_5084_50840100_54_dialog_content = "... ¿Sikare?",
  ui_story_5084_50840100_55_dialog_content = "¿Acabo de tropezar con tus enredaderas?",
  ui_story_5084_50840100_56_dialog_content = "No es cortés seguir haciendo preguntas después de pisar a alguien. Realmente deberías disculparte, ¿sabes?",
  ui_story_5084_50840100_57_dialog_content = "L-Lo siento por eso... Entonces, ¿qué estás haciendo aquí, de todos modos?",
  ui_story_5084_50840100_58_dialog_content = "Yo podría preguntarte exactamente lo mismo. ¿Qué te trae por aquí hoy?",
  ui_story_5084_50840100_59_dialog_content = "Todo es mi culpa. Sabía que iba a cometer un error imperdonable hoy.",
  ui_story_5084_50840100_60_dialog_content = "Si no te importa, Señorita Sikare, me gustaría arrepentirme de mis pecados aquí y ahora...",
  ui_story_5084_50840100_61_dialog_content = "Parece que todos están presentes ahora, Lady Victoria.",
  ui_story_5084_50840100_62_dialog_content = "Señorita Victoria...",
  ui_story_5084_50840100_63_dialog_content = "Una vez me dijiste que aún no era el momento, y que los secretos dentro de la Cripta Estrellada aún estaban más allá de mi comprensión.",
  ui_story_5084_50840100_64_dialog_content = "La Biblia Sangrienta me ha guiado hasta aquí hoy.",
  ui_story_5084_50840100_65_dialog_content = "May ¿Pregunto qué tipo de artefacto has encontrado esta vez?",
  ui_story_5084_50840100_66_dialog_content = "Éste.",
  ui_story_5084_50840100_67_dialog_content = "Si lo que dices es cierto, entonces ahora tienes el privilegio de entrar a la Cripta Estrellada.",
  ui_story_5084_50840100_68_dialog_content = "¿Qué tipo de lugar es este, de todos modos?",
  ui_story_5084_50840100_69_dialog_content = "En términos sencillos, es un lugar donde se entierran a los muertos.",
  ui_story_5084_50840100_70_dialog_content = "¿¡Qué?! Pero... Pero Faust dijo que esto era para la próxima celebración de la Orden Verdadera!",
  ui_story_5084_50840100_71_dialog_content = "En cierto sentido, sí. Por el bien de lo que está por venir, primero debemos llegar a este lugar.",
  ui_story_5084_50840100_72_dialog_content = "No tengas miedo. Lo que yace dentro de la Cripta Estrellada es más valioso que toda la riqueza de Lumopolis combinada.",
  ui_story_5084_50840100_73_dialog_content = "Innumerables personas han venido en busca de los secretos de la cripta, solo para encontrarse enterrados aquí. Considérense afortunados.",
  ui_story_5084_50840100_74_dialog_content = "A-Aunque sea un tesoro, yo... ¡yo merezco algo de tiempo para pensar en esto! ¿Verdad...?",
  ui_story_5084_50840100_75_dialog_content = "Antes de entrar a la Cripta Estrellada, solo tengo tres advertencias para compartir.",
  ui_story_5084_50840100_76_dialog_content = "Primero, la sangre es la única forma en que Faria reconoce a aquellos que desean entrar en la cripta, y solo aquellos que han formado un pacto de sangre con ella pueden hacerlo.",
  ui_story_5084_50840100_77_dialog_content = "La otra puerta abierta por Faria acatará la voluntad del atado.",
  ui_story_5084_50840100_78_dialog_content = "Esta es Faria.",
  ui_story_5084_50840100_79_dialog_content = "En segundo lugar, los objetos que llevas contigo poseen una presencia guía. Como pertenecen al tiempo, naturalmente seguirán el tiempo hasta los lugares a los que pertenecen.",
  ui_story_5084_50840100_80_dialog_content = "En tercer lugar, el destino ha sido determinado desde hace mucho tiempo. No hay lugar para cuestionarlo, resentirlo o cambiarlo.",
  ui_story_5084_50840100_81_dialog_content = "Aunque parece que todavía tienes muchas preguntas, Snowball.",
  ui_story_5084_50840100_82_option_content = "¿Un \"pacto de sangre\"?",
  ui_story_5084_50840100_83_dialog_content = "¿Esto significa que tenemos que sangrar?",
  ui_story_5084_50840100_84_dialog_content = "Oh todopoderoso Señor de la Verdad, toma hasta la última gota de mi sangre manchada si es tu deseo...",
  ui_story_5084_50840100_85_option_content = "¿Un destino \"incuestionable\"?",
  ui_story_5084_50840100_86_dialog_content = "Suena como una de esas historias sobre ser enviado a un mundo diferente.",
  ui_story_5084_50840100_87_dialog_content = "De repente, te ves mucho más emocionado.",
  ui_story_5084_50840100_88_dialog_content = "Comienza los preparativos, Faria.",
  ui_story_5084_50840100_89_dialog_content = "¡E-Espera! Mi sangre... ¿La sangre de un Caelestita incluso funcionará para este tipo de cosas?",
  ui_story_5084_50840100_90_dialog_content = "¡Pincha—!",
  ui_story_5084_50840100_91_dialog_content = "<size=45>¡¡¡Ay!!!</size>",
  ui_story_5084_50840100_92_dialog_content = "¿No escuchaste? Sikare le dijo a Faria que se prepare, ¡así que pongámonos en marcha!",
  ui_story_5084_50840100_93_dialog_content = "Tienes que llevar a Bebe y a mí contigo, Lady Victoria! Te prometo que nos portaremos lo mejor posible!",
  ui_story_5084_50840100_94_dialog_content = "¿Lenore sabe que estás aquí, May?",
  ui_story_5084_50840100_95_dialog_content = "Lo es, y ella también me dijo que me divirtiera mucho!",
  ui_story_5084_50840100_96_dialog_content = "¡Bebe ahorró mucho hilo, lo que significa que puedo coser tantas heridas como tú necesites!",
  ui_story_5084_50840100_97_dialog_content = "¡Cuidaré bien de ti PlayerName, así que no te alejes demasiado de mí!",
  ui_story_5084_50840100_98_dialog_content = "¡Miau!",
  ui_story_5084_50840100_99_dialog_content = "Creo que es mejor si mantengo mi distancia por ahora...",
  ui_story_5084_50840100_100_dialog_content = "Si todos están listos ahora, Faria puede comenzar.",
  ui_story_5084_50840100_101_dialog_content = "Señor de la Verdad, guíame a la respuesta que busco.",
  ui_story_5084_50840100_102_dialog_content = "Señor de la Verdad, bendice nuestro viaje con seguridad y prontitud.",
  ui_story_5084_50840100_103_dialog_content = "Señor de la Verdad, castígame por mis pecados.",
  ui_story_5084_50840100_104_dialog_content = "¡Señor de la Verdad, llévame a un lugar divertido!",
  ui_story_5084_50840100_105_dialog_content = "Puedes tirar de mi ropa todo lo que quieras... aún así, yo no...",
  ui_story_5084_50840100_106_dialog_content = "¡Urk...!",
  ui_story_5084_50840100_107_dialog_content = "S... Sikare...",
  ui_story_5084_50840100_108_dialog_content = "Sálvame...",
  ui_story_5084_50840100_109_dialog_content = "Parece que estás en mucho dolor con tus ojos cerrados así, Snowball.",
  ui_story_5084_50840100_110_dialog_content = "Ábrelos y echa un vistazo alrededor. Aquí no hay peligro.",
  ui_story_5084_50840100_111_dialog_content = "P-Pero esas enredaderas gruesas de ahora... Eran tan picantes y aterradoras...",
  ui_story_5084_50840100_112_dialog_content = "¿No quieres saber más sobre La Verdad? Oh espera, acabo de recordar que aún no te has unido a la True Order.",
  ui_story_5084_50840100_113_dialog_content = "... Realmente no prestas atención a muchas cosas, ¿verdad, Sikare?",
  ui_story_5084_50840100_114_dialog_content = "De todos modos, ¡no puedo creer que hayan desaparecido así de fácil!",
  ui_story_5084_50840100_115_dialog_content = "El verdadero problema es que tú tampoco desapareciste.",
  ui_story_5084_50840100_116_dialog_content = "Necesito escucharte decir algo como \"Deseo acercarme más a La Verdad,\" o \"Deseo rendir mis pensamientos y dejar que mis sentidos exploren el mundo a mi alrededor.\"",
  ui_story_5084_50840100_117_dialog_content = "Eres un Caelestite, así que deberías ser bastante bueno en algo como esto.",
  ui_story_5084_50840100_118_dialog_content = "Puedes decirme quién eres, o por qué estás aquí, o a dónde quieres ir...",
  ui_story_5084_50840100_119_dialog_content = "Tan oscuro... Solo vine porque Faust me invitó a una celebración \"única en la vida\".",
  ui_story_5084_50840100_120_dialog_content = "Entonces solo piensa en una celebración. Si todavía tienes miedo, simplemente tantea entre las enredaderas y busca un candelabro.",
  ui_story_5084_50840100_121_dialog_content = "Un candelabro...",
  ui_story_5084_50840100_122_dialog_content = "O-Oh, mira, en realidad encontré uno...",
  ui_story_5084_50840100_123_dialog_content = "Servirá como tu guía, pero no te dejes llevar; recuerda regresar antes de que la vela se apague.",
  ui_story_5084_50840100_124_dialog_content = "Pero... ¿Cómo hago eso? ¿Y a dónde se supone que debo regresar?",
  ui_story_5084_50840100_125_dialog_content = "... Sikare?",
  ui_story_5084_50840100_126_dialog_content = "Sikare!",
  ui_story_5084_50840201_1_dialog_content = "(Gracias a Dios que conseguí este candelabro de Sikare, o si no, estaría demasiado oscuro aquí...)",
  ui_story_5084_50840201_2_dialog_content = "(Aunque todavía no tengo idea de dónde encontrar a los demás...)",
  ui_story_5084_50840201_3_dialog_content = "Espera, ¿es esto...?",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>Mientras suenan las campanas antiguas, innumerables torres de reloj se elevan repentinamente y se extienden hacia la luna roja sangre en el cielo nocturno.</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>Su luz carmesí brilla sobre los caminos de los fieles y las paredes y puertas intrincadamente talladas de la ciudad.</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>Escucha las confesiones dentro del Templo de la Verdad, y habla de la gloria y los secretos de la familia de sangre...</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>¡Salto, salto—!</color>",
  ui_story_5084_50840201_8_dialog_content = "El suelo aquí es real... ¡Y también estas paredes!",
  ui_story_5084_50840201_9_dialog_content = "¿No es como la Mansión de la Verdad, verdad? Un lugar donde nadie está al tanto de lo que está sucediendo a menos que estén realmente aquí...",
  ui_story_5084_50840201_10_dialog_content = "Ah sí, la luna de sangre ha aparecido. Ahora, el Advenimiento de la Verdad, que solo ocurre una vez cada tres años, finalmente puede comenzar.",
  ui_story_5084_50840201_11_dialog_content = "Mis oraciones están listas, y las recitaré al Señor de la Verdad con todo mi corazón durante la procesión.",
  ui_story_5084_50840201_12_dialog_content = "Tus oraciones no serán escuchadas a menos que seas elegido como un \"Iniciado\". Solo sacrificándote a ti mismo, el Señor de la Verdad responderá a tus súplicas.",
  ui_story_5084_50840201_13_dialog_content = "Ciudad de Varaki... ¿Es aquí donde el True Order está celebrando su \"celebración\"? El advenimiento de la verdad... desfile...",
  ui_story_5084_50840201_14_dialog_content = "¿Cómo llegué incluso hasta aquí? ¿Y adónde fueron todos los demás...?",
  ui_story_5084_50840201_15_dialog_content = "Primero, tienes que leer, aprender e interactuar con los demás. Los hermanos y hermanas de la Orden Verdadera pueden enseñarte muchas cosas que nunca aprenderías por tu cuenta.",
  ui_story_5084_50840201_16_dialog_content = "En segundo lugar, tienes que comer, congregarte y alabar al Señor de la Verdad.",
  ui_story_5084_50840201_17_dialog_content = "Al comer en compañía de los fieles todos los días, La Verdad eventualmente se revelará a ti.",
  ui_story_5084_50840201_18_dialog_content = "Tercero, tienes que excavar y explorar. Si tienes algún talento, encontrarás tesoros para que todos admiren y disfruten.",
  ui_story_5084_50840201_19_dialog_content = "Si te encanta explorar como a mí antes, entonces no hay mejor familia para ti que True Order.",
  ui_story_5084_50840201_20_dialog_content = "¡Incluso el Sr. Beau dejó de perder tanto cabello después de que nos unimos!",
  ui_story_5084_50840201_21_dialog_content = "También logré ganarme el respeto de Lady Victoria bastante rápido, por eso a menudo confía en mí para manejar su trabajo importante por mi cuenta.",
  ui_story_5084_50840201_22_dialog_content = "¿Bueno? ¿No te hace querer unirte a la True Order?",
  ui_story_5084_50840201_23_dialog_content = "¡Miau!",
  ui_story_5084_50840201_24_dialog_content = "Parece bastante segura de sí misma...",
  ui_story_5084_50840201_25_dialog_content = "Antes de predicarnos, quizás deberías vestirte de manera más agradable.",
  ui_story_5084_50840201_26_dialog_content = "Lady Victoria es una noble de la Familia Varaki. ¿Cómo podría confiar en una pequeña niña como tú para manejar sus asuntos...?",
  ui_story_5084_50840201_27_dialog_content = "Además, ¿estoy en lo correcto al suponer que esta es tu primera vez en la ciudad de Varaki?",
  ui_story_5084_50840201_28_dialog_content = "Si es así, permíteme ilustrarte sobre los orígenes y enseñanzas de la True Order, así como los secretos ocultos dentro de la cripta...",
  ui_story_5084_50840201_29_dialog_content = "E-Espera, ¿son ustedes los mayores de la Orden Verdadera...? Pero ambos son tan diferentes de las personas que conozco...",
  ui_story_5084_50840201_30_dialog_content = "May...!",
  ui_story_5084_50840201_31_dialog_content = "PlayerName? ¿Por qué me arrastraste?! ¡Esos dos estaban a punto de unirse a nosotros!",
  ui_story_5084_50840201_32_dialog_content = "Dejando de lado el hecho de que claramente no tenían ninguna intención de \"unirse\" a ti...",
  ui_story_5084_50840201_33_dialog_content = "¿No has estado escuchando a la gente en la calle? Han estado hablando sobre el Advenimiento de la Verdad y algún tipo de procesión... No estoy seguro de cómo, ¡pero terminamos en el pueblo de Varaki! ¡El pueblo natal de Lady Victoria!",
  ui_story_5084_50840201_34_dialog_content = "La ciudad natal de Lady Victoria... Sí, creo que he oído hablar de ella antes. ¿Entonces cuál es el problema?",
  ui_story_5084_50840201_35_dialog_content = "¿Quieres decir que no te sorprende nada de esto? ¿No tienes curiosidad por saber a dónde fue el resto de nuestro grupo?",
  ui_story_5084_50840201_36_dialog_content = "¡Jajaja, ya lo entiendo! ¡Todos se están vistiendo para la celebración ahora mismo!",
  ui_story_5084_50840201_37_dialog_content = "¡Vamos a preguntar dónde compraron sus atuendos y compramos algunos para nosotros mismos!",
  ui_story_5084_50840201_38_dialog_content = "¿Eh? ¿Por qué estás tan emocionado? Este lugar parece más una sastrería embrujada que cualquier tipo de tienda...",
  ui_story_5084_50840201_39_dialog_content = "Eh... ¿May?",
  ui_story_5084_50840201_40_dialog_content = "¡Escucha! ¡La procesión viene por aquí! Toma mi mano y no la sueltes!",
  ui_story_5084_50840201_41_dialog_content = "¡Escucho que la persona dentro de ese ataúd es un antepasado Varaki, y que fueron elegidos por el Señor de la Verdad!",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>Con la luna de sangre como testigo, un grupo de personas con túnicas elegantes marchan lentamente por la calle, llevando en sus hombros los paños de un ataúd antiguo y ornamentado.</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>Dentro del ataúd yace el llamado \"ancestro\" de los Varaki, sosteniendo un texto sagrado y exudando La Verdad junto con la luz de la luna de sangre.</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>Los discípulos de la Verdad siguen con reverencia, sin atreverse a quitar los ojos del ataúd.</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>Lentamente y solemnemente, pasan por cada calle de la ciudad antes de llegar a las puertas del Templo de la Verdad.</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>Crujido... Pum—</color>",
  ui_story_5084_50840201_47_dialog_content = "La procesión ha terminado, y La Verdad ha llegado.",
  ui_story_5084_50840201_48_dialog_content = "Los fieles se han acercado a nuestro señor y le han hecho sus ofrendas.",
  ui_story_5084_50840201_49_dialog_content = "¡Alaba al Señor de la Verdad!",
  ui_story_5084_50840201_50_dialog_content = "¡Dedico mi vida al Señor de la Verdad!",
  ui_story_5084_50840201_51_dialog_content = "Ahora...",
  ui_story_5084_50840201_52_dialog_content = "Uno de vosotros será elegido por lo divino y se le permitirá entrar a este ataúd de revelaciones infinitas, para escuchar y recibir La Verdad.",
  ui_story_5084_50840201_53_dialog_content = "Con su profunda perspicacia, verás incluso los secretos más oscuros de la historia. ",
  ui_story_5084_50840201_54_dialog_content = "De esta manera, trascenderás tu individualidad y te convertirás en la encarnación del True Order y su sabiduría colectiva. ",
  ui_story_5084_50840201_55_dialog_content = "Todo lo que experimentes guiará a nuestra sagrada orden hacia un futuro cada vez más grande. ",
  ui_story_5084_50840201_56_dialog_content = "Una vez sumergido en el flujo ilimitado de la nada, las fronteras del tiempo y el espacio se disolverán a tu alrededor.",
  ui_story_5084_50840201_57_dialog_content = "Solo cuando el Señor de la Verdad aparezca y te limpie de tu ego alcanzarás tu forma más pura.",
  ui_story_5084_50840201_58_dialog_content = "Escucha La Verdad, despierta tu mente y asciende a un plano superior.",
  ui_story_5084_50840201_59_dialog_content = "Cuando llegue el momento, lograrás la unidad con lo divino.",
  ui_story_5084_50840201_60_dialog_content = "¡Elígeme, señor Wilhelm!",
  ui_story_5084_50840201_61_dialog_content = "¡Deseo escuchar La Verdad...!",
  ui_story_5084_50840201_62_dialog_content = "¡Yo también quiero escuchar La Verdad!",
  ui_story_5084_50840201_63_dialog_content = "¡Shhh! Calma, May!",
  ui_story_5084_50840201_64_dialog_content = "Fue lo suficientemente difícil para nosotros mezclarnos con la multitud...",
  ui_story_5084_50840201_65_dialog_content = "Pero si quiero ser un miembro importante de la Orden Verdadera, ¡tengo que aprender más sobre La Verdad! Esta es una oportunidad perfecta para eso, ¡ahora ve, Bebe!",
  ui_story_5084_50840201_66_dialog_content = "\"El destino ha sido determinado desde hace mucho tiempo. No hay lugar para cuestionarlo, resentirlo o cambiarlo.\"",
  ui_story_5084_50840201_67_dialog_content = "¿Miau...?",
  ui_story_5084_50840201_68_dialog_content = "¿Ya has olvidado la advertencia que nos dio Sikare, May?",
  ui_story_5084_50840201_69_dialog_content = "¿L... Dama Victoria?!",
  ui_story_5084_50840201_70_dialog_content = "¿Eh? ¿Qué pasa con ese atuendo?",
  ui_story_5084_50840201_71_dialog_content = "Podría hacer la misma pregunta. ¿Los conseguiste para poder entrar a este lugar?",
  ui_story_5084_50840201_72_dialog_content = "Fue idea de May. Después de eso, simplemente seguimos a la multitud todo el camino hasta aquí.",
  ui_story_5084_50840201_73_dialog_content = "¿Así que sabes dónde estamos ahora?",
  ui_story_5084_50840201_74_dialog_content = "Creo que sí. Según esos adoradores, estamos en la ciudad de Varaki... Tu hogar. Realmente parece que fuimos a otro mundo, ¿sabes?",
  ui_story_5084_50840201_75_dialog_content = "Esto está todo en el pasado.",
  ui_story_5084_50840201_76_dialog_content = "¿El pasado?",
  ui_story_5084_50840201_77_dialog_content = "En ese momento, aún no me había unido a la True Order. Estaba viajando por el mundo en busca de la Verdad para mí mismo.",
  ui_story_5084_50840201_78_dialog_content = "Estamos en el año 1915. Tras este Advenimiento de la Verdad, el líder de True Order desaparece.",
  ui_story_5084_50840201_79_dialog_content = "... ¿A dónde va él?",
  ui_story_5084_50840201_80_dialog_content = "El Señor de la Verdad me guió aquí a través de ese anillo. Es justo como dijo Sikare: como un objeto perteneciente al tiempo, me guió a su lugar legítimo en la historia.",
  ui_story_5084_50840201_81_dialog_content = "La Biblia Sangrienta está en posesión de mi antepasado, pero el anillo sigue en manos del líder de la Orden Verdadero.",
  ui_story_5084_50840201_82_dialog_content = "No importa cuántos años pasen, la maldición de la línea de sangre Varaki nunca puede deshacerse.",
  ui_story_5084_50840201_83_dialog_content = "En el flujo interminable del tiempo, se requiere la verdadera iluminación para responder a las preguntas que albergas.",
  ui_story_5084_50840201_84_dialog_content = "La Verdad debe impregnar tu ser para obtener una mayor comprensión del mundo.",
  ui_story_5084_50840201_85_dialog_content = "Yo, Wilhelm Varaki, líder de True Order, bajo la guía del Señor de la Verdad, anuncio aquí el Iniciado de este Advenimiento de la Verdad—",
  ui_story_5084_50840201_86_dialog_content = "Victoria Varaki.",
  ui_story_5084_50840201_87_dialog_content = "¿Qué...?",
  ui_story_5084_50840201_88_dialog_content = "¿Victoria Varaki? ¿Por qué está ella aquí...?",
  ui_story_5084_50840201_89_dialog_content = "Jeje. Interesante.",
  ui_story_5084_50840201_90_dialog_content = "...",
  ui_story_5084_50840201_91_dialog_content = "¿Dama Victoria? ¡Es ella! ¡Ella realmente está aquí!",
  ui_story_5084_50840201_92_dialog_content = "Pero ella es la única hija de los Varaki...",
  ui_story_5084_50840201_93_dialog_content = "Sí, pero escuché que el jefe de la familia no la reclama como suya...",
  ui_story_5084_50840201_94_dialog_content = "...",
  ui_story_5084_50840301_1_dialog_content = "<size=30>... ¡Es la Dama Victoria!</size>",
  ui_story_5084_50840301_2_dialog_content = "¡¿Por qué te ves tan feliz?! ¡Ella ha sido vista por la gente del pasado!",
  ui_story_5084_50840301_3_dialog_content = "¿No va eso en contra de las reglas de que estemos aquí?!",
  ui_story_5084_50840301_4_dialog_content = "Sigue la guía de tu corazón, y las revelaciones de la Verdad no te llevarán por mal camino.",
  ui_story_5084_50840301_5_dialog_content = "Hasta la próxima luna de sangre, fieles discípulos. El Señor de la Verdad nos vigila a todos, esperando pacientemente que nos acerquemos a él.",
  ui_story_5084_50840301_6_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840301_7_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840301_8_dialog_content = "¿Deberíamos irnos con ellos?",
  ui_story_5084_50840301_9_dialog_content = "Si me permites, mi corazón me dice que me aparte y observe en silencio.",
  ui_story_5084_50840301_10_dialog_content = "Habla tu mente, Victoria.",
  ui_story_5084_50840301_11_dialog_content = "No soy miembro de la True Order. El honor de escuchar La Verdad se desperdicia en mí.",
  ui_story_5084_50840301_12_dialog_content = "Y sin embargo, no escuché ninguna objeción cuando te elegí en el Templo de la Verdad.",
  ui_story_5084_50840301_13_dialog_content = "¿Buscar la Verdad y formar alianzas; no es simplemente tu forma de prepararte para unirte a la True Order en el futuro?",
  ui_story_5084_50840301_14_dialog_content = "Mi negocio no es de tu incumbencia.",
  ui_story_5084_50840301_15_dialog_content = "Todavía no me has respondido. Dime, ¿qué es exactamente La Verdad?",
  ui_story_5084_50840301_16_dialog_content = "...",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>Crrrrrieta-!</color>",
  ui_story_5084_50840301_18_dialog_content = "El honor de escuchar La Verdad... Deseo fervientemente escuchar los pensamientos de alguien tan precoz como tú, Victoria Varaki. ¿Qué es, en tu definición, La Verdad?",
  ui_story_5084_50840301_19_dialog_content = "La Verdad... es el conocimiento.",
  ui_story_5084_50840301_20_dialog_content = "Humph, Victoria Varaki... Aunque compartimos la misma línea de sangre, en términos de fuerza, sabiduría, capacidad e incluso belleza... Estoy muy por encima de ti.",
  ui_story_5084_50840301_21_dialog_content = "¿Entonces qué te hace pensar que este anillo es legítimamente tuyo?",
  ui_story_5084_50840301_22_dialog_content = "¡Soy un verdadero Varaki y el líder de la True Order!",
  ui_story_5084_50840301_23_dialog_content = "En cuanto a ti... Primero debes demostrar que eres digno de nuestro apellido familiar. No me decepciones.",
  ui_story_5084_50840301_24_dialog_content = "...",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>Crrrrack—!</color>",
  ui_story_5084_50840301_26_dialog_content = "Elige palabras y frases de libros que no puedes comprender, y busca iluminación en las imágenes que evocan en tu mente...",
  ui_story_5084_50840301_27_dialog_content = "¿No es esta tu forma de buscar respuestas?",
  ui_story_5084_50840301_28_dialog_content = "¿Qué viste hace un momento? ¿Qué te vino a la mente?",
  ui_story_5084_50840301_29_dialog_content = "¿Duda? ¿Miedo? ¿Negación? El poder de los Varaki no puede ser elegido, pues el propio poder elige a aquellos que son dignos de él.",
  ui_story_5084_50840301_30_dialog_content = "...",
  ui_story_5084_50840301_31_dialog_content = "(Él lleva el anillo familiar de Victoria...)",
  ui_story_5084_50840301_32_dialog_content = "Wilhelm... Pensé que dijiste que Victoria había partido de la ciudad de Varaki?",
  ui_story_5084_50840301_33_dialog_content = "Jejeje, eso ella tenía.",
  ui_story_5084_50840301_34_dialog_content = "¿Cómo puedes ser tan duro con una mujer joven tan brillante y prometedora, Varaki?",
  ui_story_5084_50840301_35_dialog_content = "Ha pasado bastante tiempo, Dama Victoria.",
  ui_story_5084_50840301_36_dialog_content = "Tiene.",
  ui_story_5084_50840301_37_dialog_content = "El Señor de la Verdad me guió para elegirla, Porfirio. Los Varaki y yo somos impotentes para cambiar su voluntad.",
  ui_story_5084_50840301_38_dialog_content = "Jejeje, no te culpo por esto, Wilhelm. Simplemente lamento la marcada desigualdad entre las ramas de nuestra familia de sangre.",
  ui_story_5084_50840301_39_dialog_content = "¿Aparecerá aún el Señor de la Verdad ante nosotros? ¿Le falta fe o dignidad a su elegido?",
  ui_story_5084_50840301_40_dialog_content = "Esta decisión recae en los jefes de las doce familias de la rama, no solo en el líder Varaki.",
  ui_story_5084_50840301_41_dialog_content = "¡Jajaja, otra refutación elegante y mordaz, Porfirio.",
  ui_story_5084_50840301_42_dialog_content = "En cualquier caso, la voluntad de la Verdad no debe ser ignorada. Veamos... ¿Qué conocimiento le impartirá el Señor de la Verdad a ella...",
  ui_story_5084_50840301_43_dialog_content = "¡Cabezas de familias!",
  ui_story_5084_50840301_44_dialog_content = "¿Hay alguna objeción al Iniciado elegido para este Advenimiento de la Verdad?",
  ui_story_5084_50840301_45_dialog_content = "...",
  ui_story_5084_50840301_46_dialog_content = "Sin objeciones...",
  ui_story_5084_50840301_47_dialog_content = "¿Cambiaría algo una objeción en este punto?",
  ui_story_5084_50840301_48_dialog_content = "Hmph.",
  ui_story_5084_50840301_49_dialog_content = "Continúa. El Señor de la Verdad ya no puede esperar más.",
  ui_story_5084_50840301_50_dialog_content = "No tengas miedo, Victoria Varaki.",
  ui_story_5084_50840301_51_dialog_content = "Te escoltaré personalmente al templo y te colocaré en ese sagrado ataúd.",
  ui_story_5084_50840301_52_dialog_content = "Afianza tu corazón y mente, y prepárate para compartir tu conocimiento de la Verdad con nuestro señor.",
  ui_story_5084_50840301_53_dialog_content = "...",
  ui_story_5084_50840301_54_dialog_content = "(Escuché a alguien en la calle decir que el Iniciado tenía que \"sacrificarse\"... ¿De qué trata exactamente esta ceremonia...?)",
  ui_story_5084_50840301_55_dialog_content = "(Siento un grave peligro proveniente de estos jefes de familias...)",
  ui_story_5084_50840301_56_dialog_content = "(¿Qué pasará si Victoria realmente se sacrifica?!)",
  ui_story_5084_50840301_57_dialog_content = "(De ninguna manera, tengo que hacer algo antes de que Victoria entre en ese ataúd...)",
  ui_story_5084_50840301_58_option_content = "Enlace Telepático",
  ui_story_5084_50840301_59_dialog_content = "Finalmente te pusiste al día.",
  ui_story_5084_50840301_60_dialog_content = "Algo no parece correcto aquí, Victoria... ¿Vas a dejar que este tipo te meta en el ataúd y te sacrifique?!",
  ui_story_5084_50840301_61_dialog_content = "Sí.",
  ui_story_5084_50840301_62_dialog_content = "¿E-Entonces... Qué debemos hacer May y yo?!",
  ui_story_5084_50840301_63_dialog_content = "¿Recuerdas las palabras de Sikare?",
  ui_story_5084_50840301_64_dialog_content = "¡Por supuesto que sí! \"El destino ha sido determinado desde hace mucho tiempo. No hay lugar para cuestionarlo, resentirlo o cambiarlo.\"",
  ui_story_5084_50840301_65_dialog_content = "No hay duda...",
  ui_story_5084_50840301_66_dialog_content = "Parece que lo entiendes ahora.",
  ui_story_5084_50840301_67_dialog_content = "Parece que te has separado de todos los demás, Caelestite.",
  ui_story_5084_50840301_68_dialog_content = "Y a pesar de la advertencia de Sikare, tu mente está llena de preguntas y dudas.",
  ui_story_5084_50840301_69_dialog_content = "Creo que es bastante normal cuestionar la situación actual...",
  ui_story_5084_50840301_70_dialog_content = "Simplemente sigue tu intuición y presencia cómo se despliega el pasado conmigo.",
  ui_story_5084_50840301_71_dialog_content = "Victoria!",
  ui_story_5084_50840301_72_dialog_content = "Ahora...",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>¡¡Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_74_dialog_content = "¡Entra en el ataúd!",
  ui_story_5084_50840301_75_dialog_content = "...",
  ui_story_5084_50840301_76_dialog_content = "¿Viento...? ¿De verdad la Lady Victoria va a acostarse ahí dentro?",
  ui_story_5084_50840301_77_option_content = "Enlace Telepático",
  ui_story_5084_50840301_78_dialog_content = "(Se siente como si algo me estuviera bloqueando...)",
  ui_story_5084_50840301_79_dialog_content = "Jaja...",
  ui_story_5084_50840301_80_dialog_content = "Jaja... Jajajaja...",
  ui_story_5084_50840301_81_dialog_content = "Jajajaja... Jajajajaja...",
  ui_story_5084_50840301_82_dialog_content = "(Esas son algunas risas espeluznantes... ¿Qué demonios están tramando?)",
  ui_story_5084_50840301_83_dialog_content = "Jajajajajajaja...",
  ui_story_5084_50840301_84_dialog_content = "(Incluso ese tal Wilhelm se está uniendo...)",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_86_dialog_content = "¿PlayerName?",
  ui_story_5084_50840301_87_dialog_content = "¡No te preocupes, May! ¡Estoy justo aquí!",
  ui_story_5084_50840301_88_dialog_content = "¡¿Qué...?!",
  ui_story_5084_50840301_89_dialog_content = "Parece que ese viento negro de hace un momento apagó mi vela... ¡No puedo ver nada aquí dentro!",
  ui_story_5084_50840301_90_dialog_content = "La forma en que esas personas se estaban riendo era tan perturbadora... ¿Estaban todos en liga entre ellos?",
  ui_story_5084_50840301_91_dialog_content = "Por no mencionar todas las cosas que ese tipo Wilhelm dijo sobre Victoria...",
  ui_story_5084_50840301_92_dialog_content = "¿Ella no está en peligro, verdad? No... ¡Tengo que saber de qué se estaban riendo!",
  ui_story_5084_50840301_93_option_content = "(Impulso de la fuerza—)",
  ui_story_5084_50840301_94_dialog_content = "(Yo... Apenas puedo entender algo... ¿Qué está pasando aquí...?)",
  ui_story_5084_50840301_95_dialog_content = "¿Ha pasado factura la dirección de la True Order después de todos estos años, Wilhelm Varaki?",
  ui_story_5084_50840301_96_dialog_content = "Sabes exactamente lo que significa para una persona entrar a ese ataúd. Seguramente tienes un motivo oculto para elegir a la hija de <color=#FFB400>Osten Varaki</color>, ¿verdad?",
  ui_story_5084_50840301_97_dialog_content = "Él era el líder anterior de la True Order y mi hermano mayor. Naturalmente, cuidar de su preciosa hija es mi responsabilidad.",
  ui_story_5084_50840301_98_dialog_content = "(Espera, entonces Wilhelm... ¿Es el tío de Victoria?)",
  ui_story_5084_50840301_99_dialog_content = "Me canso de tus palabras vanidosas, Varaki.",
  ui_story_5084_50840301_100_dialog_content = "Soy muy consciente de que aún no has encontrado una solución.",
  ui_story_5084_50840301_101_dialog_content = "Si realmente tienes sus mejores intereses en el corazón, ¿por qué no te unes a ella allí...?",
  ui_story_5084_50840301_102_dialog_content = "Espera—",
  ui_story_5084_50840301_103_dialog_content = "¿Qué crees que estás haciendo, Wilhelm? Esto no es nada como dijiste que sería.",
  ui_story_5084_50840301_104_dialog_content = "De hecho no lo es, Clavis. Sin embargo, ya has tomado tu decisión.",
  ui_story_5084_50840301_105_dialog_content = "...",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_107_dialog_content = "(Oh no... Parece que este viento negro estaba destinado a ocultarlo todo desde el principio...)",
  ui_story_5084_50840301_108_dialog_content = "(Clavis, Wilhelm y Victoria... ¿Qué están planeando?)",
  ui_story_5084_50840301_109_dialog_content = "Ugh, deja de agarrarme tan fuerte, PlayerName! Vas a partirme el brazo por la mitad...",
  ui_story_5084_50840301_110_dialog_content = "Oh, lo siento...",
  ui_story_5084_50840301_111_dialog_content = "¡Ahí, eso está mucho mejor!",
  ui_story_5084_50840301_112_dialog_content = "Tengo que pensar en algo... Pero ¿qué puedo hacer realmente...?",
  ui_story_5084_50840301_113_dialog_content = "¿Y qué está pasando entre Victoria y su tío? ¿Por qué sacrificaría a su propia sobrina...?",
  ui_story_5084_50840301_114_dialog_content = "¿Estás intentando idear un plan, PlayerName? La llama de la vela está parpadeando... Mira, la escena está empezando a cambiar.",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>Pozo-pat, pozo-pat...</color>",
  ui_story_5084_50840401_2_dialog_content = "¡Ese sonido...!",
  ui_story_5084_50840401_3_dialog_content = "¿Miau?",
  ui_story_5084_50840401_4_dialog_content = "¡No te asustes, Bebe! ¡Estoy justo aquí!",
  ui_story_5084_50840401_5_dialog_content = "Gracias a Dios que todavía están allí. Por un segundo pensé que estaba solo de nuevo.",
  ui_story_5084_50840401_6_dialog_content = "Parece que terminamos en un lugar nuevo. Algo huele bien, también. ¿Es el olor de la ropa limpia...?",
  ui_story_5084_50840401_7_dialog_content = "¿Ah?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5084_50840401_9_dialog_content = "¡A-Alguien está aquí!",
  ui_story_5084_50840401_10_dialog_content = "Mmph... ¡Oye, no me tapes mi... Mmph!",
  ui_story_5084_50840401_11_dialog_content = "... Hmph. Llevé esta ropa ayer, lo que la convierte en historia antigua ahora.",
  ui_story_5084_50840401_12_dialog_content = "¡Y esta tela se siente como papel de lija en mi piel! Soy un artista, no un simple carpintero...",
  ui_story_5084_50840401_13_dialog_content = "En cuanto a este... El color es tan lamentablemente carente de imaginación... Un verdadero artista nunca podría resignarse a usar colores tan apagados.",
  ui_story_5084_50840401_14_dialog_content = "¡Bah! ¿Estos fueron hechos en una tienda de ropa para niños?! ¡Soy más que suficientemente mayor para usar ropa de adulto!",
  ui_story_5084_50840401_15_dialog_content = "¡Maldita sea—! ¡Nunca debí haber tomado en serio las palabras de Papá!",
  ui_story_5084_50840401_16_dialog_content = "¡Ese dúo de tontos nunca podría diseñar ropa formal para el gran Charon!",
  ui_story_5084_50840401_17_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5084_50840401_18_dialog_content = "¿...?",
  ui_story_5084_50840401_19_dialog_content = "¿¡Ch-Charon?!?",
  ui_story_5084_50840401_20_dialog_content = "Espera... ¿no puede vernos?",
  ui_story_5084_50840401_21_dialog_content = "Huff, huff... ¡P-Por fin, me has soltado! ¿Conoces a este niño, PlayerName?",
  ui_story_5084_50840401_22_dialog_content = "Sí... Ese cabello y esas expresiones... No hay forma de confundir \"el gran Charon\" con nadie más!",
  ui_story_5084_50840401_23_dialog_content = "Estaba parado justo en frente de nosotros hace un momento, ¿no es así?",
  ui_story_5084_50840401_24_dialog_content = "Sí, y parece que estaba eligiendo un atuendo. Mmm... ¡Estas ropas de buen olor realmente son algo más! Nunca podría armar algo tan bueno como esto...",
  ui_story_5084_50840401_25_dialog_content = "Así que estamos en el armario de Charon... Pero por cómo se ve, apenas tiene más de diez años...",
  ui_story_5084_50840401_26_dialog_content = "De nuevo... Nunca he podido adivinar la edad de ese tipo. Supongo que realmente no importa, ya que estamos en el pasado en este momento.",
  ui_story_5084_50840401_27_dialog_content = "Espera... De vuelta en el Advenimiento de la Verdad, Victoria dijo que estamos en el año 1915, lo que significa...",
  ui_story_5084_50840401_28_dialog_content = "¿Y qué pasa con esta vela de todos modos? Me envía a un lugar diferente cada vez que empieza a parpadear, y esta vez también te trajo a ti, May!",
  ui_story_5084_50840401_29_dialog_content = "¡Eres tan tonto, PlayerName! Obviamente, solo sucedió porque estás sosteniendo esa vela en una mano y a Bebe en la otra!",
  ui_story_5084_50840401_30_dialog_content = "Sikare tiene a su disposición todo tipo de objetos mágicos y poderosos. Pero si no crees en la magia, entonces no hay mucho más que decir.",
  ui_story_5084_50840401_31_dialog_content = "...? ¿No estás preocupado o incluso curioso por todas las cosas que acabamos de ver?",
  ui_story_5084_50840401_32_dialog_content = "¿Te refieres al tipo de curiosidad feliz, o al tipo asustado?",
  ui_story_5084_50840401_33_dialog_content = "Ah, ¿qué importa? ¡Me gustan ambos! ¡Jajaja!",
  ui_story_5084_50840401_34_dialog_content = "Entonces, ¿es esta vela la razón por la que Charon no pudo vernos ni oírnos...?",
  ui_story_5084_50840401_35_dialog_content = "Lo mismo ocurrió en el Templo de la Verdad... Solo el Victoria del presente pudo vernos.",
  ui_story_5084_50840401_36_dialog_content = "¡Es como un objeto de una de esas historias! ¡El tipo que puede otorgar invisibilidad!",
  ui_story_5084_50840401_37_dialog_content = "¡Jajaja, no es broma!",
  ui_story_5084_50840401_38_dialog_content = "No sabemos qué le pasó a Victoria después de que entró en ese ataúd, o dónde están Nails y Faust ahora mismo...",
  ui_story_5084_50840401_39_dialog_content = "¿Realmente vinimos aquí siguiendo la guía de nuestros corazones...?",
  ui_story_5084_50840401_40_dialog_content = "¿En qué estabas pensando antes?",
  ui_story_5084_50840401_41_dialog_content = "¿Te refieres a cuando la luz de la vela comenzó a parpadear? Era algo como...",
  ui_story_5084_50840401_42_dialog_content = "\"Clavis, Wilhelm y Victoria... ¿Qué están planeando?\"",
  ui_story_5084_50840401_43_dialog_content = "Si el padre de Charon y ese \"dúo de tontos\" son los tres...",
  ui_story_5084_50840401_44_dialog_content = "¡Quizás esto es lo que Sikare quiso decir cuando dijo que la vela sería mi guía!",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5084_50840401_46_dialog_content = "Hago esto solo para preservar la naturaleza imparcial de mi arte. Estos calcetines son mis mayores tesoros, pero los cambiaré a regañadientes por su bien.",
  ui_story_5084_50840401_47_dialog_content = "(Charon es tan serio cuando se trata de cambiar su ropa...)",
  ui_story_5084_50840401_48_dialog_content = "\"Oh Señor Charon, ¿dónde encuentras para comprar calcetines tan hipnóticamente magníficos?\"",
  ui_story_5084_50840401_49_dialog_content = "\"Nadie podría igualar tus gustos, Señor Charon...\"",
  ui_story_5084_50840401_50_dialog_content = "Hmph, ¿así que esto es ser famoso? Una existencia tan problemática...",
  ui_story_5084_50840401_51_dialog_content = "<color=#828282>¡Golpe!</color>",
  ui_story_5084_50840401_52_dialog_content = "...",
  ui_story_5084_50840401_53_dialog_content = "Ha sido diferente a todos desde que era un niño, ¿eh...",
  ui_story_5084_50840401_54_dialog_content = "Vamos a echar un vistazo, May. ¡Pero no te alejes demasiado de mí!",
  ui_story_5084_50840401_55_dialog_content = "¡Sé que sé!",
  ui_story_5084_50840401_56_dialog_content = "Mucho tiempo sin verte, Clavis.",
  ui_story_5084_50840401_57_dialog_content = "Hola, tío Clavis.",
  ui_story_5084_50840401_58_dialog_content = "¡Es la Dama Victoria! ¡Oye...",
  ui_story_5084_50840401_59_dialog_content = "¡Cálmate, May! Aunque ella no está respondiendo, estoy seguro de que ya nos notó desde esta distancia. ¿Esto debe ser otra versión de su yo pasado, verdad?",
  ui_story_5084_50840401_60_dialog_content = "Aunque no parece muy diferente de la Victoria que conocemos en el presente...",
  ui_story_5084_50840401_61_dialog_content = "Eso es porque ella es un miembro noble de la familia de sangre! Una vez que despertó su poder, el proceso de envejecimiento se detuvo para ella.",
  ui_story_5084_50840401_62_dialog_content = "¿Y por qué sigues escondiéndote si la gente del pasado no puede vernos, PlayerName?",
  ui_story_5084_50840401_63_dialog_content = "¿Eh?! Oh sí... ¿Quizás es porque todo y todos aquí se ven un poco aterradores?",
  ui_story_5084_50840401_64_dialog_content = "Jaja... Verlos a ambos aquí al mismo tiempo es una vista bastante rara.",
  ui_story_5084_50840401_65_dialog_content = "Mmm...",
  ui_story_5084_50840401_66_dialog_content = "¿Dónde está el joven Charon?!?",
  ui_story_5084_50840401_67_dialog_content = "Oh, tú conoces a ese chico. Tan pronto como sabe que esperamos compañía, pasa horas arreglándose...",
  ui_story_5084_50840401_68_dialog_content = "...",
  ui_story_5084_50840401_69_dialog_content = "Oye, Señor Charon. Bonitos calcetines los que tienes ahí.",
  ui_story_5084_50840401_70_dialog_content = "D-Di lo que quieras, aún así no lo haré...",
  ui_story_5084_50840401_71_dialog_content = "Cuida tus modales, Charon.",
  ui_story_5084_50840401_72_dialog_content = "... Hola, tío Wilhelm.",
  ui_story_5084_50840401_73_dialog_content = "¿No estás olvidando a alguien? Esta es Victoria, la sobrina de tu tío Wilhelm.",
  ui_story_5084_50840401_74_dialog_content = "Hola, prima.",
  ui_story_5084_50840401_75_dialog_content = "... Hola, prima.",
  ui_story_5084_50840401_76_dialog_content = "Charon, ¿por qué no llevas a Victoria a la otra habitación y tomas un té y postres?",
  ui_story_5084_50840401_77_dialog_content = "... Si padre.",
  ui_story_5084_50840401_78_dialog_content = "Me sorprende que tengas tiempo para visitarnos aquí en Old Town. ¿Están más o menos resueltos los asuntos en la ciudad de Varaki?",
  ui_story_5084_50840401_79_dialog_content = "Venir aquí no fue nada fácil, pero sabes que viajaría cualquier distancia para verte, Clavis.",
  ui_story_5084_50840401_80_dialog_content = "...",
  ui_story_5084_50840401_81_dialog_content = "...",
  ui_story_5084_50840401_82_dialog_content = "¿Cuánto tiempo vas a seguir mirándome?",
  ui_story_5084_50840401_83_dialog_content = "¿Estás en liga con el resto de esas personas miserables?",
  ui_story_5084_50840401_84_dialog_content = "¿Qué personas miserables, exactamente?",
  ui_story_5084_50840401_85_dialog_content = "Sabes, esos sectarios que son justo como Wilhelm Varaki.",
  ui_story_5084_50840401_86_dialog_content = "Si te refieres a True Order, entonces no, no soy uno de ellos. También es bastante inapropiado referirse a su líder por su nombre completo, ¿no crees?",
  ui_story_5084_50840401_87_dialog_content = "Llámalo intuición de artista, pero nadie que se asocie con él está tramando algo bueno. Solo por insistencia de mi padre me presenté ante ti hoy.",
  ui_story_5084_50840401_88_dialog_content = "Dices que no puedes soportar al asociado de tu padre, y sin embargo te esforzaste tanto para hacerte presentable.",
  ui_story_5084_50840401_89_dialog_content = "...! ¡Todo es por el bien del arte!",
  ui_story_5084_50840401_90_dialog_content = "¿Oh? Entonces, ¿qué es exactamente el arte?",
  ui_story_5084_50840401_91_dialog_content = "¿Eres consciente de que todos debemos morir algún día, sí? Sin embargo, hay una cosa en este mundo que nunca puede morir; ¿sabes qué es eso?",
  ui_story_5084_50840401_92_dialog_content = "¡Es arte!",
  ui_story_5084_50840401_93_dialog_content = "¡El arte es una flor prohibida que puede florecer en las profundidades del infierno! Un tren imparable que surge de las aguas del río Styx.",
  ui_story_5084_50840401_94_dialog_content = "Y me convertiré en su conductor, un barquero de almas y una obra de arte eterna.",
  ui_story_5084_50840401_95_dialog_content = "Una obra de arte eterna, dices... Jeje, parece que estoy destinado a convertirme en tu pasajero algún día.",
  ui_story_5084_50840401_96_dialog_content = "¡Pero por supuesto! No, espera... Desde que esos malditos tontos se burlaron de mi arte...",
  ui_story_5084_50840401_97_dialog_content = "Un niño de esta edad no debería estar tan obsesionado con los urinarios...",
  ui_story_5084_50840401_98_dialog_content = "... Como un hombre que está demasiado sumergido en sus copas, su frivolidad descuidada es casi divertida.",
  ui_story_5084_50840401_99_dialog_content = "Desde aquel día, decidí que solo aquellos que aprecian mi arte pueden abordar mi tren...",
  ui_story_5084_50840401_100_dialog_content = "Me niego a aceptar a cualquiera que haya vivido demasiado tiempo, se comporte demasiado grosero o no tenga gusto por el arte.",
  ui_story_5084_50840401_101_dialog_content = "Estás bastante seguro de ti mismo, Charon.",
  ui_story_5084_50840401_102_dialog_content = "Eso es solo natural, ya que nadie más en el Viejo Pueblo tiene gustos que rivalizan con los míos.",
  ui_story_5084_50840401_103_dialog_content = "Y algún día, estableceré mi propia compañía de teatro, así como grupos para apreciar cosas como la música, el arte y los trenes a escala...",
  ui_story_5084_50840401_104_dialog_content = "No me importa decírtelo, ya que hace tiempo descubrí la llamada \"verdad\" de la que esos tontos siempre están parloteando. Es arte, simple y llanamente.",
  ui_story_5084_50840401_105_dialog_content = "¿Bueno? Como no has encontrado una organización a la que unirte, ¿eres lo suficientemente valiente para enfrentarte a mi proceso de admisión?",
  ui_story_5084_50840401_106_dialog_content = "Jejeje, interesante. ¿Y qué exactamente es este \"proceso de admisión\" tuyo?",
  ui_story_5084_50840401_107_dialog_content = "Es realmente simple. Cuando veas pasar mi tren, moviliza todos tus sentidos y entra en mi mundo del arte. Después, también tendrás que demostrar tu comprensión del arte.",
  ui_story_5084_50840401_108_dialog_content = "Muy bien, acepto.",
  ui_story_5084_50840401_109_dialog_content = "Entonces solo espera allí. A Papá no le agrada que muestre estas cosas a otras personas.",
  ui_story_5084_50840401_110_dialog_content = "¡Ahora deleita tus ojos con la actuación de un conductor y presencia el verdadero significado del arte!",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>Momentos después...</color>",
  ui_story_5084_50840401_112_dialog_content = "¡Escucha atentamente! ¡Las vías del tren resuenan con los gritos del apocalipsis!",
  ui_story_5084_50840401_113_dialog_content = "¡Presencia el último tren partiendo de un mundo moribundo y hacia la eternidad! ",
  ui_story_5084_50840401_114_dialog_content = "¡Solo los artistas que aspiran a la inmortalidad pueden abordarlo y viajar más allá de los gloriosos cielos! ",
  ui_story_5084_50840401_115_dialog_content = "Liberado de las cadenas que aprisionaban su cuerpo, sus ruedas desatadas giran sin cesar mientras sigue adelante por siempre!",
  ui_story_5084_50840401_116_dialog_content = "El motor apunta hacia el cielo y yo, el gran Charon, soy su conductor! ¡Juntos, escaparemos de este abismo maldito!",
  ui_story_5084_50840401_117_dialog_content = "¡Ordenaré al mismísimo infierno que abra sus puertas y deje entrar la luz de un nuevo mundo!",
  ui_story_5084_50840401_118_dialog_content = "Vaya... Creo que en realidad veo un tren en la oscuridad...",
  ui_story_5084_50840401_119_dialog_content = "Eso es Charon para ti... No importa a dónde vaya, el mundo es su escenario...",
  ui_story_5084_50840401_120_dialog_content = "¡Ka-chunk, ka-chunk, ka-chunk—! ¡Escucha la sinfonía de mundos viejos y nuevos mientras escapa de mi boca! ¡No temas al sonido!",
  ui_story_5084_50840401_121_dialog_content = "¡Ahora conduce! ¡Conduce hasta que atravesemos las puertas del nuevo mundo! ¡Nos espera un paraíso inmortal!",
  ui_story_5084_50840401_122_dialog_content = "...",
  ui_story_5084_50840401_123_dialog_content = "¡Es tu turno ahora, primo!",
  ui_story_5084_50840401_124_dialog_content = "Jeje, ciertamente tienes un talento para lo dramático, pero esta \"puerta a un nuevo mundo\" no es más que una ilusión!",
  ui_story_5084_50840401_125_dialog_content = "La \"puerta\" que buscas tan desesperadamente es más como una pared sin forma que se estrellará violentamente contra tu cara!",
  ui_story_5084_50840401_126_dialog_content = "Las vías del tren se encenderán, y este gigante rojo y dorado quemará tus sueños hasta convertirlos en cenizas.",
  ui_story_5084_50840401_127_dialog_content = "¡La muerte es la Verdad absoluta! ¡Se debe ofrecer un preludio al final como tributo! ¡La inmortalidad no es más que miedo y pánico interminables!",
  ui_story_5084_50840401_128_dialog_content = "El miedo te aplastará hasta convertirte en un insecto insignificante y te atrapará en la jaula de la eternidad sin esperanza de escape.",
  ui_story_5084_50840401_129_dialog_content = "¡Un juguete indefenso para ser observado y atormentado por seres aún superiores!",
  ui_story_5084_50840401_130_dialog_content = "¡Mira arriba!",
  ui_story_5084_50840401_131_dialog_content = "¡Esta es la realidad del nuevo mundo—Un ciclo interminable de manipulación!",
  ui_story_5084_50840401_132_dialog_content = "¡...!",
  ui_story_5084_50840401_133_dialog_content = "En los ojos de nuestros señores ocultos, tu locura solo sirve para su diversión.",
  ui_story_5084_50840401_134_dialog_content = "¡El poder de inspirar miedo es verdadero arte!",
  ui_story_5084_50840401_135_dialog_content = "... ¡Waaaahhhh!",
  ui_story_5084_50840401_136_dialog_content = "... Primo, tú—!",
  ui_story_5084_50840401_137_dialog_content = "Esto es mucho más emocionante que el arte eterno, ¿no es así?",
  ui_story_5084_50840401_138_dialog_content = "¡Jajajajajajajaja...!",
  ui_story_5084_50840401_139_dialog_content = "... ¡¡¡Waaaahhhh!!!",
  ui_story_5084_50840401_140_dialog_content = "¡M-Mi tren... Deténgalo! ¡Deténgalo ahora mismo!",
  ui_story_5084_50840401_141_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840401_142_dialog_content = "No tenía idea de que la Dama Victoria tenía un primo pequeño tan gracioso.",
  ui_story_5084_50840401_143_dialog_content = "¿Eh? Creo que te estás perdiendo el verdadero problema aquí... ¿Cómo podría Victoria ser tan malo con Charon?!",
  ui_story_5084_50840401_144_dialog_content = "No es de extrañar que siempre sea reacio a hablar de Victoria como su pariente... ¿Qué tipo de arte es este?!",
  ui_story_5084_50840401_145_dialog_content = "No puedo estar de acuerdo con eso, Wilhelm...",
  ui_story_5084_50840401_146_dialog_content = "¿De qué tienes tanto miedo, Clavis? ¿O realmente no ves el empeoramiento de nuestra situación?",
  ui_story_5084_50840401_147_dialog_content = "Porfirio y los gobernantes de la casa dejaron de seguir las reglas después de ramificarse de la línea de sangre Varaki.",
  ui_story_5084_50840401_148_dialog_content = "No salvarás a nadie de esta manera.",
  ui_story_5084_50840401_149_dialog_content = "¡Pero en su estado actual, el True Order no es más que una plaga para nosotros y para la gente de esta ciudad! ¡Los preceptos de las familias de sangre nos encarcelan a todos!",
  ui_story_5084_50840401_150_dialog_content = "La sed de sangre está en nuestra naturaleza, Wilhelm... En nuestra propia sangre. Y aunque tú y yo somos un poco más afortunados que el resto, no somos diferentes en este aspecto.",
  ui_story_5084_50840401_151_dialog_content = "¿Nuestra naturaleza, dices...? ¿Cuándo empezaste a preocuparte por este tipo de conversación, Clavis?",
  ui_story_5084_50840401_152_dialog_content = "No me culpes por esto, Wilhelm. Simplemente no puedo negar lo que sé que es verdad...",
  ui_story_5084_50840401_153_dialog_content = "Esa <color=#FFB400>llave</color> solo te traerá daño.",
  ui_story_5084_50840401_154_dialog_content = "Justo antes de morir, mi hermano lo recuperó de los <color=#FFB400>Vinekeepers</color> y te lo dio... Claramente, era para asegurarse de que la llave llegaría a mis manos algún día.",
  ui_story_5084_50840401_155_dialog_content = "... O quizás fue para evitar que tú mismo lo tomaras a la fuerza de los <color=#FFB400>Vinekeepers</color>.",
  ui_story_5084_50840401_156_dialog_content = "A pesar de tus métodos poco ortodoxos, ya has liderado la True Order como sucesor de tu hermano durante muchos años.",
  ui_story_5084_50840401_157_dialog_content = "Todo lo que ha sucedido fue predicho en una antigua profecía.",
  ui_story_5084_50840401_158_dialog_content = "El curso del destino no puede ser alterado. Tú lo sabes mejor que yo.",
  ui_story_5084_50840401_159_dialog_content = "¡No! ¡Me niego a aceptarlo!",
  ui_story_5084_50840401_160_dialog_content = "Pongo mi fe en el Señor de la Verdad; ¡el destino de los Varaki no me preocupa! Al menos, me niego a aceptar este llamado \"curso del destino...\"",
  ui_story_5084_50840401_161_dialog_content = "No importa lo que me suceda, lo soportaré. Debo hacerlo.",
  ui_story_5084_50840401_162_dialog_content = "Desde el principio, solo he seguido la guía de mi corazón. Para mí, eso es La Verdad.",
  ui_story_5084_50840401_163_dialog_content = "¿Y qué pasa con Victoria? Tu hermano te confió a ella...",
  ui_story_5084_50840401_164_dialog_content = "No hay necesidad de mencionarla, Clavis.",
  ui_story_5084_50840401_165_dialog_content = "El desprecio de Victoria por nuestro poder y su indiferencia hacia los asuntos de la ciudad de Varaki son incluso mayores que los míos. Ella puede cuidarse a sí misma.",
  ui_story_5084_50840401_166_dialog_content = "Jeje... Quizás esto también sea un castigo por las acciones de mi hermano.",
  ui_story_5084_50840401_167_dialog_content = "Wilhelm...",
  ui_story_5084_50840401_168_dialog_content = "En cualquier caso... Por favor, cuida bien a tu familia, Clavis.",
  ui_story_5084_50840401_169_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_170_dialog_content = "...",
  ui_story_5084_50840401_171_dialog_content = "Es hora de que nos vayamos, Victoria Varaki.",
  ui_story_5084_50840401_172_dialog_content = "...",
  ui_story_5084_50840401_173_dialog_content = "¿Ya? Pero aún no he aprendido nada... Tengo que encontrar una manera de alcanzarlos... ¡Espera, eso es! Solo tengo que concentrarme, y...",
  ui_story_5084_50840401_174_dialog_content = "¡Está funcionando! ¡La vela está empezando a parpadear! ¡Apresúrate—",
  ui_story_5084_50840401_175_dialog_content = "Seca tus lágrimas, Charon...",
  ui_story_5084_50840401_176_dialog_content = "Maldígala... ¡Maldiga a esa loca...!",
  ui_story_5084_50840401_177_dialog_content = "¡Basta! Ahora, recoge todos esos pedazos rotos!",
  ui_story_5084_50840401_178_dialog_content = "... Olfatea...",
  ui_story_5084_50840501_1_dialog_content = "Creo que ya le he cogido el truco. Cuando la vela empezó a parpadear, me pregunté qué estaría pensando Wilhelm.",
  ui_story_5084_50840501_2_dialog_content = "¿Entonces eso significa... Estamos en la casa del Señor Wilhelm ahora?",
  ui_story_5084_50840501_3_dialog_content = "¡Es él! ¡Lord Wilhelm!",
  ui_story_5084_50840501_4_dialog_content = "Se ve muy triste sosteniendo ese anillo...",
  ui_story_5084_50840501_5_dialog_content = "Aunque todavía no sabemos lo que realmente está pensando.",
  ui_story_5084_50840501_6_dialog_content = "Eres el legendario Último Caelestite, ¿verdad? ¡Solo escucha sus pensamientos ya!",
  ui_story_5084_50840501_7_dialog_content = "¡D-No lo llames \"escuchar a escondidas\"! ¡Eso no es para lo que sirven mis poderes!",
  ui_story_5084_50840501_8_dialog_content = "Bueno, ¿cómo se supone que debemos averiguar qué está tramando?!",
  ui_story_5084_50840501_9_dialog_content = "...",
  ui_story_5084_50840501_10_dialog_content = "¡Deja de perder el tiempo! Como adulto, necesitas ser más decisivo!",
  ui_story_5084_50840501_11_dialog_content = "¡Bien! Estoy bastante seguro de que no va en contra de las reglas de Sikare si solo leo un poco sus pensamientos...",
  ui_story_5084_50840501_12_option_content = "Enlace mental—",
  ui_story_5084_50840501_13_dialog_content = "Los susurros atrapados dentro de esta reliquia... Simplemente al usarla, experimentaré el dolor de ser devorado innumerables veces en un instante...",
  ui_story_5084_50840501_14_dialog_content = "Los Varaki... Y el resto de la familia de sangre... ¿Realmente podemos escapar de nuestro destino...?",
  ui_story_5084_50840501_15_dialog_content = "Nacidos como Aurorianos pero condenados a vivir en este oscuro y sin sol pueblo, donde el poder solo puede ser transmitido a través de la herencia.",
  ui_story_5084_50840501_16_dialog_content = "Bajo la guía de nuestros ancestros, corremos, nos escondemos y llevamos vidas que no son mejores que la muerte...",
  ui_story_5084_50840501_17_dialog_content = "La voluntad de nuestros antepasados... La sucesión del poder... Qué absolutamente sin sentido. Los Varaki abandonarán a nuestras futuras generaciones antes de ceder cualquier control.",
  ui_story_5084_50840501_18_dialog_content = "Y aunque hemos aprendido a subsistir con sustitutos de sangre, no hay forma de deshacernos de la fuente de nuestro malvado poder.",
  ui_story_5084_50840501_19_dialog_content = "(¿Sustitutos de sangre... El \"néctar de la vida\" del que Victoria sigue hablando... Podría ser...?)",
  ui_story_5084_50840501_20_dialog_content = "Maldito este anillo infernal...",
  ui_story_5084_50840501_21_dialog_content = "Maldita sea todo...",
  ui_story_5084_50840501_22_dialog_content = "Con cada año que pasa, los jefes de las familias se vuelven más hambrientos de sangre fresca...",
  ui_story_5084_50840501_23_dialog_content = "Suspiro, Clavis... Han pasado tres años desde la última vez que hablamos. ¿Me pregunto cómo le estará yendo estos días?",
  ui_story_5084_50840501_24_dialog_content = "(Han pasado tres años desde que Wilhelm y Victoria visitaron al papá de Charon? Espera... ¿Entonces qué año es ahora?)",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5084_50840501_26_dialog_content = "...",
  ui_story_5084_50840501_27_dialog_content = "Es Victoria...",
  ui_story_5084_50840501_28_dialog_content = "Pero esa presencia... Parece que sigue siendo la versión pasada de ella.",
  ui_story_5084_50840501_29_dialog_content = "¡Es la Dama Victoria del pasado otra vez! Entonces, ¿has escuchado algo importante justo ahora?",
  ui_story_5084_50840501_30_dialog_content = "Wilhelm guardó el anillo tan pronto como Victoria entró en la habitación. Ahora siento como si algo estuviera bloqueando mis poderes...",
  ui_story_5084_50840501_31_dialog_content = "¿Así que ya no puedes leer sus pensamientos?",
  ui_story_5084_50840501_32_dialog_content = "Así es... Creo que ese anillo está sometiendo su psique a una enorme tensión. Solo veamos qué tienen que decir esta vez.",
  ui_story_5084_50840501_33_dialog_content = "Oh...",
  ui_story_5084_50840501_34_dialog_content = "Bienvenido de nuevo... Te fuiste por tres meses esta vez. ¿Cómo te fue?",
  ui_story_5084_50840501_35_dialog_content = "... Eso no es asunto tuyo.",
  ui_story_5084_50840501_36_dialog_content = "La mirada en tus ojos... Tan llena de resentimiento e incertidumbre...",
  ui_story_5084_50840501_37_dialog_content = "¿Qué viste en el mundo exterior, Wilhelm Varaki?",
  ui_story_5084_50840501_38_dialog_content = "No recuerdo haberte permitido entrar a mi habitación.",
  ui_story_5084_50840501_39_dialog_content = "Eres el líder de True Order, y sin embargo, regularmente te vas sin cumplir tus deberes... También has estado pasando menos tiempo en casa.",
  ui_story_5084_50840501_40_dialog_content = "¿Cuántas veces debo decirte que eso no es asunto tuyo?! ¡Ahora déjame!",
  ui_story_5084_50840501_41_dialog_content = "Muy bien entonces; No soy ajeno a que se me niegue tu conversación. Pero dado que esta noche es la Venida de la Verdad, esperaba que pudiéramos tener una última discusión.",
  ui_story_5084_50840501_42_dialog_content = "Sobre La Verdad, y nosotros mismos...",
  ui_story_5084_50840501_43_dialog_content = "¡Dije que te vayas! ¡No me hagas repetirme!",
  ui_story_5084_50840501_44_dialog_content = "...",
  ui_story_5084_50840501_45_dialog_content = "El Señor Wilhelm es tan hostil ahora... ¿Qué podría haberle sucedido...?",
  ui_story_5084_50840501_46_dialog_content = "... Nngh... <size=45>¡Arrrgh...!</size>",
  ui_story_5084_50840501_47_dialog_content = "Algo anda mal con el Señor Wilhelm... ¡Rápido, haz algo!",
  ui_story_5084_50840501_48_dialog_content = "¿Es ese anillo...?",
  ui_story_5084_50840501_49_option_content = "Enlace mental—",
  ui_story_5084_50840501_50_dialog_content = "¡Jajajajaja! ¡Arráncale los dedos! ¡Rompe su bonito y pequeño cuello!",
  ui_story_5084_50840501_51_dialog_content = "Sé silencioso...",
  ui_story_5084_50840501_52_dialog_content = "Qué absolutamente tonto. En tu desesperación por mantener el poder, voluntariamente usas un anillo que te vuelve loco ante el verdadero líder de tu pueblo.",
  ui_story_5084_50840501_53_dialog_content = "¿Deseas terminar con su vida... o con la tuya?",
  ui_story_5084_50840501_54_dialog_content = "Jeje... Me volví insensible al dolor que me infligiste hace mucho tiempo...",
  ui_story_5084_50840501_55_dialog_content = "El Varaki será destruido en tus manos.",
  ui_story_5084_50840501_56_dialog_content = "Je... Si estoy destinado a la destrucción, entonces la True Order compartirá mi destino...",
  ui_story_5084_50840501_57_dialog_content = "Ha hecho muchas nuevas alianzas. Una vez que se erradique la línea de sangre de Varaki, nacerá de nuevo la True Order.",
  ui_story_5084_50840501_58_dialog_content = "Ella será la que acabe con los Varaki de una vez por todas.",
  ui_story_5084_50840501_59_dialog_content = "¿Incluyéndome a mí?",
  ui_story_5084_50840501_60_dialog_content = "Solo muriendo en sus manos realmente comenzarás a vivir...",
  ui_story_5084_50840501_61_dialog_content = "¿Te escuchas siquiera ahora mismo?",
  ui_story_5084_50840501_62_dialog_content = "¡Sí, y te estoy diciendo que mueras!!",
  ui_story_5084_50840501_63_dialog_content = "(Estas voces son aterradoras! Es como si estuvieran devorando la conciencia de Wilhelm...)",
  ui_story_5084_50840501_64_dialog_content = "(¿Podría ser que este anillo otorga a su portador un poder enorme a cambio de causarles un sufrimiento inmenso?)",
  ui_story_5084_50840501_65_dialog_content = "(Suena mucho a algo de True Order, eso es seguro...)",
  ui_story_5084_50840501_66_dialog_content = "(Y ¿de quién son esas voces? ¿Los antepasados Varaki? ¿El dueño original del anillo? ¿O tal vez...)",
  ui_story_5084_50840501_67_dialog_content = "<size=45>Urgh... ¡Ahhhhhhhh!</size>",
  ui_story_5084_50840501_68_dialog_content = "Lucha contra el destino hasta que tu corazón esté satisfecho...",
  ui_story_5084_50840501_69_dialog_content = "¡Salir... Fuera!!!",
  ui_story_5084_50840501_70_dialog_content = "Conoce tus límites, tonto.",
  ui_story_5084_50840501_71_dialog_content = "Mi cuerpo... <size=45>¡¡¡Sal de mi cuerpo!!!</size>",
  ui_story_5084_50840501_72_dialog_content = "¡Señor de la Verdad...! ¡Muéstrame el camino!!!",
  ui_story_5084_50840501_73_dialog_content = "(¡Wilhelm está a punto de desmayarse!)",
  ui_story_5084_50840501_74_dialog_content = "(Estas voces se están convirtiendo en monstruos en su mente. ¡Podría ser capaz de hacer algo aquí!)",
  ui_story_5084_50840502_1_dialog_content = "¿Oh? Parece que has aprendido una nueva habilidad, Wilhelm...",
  ui_story_5084_50840502_2_dialog_content = "Tu mente... Tan tranquila y estable...",
  ui_story_5084_50840502_3_dialog_content = "...",
  ui_story_5084_50840502_4_dialog_content = "(Uh-oh! No me digas que me notaron...)",
  ui_story_5084_50840502_5_dialog_content = "Como recompensa, te dejaré ver algo interesante.",
  ui_story_5084_50840502_6_dialog_content = "May La Verdad lo bendiga.",
  ui_story_5084_50840502_7_dialog_content = "Finalmente... Otro gran logro ahora está completo.",
  ui_story_5084_50840502_8_dialog_content = "La sangre de un discípulo... Cómo he anhelado su sabor...",
  ui_story_5084_50840502_9_dialog_content = "¿Qué conocimiento obtuviste de La Verdad?",
  ui_story_5084_50840502_10_dialog_content = "La Verdad me mostró solo una cosa... Gratitud.",
  ui_story_5084_50840502_11_dialog_content = "Solo bajo la luz de una luna de sangre podemos realmente aplacar nuestra sed de sangre.",
  ui_story_5084_50840502_12_dialog_content = "Los fieles bailan salvajemente mientras rezan, ofreciendo sus cuerpos auto-castigados a un dios que nunca pueden comprender verdaderamente.",
  ui_story_5084_50840502_13_dialog_content = "Durante siglos... Han vivido de esta manera...",
  ui_story_5084_50840502_14_dialog_content = "Pero este delicioso sabor merece mucha más apreciación...",
  ui_story_5084_50840502_15_dialog_content = "¿Por qué no seleccionar unos cuantos discípulos más fieles para el Adviento de la Verdad de este año?",
  ui_story_5084_50840502_16_dialog_content = "¿Es este el conocimiento que obtuviste al consumir la sangre de este fiel servidor?",
  ui_story_5084_50840502_17_dialog_content = "No del todo.",
  ui_story_5084_50840502_18_dialog_content = "Cuando La Verdad fluye a través de sus cuerpos, consumimos su sangre para obtener este conocimiento y transmitirlo a las futuras generaciones.",
  ui_story_5084_50840502_19_dialog_content = "Este es el pacto entre nosotros, los jefes de familia, y los fieles.",
  ui_story_5084_50840502_20_dialog_content = "Tales sacrificios son inútiles si no nos permiten presenciar La Verdad.",
  ui_story_5084_50840502_21_dialog_content = "¿Te revelaron algo?",
  ui_story_5084_50840502_22_dialog_content = "Por supuesto.",
  ui_story_5084_50840502_23_dialog_content = "Permíteme recordarte nuestros principios y nuestra necesidad de secreto.",
  ui_story_5084_50840502_24_dialog_content = "Como jefes de familias, están obligados a mantenerlas. Bajo ninguna circunstancia se nos permite volver a nuestros viejos modos bárbaros.",
  ui_story_5084_50840502_25_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840502_26_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840502_27_dialog_content = "Estas visiones me fueron reveladas hace mucho tiempo, cuando se despertó el poder de mi linaje.",
  ui_story_5084_50840502_28_dialog_content = "Un antiguo ritual para la Venida de la Verdad, en el cual nuestros antepasados consumen completamente la sangre de un sacrificio para obtener inspiración divina.",
  ui_story_5084_50840502_29_dialog_content = "¿Espera... Esto significa que el Iniciado es devorado en cada Advenimiento de la Verdad?!",
  ui_story_5084_50840502_30_dialog_content = "¡No es de extrañar que se estuvieran riendo así antes!",
  ui_story_5084_50840502_31_dialog_content = "¿Realmente se sacrificó a Victoria de esta manera?!",
  ui_story_5084_50840502_32_dialog_content = "¿Hay alguien ahí...?",
  ui_story_5084_50840502_33_dialog_content = "¿Oh? Parece que tienes un visitante, Wilhelm.",
  ui_story_5084_50840502_34_dialog_content = "...",
  ui_story_5084_50840502_35_dialog_content = "Uh, PlayerName... ¿Qué hiciste? Lord Wilhelm no nos ve, ¿verdad?",
  ui_story_5084_50840502_36_dialog_content = "Lo siento... Debo haberme emocionado demasiado hace un momento...",
  ui_story_5084_50840502_37_dialog_content = "Pero vi algunas cosas realmente perturbadoras en la mente de Wilhelm...",
  ui_story_5084_50840502_38_dialog_content = "Todavía estoy bastante preocupado por Victoria, ¡así que lo intentaré de nuevo!",
  ui_story_5084_50840502_39_option_content = "Mindlink—",
  ui_story_5084_50840502_40_dialog_content = "¿Qué pasa con estos?",
  ui_story_5084_50840502_41_dialog_content = "Incluso después de ofrecer a tu propia sobrina, el Señor de la Verdad no te agració con ninguna revelación. ¿Tu propio fracaso finalmente te ha vuelto loco?",
  ui_story_5084_50840502_42_dialog_content = "No importa. Hace mucho que me cansé de tus juegos, Wilhelm.",
  ui_story_5084_50840502_43_dialog_content = "¡La Biblia Sangrienta es mía ahora! ¡La Verdad está a mi alcance!",
  ui_story_5084_50840502_44_dialog_content = "...! ¿Es esta una profecía...? El Advenimiento de la Verdad... Esta noche...",
  ui_story_5084_50840502_45_dialog_content = "(¡Es ese chico que vi en el templo antes! Están a punto de sacrificar a Victoria para el Advenimiento de la Verdad... ¡Lo que significa que estamos de vuelta en el año 1915!)",
  ui_story_5084_50840502_46_dialog_content = "¿Todavía no me crees?",
  ui_story_5084_50840502_47_dialog_content = "... ¿Es así como termina mi vida?",
  ui_story_5084_50840502_48_dialog_content = "Todavía no logras comprender el poder de los Varaki, sin embargo, condenarías a la familia de sangre a la muerte debido a tu propia desgracia.",
  ui_story_5084_50840502_49_dialog_content = "La juventud siempre desprecia el dogma de sus predecesores.",
  ui_story_5084_50840502_50_dialog_content = "Pero nunca fuiste el líder de True Order para empezar.",
  ui_story_5084_50840502_51_dialog_content = "Jejeje... Jajajaja...",
  ui_story_5084_50840502_52_dialog_content = "¿La Verdad? Qué absurdo...",
  ui_story_5084_50840502_53_dialog_content = "¿Pasaste tanto tiempo en la mano de mi hermano que heredaste su mal genio?",
  ui_story_5084_50840502_54_dialog_content = "Me maldijo al confiar en mí la familia y su hija... Y ahora Victoria, el verdadero líder de la orden, nos ha dejado...",
  ui_story_5084_50840502_55_dialog_content = "Se permitió ser engañado por una falsa visión del futuro, dejando que lo distorsionara y manipulara para los fines de otra persona.",
  ui_story_5084_50840502_56_dialog_content = "Un sentimiento que conozco demasiado bien...",
  ui_story_5084_50840502_57_dialog_content = "Cometí ese error antes. ¿Soy capaz de hacerlo de nuevo?",
  ui_story_5084_50840502_58_dialog_content = "¿De verdad deseas perdonar a Victoria?",
  ui_story_5084_50840502_59_dialog_content = "Si.",
  ui_story_5084_50840502_60_dialog_content = "Tú dudaste.",
  ui_story_5084_50840502_61_dialog_content = "Los que desean verla muerta son los otros jefes de familias. Como el segundo hijo de los Varaki, mi muerte no tendría consecuencias; lo que realmente temen es ver a Victoria ascender al poder.",
  ui_story_5084_50840502_62_dialog_content = "Si la profecía es cierta...",
  ui_story_5084_50840502_63_dialog_content = "El poder en la línea de sangre de Victoria despertó relativamente tarde, y ella no respondió a La Verdad que le transmití.",
  ui_story_5084_50840502_64_dialog_content = "Si muero, esos parásitos nunca la dejarán ir...",
  ui_story_5084_50840502_65_dialog_content = "Victoria... Victoria...",
  ui_story_5084_50840502_66_dialog_content = "(¿Eh? ¿Está él preocupado por Victoria?)",
  ui_story_5084_50840502_67_dialog_content = "¡Así es! Como líder de la True Order, soy yo quien declara al Iniciado! Pero...",
  ui_story_5084_50840502_68_dialog_content = "Dijo que no tenía intención de estar en el Advenimiento de la Verdad esta noche... ¿Dónde podría estar...?",
  ui_story_5084_50840502_69_dialog_content = "¡Eso significa que Victoria apareció en el templo en el peor momento posible! ¡Realmente fue sacrificada!",
  ui_story_5084_50840502_70_dialog_content = "¿Quién está ahí? Muéstrate...",
  ui_story_5084_50840502_71_dialog_content = "(¡Oh no, no otra vez...!)",
  ui_story_5084_50840502_72_dialog_content = "Jejeje, ¿así que tienes una contingencia en mente?",
  ui_story_5084_50840502_73_dialog_content = "¡PlayerName! ¿Hiciste algo de nuevo?!",
  ui_story_5084_50840502_74_dialog_content = "Se acabó... Tan pronto como mencionó sacrificar Victoria, no pude contenerme...",
  ui_story_5084_50840502_75_dialog_content = "Sacrificando a Lady Victoria... ¿Espera, eso es esta noche? ¿Eso significa que está a punto de suceder exactamente lo mismo?!",
  ui_story_5084_50840502_76_dialog_content = "Me temo que sí... Aunque Wilhelm parece estar preocupado por Victoria, todavía necesito saber qué planea hacerle...",
  ui_story_5084_50840502_77_dialog_content = "Este estudio... ¿Es una de las reliquias de <color=#FFB400>Osten Varaki</color> todavía aquí en algún lugar?",
  ui_story_5084_50840502_78_dialog_content = "¿O podría ser... Él?",
  ui_story_5084_50840502_79_dialog_content = "¡Dime! Ofrecer a Victoria como sacrificio... ¿Es esta tu voluntad?",
  ui_story_5084_50840502_80_dialog_content = "\"¿Él?\"",
  ui_story_5084_50840502_81_dialog_content = "¡¿Quién te habló hace un momento?! ¡Dime!",
  ui_story_5084_50840502_82_dialog_content = "¡Mi señor...!",
  ui_story_5084_50840502_83_dialog_content = "... Uraaagh! <size=45>¡Maldita sea este anillo maldito!!!</size>",
  ui_story_5084_50840502_84_dialog_content = "Mátame, mi señor... ¡¡¡Líbrame de mi sufrimiento!!!",
  ui_story_5084_50840502_85_dialog_content = "Solo mira tu estado deformado... Patético.",
  ui_story_5084_50840502_86_dialog_content = "¡Ugh... Aaaaahhh!",
  ui_story_5084_50840502_87_dialog_content = "¡Ajajajaja—! ¡Soy el líder legítimo de True Order! ¡¡¡Yo!!!",
  ui_story_5084_50840502_88_dialog_content = "(El anillo está atacando la mente de Wilhelm de nuevo... ¿Qué debería hacer?)",
  ui_story_5084_50840502_89_dialog_content = "Wilhelm, tonto sin remedio. Como dije antes, debes morir para poder vivir.",
  ui_story_5084_50840502_90_dialog_content = "No temo a la muerte... Pero Victoria... ¿¡¿Y ella?!?",
  ui_story_5084_50840502_91_dialog_content = "Señor de la Verdad...",
  ui_story_5084_50840502_92_dialog_content = "Dime qué será de Victoria después de hoy...!!!",
  ui_story_5084_50840502_93_dialog_content = "¡Ha perdido completamente el control! ¡No sobrevivirá si esto continúa!",
  ui_story_5084_50840502_94_dialog_content = "Parece que puedes hacer contacto con él usando tus poderes, PlayerName. ¿Por qué no intentas eso?",
  ui_story_5084_50840502_95_dialog_content = "¡Pero si hago eso, podría afectar el pasado! ¡Tendremos un gran problema si eso sucede...",
  ui_story_5084_50840502_96_dialog_content = "¿Crees en el Señor de la Verdad, verdad May? ¿Qué te haría sentir tranquilo en una situación como esta sin levantar ninguna sospecha?",
  ui_story_5084_50840502_97_dialog_content = "No sé, algo simple como \"May Que la Verdad te bendiga,\" o \"Sigue la guía,\" supongo?",
  ui_story_5084_50840502_98_dialog_content = "¿En serio...? Supongo que vale la pena intentarlo...",
  ui_story_5084_50840502_99_option_content = "Mindlink—",
  ui_story_5084_50840502_100_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840502_101_dialog_content = "...",
  ui_story_5084_50840502_102_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50840502_103_dialog_content = "M-May Que la Verdad te bendiga...",
  ui_story_5084_50840502_104_dialog_content = "Tú... ¿Quién eres exactamente...?",
  ui_story_5084_50840502_105_dialog_content = "(Parece que está funcionando, pero es mejor que tenga cuidado de no decir algo incorrecto...)",
  ui_story_5084_50840502_106_dialog_content = "Lo siento, pero ya no puedo creer en un dios que manipula los corazones de las personas. La Verdad en mi corazón no me llevará por mal camino.",
  ui_story_5084_50840502_107_dialog_content = "El True Order no puede continuar existiendo de esta manera, al menos no en el futuro de Victoria.",
  ui_story_5084_50840502_108_dialog_content = "Si también crees en el Señor de la Verdad, entenderás mis palabras.",
  ui_story_5084_50840502_109_dialog_content = "Para que aparezcas ante mí en este momento, debe significar que tienes algo que decirme... ¿Correcto?",
  ui_story_5084_50840502_110_dialog_content = "... Siga la guía.",
  ui_story_5084_50840502_111_dialog_content = "... Entonces crees que debería aceptar la realidad y permitirme ser consumido por los líderes de nuestras familias...",
  ui_story_5084_50840502_112_dialog_content = "¿Para que Victoria pueda seguir soportando la maldición de nuestro pueblo, y finalmente encontrar su fin a manos de ese vampiro?",
  ui_story_5084_50840502_113_dialog_content = "(No, eso no está bien... ¿Cómo empeoré las cosas...?)",
  ui_story_5084_50840502_114_dialog_content = "... ¡No! ¡Absolutamente no!",
  ui_story_5084_50840502_115_dialog_content = "He llegado tan lejos a pesar de ser abandonado por mi familia, ¡y se lo debo todo a La Verdad dentro de mi propio corazón! ¡Esa Verdad nunca me desviará!",
  ui_story_5084_50840502_116_dialog_content = "Son estas supuestas \"revelaciones\" las que han causado que el True Order caiga tan bajo...",
  ui_story_5084_50840502_117_dialog_content = "Debo... Deshacer esta maldición.",
  ui_story_5084_50840502_118_dialog_content = "Pero cómo...",
  ui_story_5084_50840502_119_dialog_content = "... La única reliquia sagrada que no ha sido manchada por un líder... Es <color=#FFB400>esa</color>.",
  ui_story_5084_50840502_120_dialog_content = "La luna de sangre... Cuando sus enredaderas toman forma viva, un guardián esperará al maestro de la cripta en su entrada.",
  ui_story_5084_50840502_121_dialog_content = "Pero aparte de transportar el ataúd de nuestro antepasado dentro y fuera de la tumba... La única forma de entrar es con la <color=#FFB400>llave</color>, o con el consentimiento de los jefes de familias...",
  ui_story_5084_50840502_122_dialog_content = "¡Ja! Wilhelm, desgraciado... ¿Sigues pensando en las reglas incluso cuando estás a punto de ser comido? Mereces ser ridiculizado...",
  ui_story_5084_50840502_123_dialog_content = "Incluso si Clavis se niega a darme la llave, los Guardianes de la Vid han servido a los Varaki durante generaciones...",
  ui_story_5084_50840502_124_dialog_content = "Seguramente me permitirá entrar a la cripta ahora que he adquirido este conocimiento, ¿verdad?",
  ui_story_5084_50840502_125_dialog_content = "¡Debo entrar antes del inicio de la procesión!",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>¡Fwoosh!</color>",
  ui_story_5084_50840502_127_dialog_content = "¡Agárrate fuerte, May!",
  ui_story_5084_50840502_128_dialog_content = "¿A dónde vamos esta vez?!",
  ui_story_5084_50840502_129_dialog_content = "¡La tumba de Varaki!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>En la entrada de una sastrería en la ciudad de Varaki</color>",
  ui_story_5084_50840601_2_dialog_content = "May Que la Verdad te bendiga, una costurera hábil.",
  ui_story_5084_50840601_3_dialog_content = "Y que la Verdad te bendiga también, amable señor. Con tal apariencia piadosa, definitivamente serás elegido como el Iniciado este año.",
  ui_story_5084_50840601_4_dialog_content = "Rezo para que así sea, querida. Debo irme ahora; hasta que nos encontremos en el banquete esta noche. No llegues tarde.",
  ui_story_5084_50840601_5_dialog_content = "Te aseguro que no lo haré.",
  ui_story_5084_50840601_6_dialog_content = "¿Qué... Cómo terminamos aquí?",
  ui_story_5084_50840601_7_dialog_content = "¿Está aquí por la túnica ceremonial, señor?",
  ui_story_5084_50840601_8_dialog_content = "¿Túnica ceremonial...?",
  ui_story_5084_50840601_9_dialog_content = "Ah, debes ser cliente de alguien más.",
  ui_story_5084_50840601_10_dialog_content = "Deberías saber, nuestra familia de sastres ha estado en el negocio más tiempo aquí en la ciudad de Varaki. Durante cada Advenimiento de la Verdad, nuestra tienda también maneja la mayoría de los pedidos de batas.",
  ui_story_5084_50840601_11_dialog_content = "Incluso las personas que viven en los bordes de nuestro pueblo vendrán a comprar nuestras túnicas en la misma noche de la celebración.",
  ui_story_5084_50840601_12_dialog_content = "¿Por qué no hacer un pedido con nosotros? Te garantizo que el precio será de tu agrado.",
  ui_story_5084_50840601_13_dialog_content = "...",
  ui_story_5084_50840601_14_dialog_content = "¡Mira, amigo! La luna de sangre ha aparecido.",
  ui_story_5084_50840601_15_dialog_content = "La luna de sangre... El Advenimiento de la Verdad es esta noche...",
  ui_story_5084_50840601_16_dialog_content = "Mi mentor dijo que me elegiría como el Iniciado de este año, lo que significa que debo vestirme piadosamente para la ocasión.",
  ui_story_5084_50840601_17_dialog_content = "¡¿El Iniciado?! ¿Escuché eso correctamente...?",
  ui_story_5084_50840601_18_dialog_content = "¡Pero la única persona que puede anunciar al Iniciado es el Señor Wilhelm Varaki! ¿Por qué te eligió a ti, de todas las personas?",
  ui_story_5084_50840601_19_dialog_content = "Sí, ese es el nombre de mi mentor. Nos conocimos en la cripta de su familia.",
  ui_story_5084_50840601_20_dialog_content = "¿La tumba de los Varaki...?! Ya veo... Dime, ¿cómo lograste acercarte tanto a La Verdad?",
  ui_story_5084_50840601_21_dialog_content = "... Confieso mis pecados y busco penitencia todos los días, pero todos aún me evitan. Todos... Excepto mi mentor.",
  ui_story_5084_50840601_22_dialog_content = "Penitencia... El Advenimiento de la Verdad... Y la luna de sangre... Sí, creo que ahora entiendo...",
  ui_story_5084_50840601_23_dialog_content = "Gracias por impartirme este conocimiento de la Verdad, honorable Iniciado...",
  ui_story_5084_50840601_24_dialog_content = "He estado aceptando dinero de los fieles en nombre del Advenimiento de la Verdad... Y así la Verdad me ha rechazado...",
  ui_story_5084_50840601_25_dialog_content = "Bendito seas, Iniciado... Bendito seas por mostrarme el error de mis caminos.",
  ui_story_5084_50840601_26_dialog_content = "¿Te importaría honrarnos con tu presencia un poco más? Mi madre, mi hija y yo estaríamos honradas de confeccionar un conjunto de túnicas para ti con la máxima urgencia!",
  ui_story_5084_50840601_27_dialog_content = "E-Eso no será necesario... Simplemente estaba de paso en busca de mi mentor.",
  ui_story_5084_50840601_28_dialog_content = "Esto no fue una coincidencia, señor; ¡La Verdad debe haberlo guiado aquí hoy! Por favor, perdóname por comportarme tan grosero hace un momento—",
  ui_story_5084_50840601_29_dialog_content = "De nuevo, realmente no es necesario...",
  ui_story_5084_50840601_30_dialog_content = "¿Mamá? ¿Qué sigues haciendo aquí?! ¡Nuestros clientes están cansados de esperar!",
  ui_story_5084_50840601_31_dialog_content = "¡Diles que entregaremos sus túnicas gratis hoy!",
  ui_story_5084_50840601_32_dialog_content = "¿Decir ah?",
  ui_story_5084_50840601_33_dialog_content = "¡Después de eso, estaremos confeccionando un conjunto de túnicas para este joven de inmediato! ¡Él es el Iniciado!",
  ui_story_5084_50840601_34_dialog_content = "¿Dices que ahora mismo?",
  ui_story_5084_50840601_35_dialog_content = "¡Sí, querido!",
  ui_story_5084_50840601_36_dialog_content = "La abuela no estará contenta con esto...",
  ui_story_5084_50840601_37_dialog_content = "Solo haz lo que digo, por ahora, niño. Le explicaré todo a tu abuela.",
  ui_story_5084_50840601_38_dialog_content = "Bien...",
  ui_story_5084_50840601_39_dialog_content = "Ah... ¡Perdóname, Señor de la Verdad! Parece que he cometido otro error...",
  ui_story_5084_50840601_40_dialog_content = "Gracias a Dios... Todavía tengo algo de dinero conmigo... Solo rezo para que cubra algunas de sus pérdidas del día...",
  ui_story_5084_50840601_41_dialog_content = "Pero no debo imponerme más a este tipo de costurera o a su familia...",
  ui_story_5084_50840601_42_dialog_content = "Wilhelm.",
  ui_story_5084_50840601_43_dialog_content = "¿Quién se atreve a pronunciar mi nombre y bloquear mi camino?! ¡Hazte a un lado! ¡La Venida de la Verdad requiere mi presencia!",
  ui_story_5084_50840601_44_dialog_content = "Has perdido de vista La Verdad, y tu visión está oscurecida por la realidad en su lugar.",
  ui_story_5084_50840601_45_dialog_content = "Esta responsabilidad es demasiado grande para que la soportes. Permíteme tomar tu lugar...",
  ui_story_5084_50840601_46_dialog_content = "¿Fuiste enviado por los otros jefes de familias? ¡Ven a mí entonces!",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>La vela parpadea y sus alrededores cambian una vez más: de repente, una tumba de origen claramente antiguo aparece ante ellos.</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>Un viento frío sopla y se lleva el polvo y los escombros que se han asentado en sus viñas durante siglos.</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>De repente, las enredaderas comienzan a retorcerse y desenredarse, liberando a la persona atrapada dentro...</color>",
  ui_story_5084_50840601_50_dialog_content = "Estamos aquí... Espera, ¿eso es...?",
  ui_story_5084_50840601_51_dialog_content = "¿Qu-Qué estoy haciendo aquí...?",
  ui_story_5084_50840601_52_dialog_content = "¿Fue esa persona con la que me encontré antes? Debe haber usado algún tipo de truco para traerme aquí... Y ahora ha tomado mi lugar en la ceremonia...",
  ui_story_5084_50840601_53_dialog_content = "La luna de sangre ha sido oscurecida... ¿Qué hora es ahora? ¿He perdido el Advenimiento de la Verdad?",
  ui_story_5084_50840601_54_dialog_content = "Has sido bendecido con la sabiduría de la Verdad.",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>Las enredaderas en la entrada de la cripta convergen y asumen la forma de un hombre de rostro pálido con ojos apagados y sin vida.</color>",
  ui_story_5084_50840601_56_dialog_content = "Mi señor, la tumba de tus antepasados está abierta para ti.",
  ui_story_5084_50840601_57_dialog_content = "Pero... ¿Cómo?",
  ui_story_5084_50840601_58_dialog_content = "La <color=#FFB400>llave</color> está cerca... Puedo sentir su llama.",
  ui_story_5084_50840601_59_dialog_content = "¿Qué llama? El único fuego que veo por aquí... Está en el candelabro en tus manos.",
  ui_story_5084_50840601_60_dialog_content = "¿Podría ser todo esto... por mi culpa? Primero lo guié hasta aquí con mi voz, y ahora he abierto la puerta de la tumba para él?",
  ui_story_5084_50840601_61_dialog_content = "¿Qué exactamente he estado cambiando aquí?",
  ui_story_5084_50840601_62_dialog_content = "Espera, yo no...",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>Sin esperar a que Wilhelm termine de hablar, el Guardián de la Vid regresa al suelo musgoso y reanuda su vigilia silenciosa.</color>",
  ui_story_5084_50840601_64_dialog_content = "La cripta está abierta, y su guardián me ha concedido la entrada...",
  ui_story_5084_50840601_65_dialog_content = "Aún no he hecho nada. ¿Podría ser esto obra de La Verdad?",
  ui_story_5084_50840601_66_dialog_content = "El destino me ha guiado hasta aquí, lo que significa que el Señor de la Verdad desea que lleve a cabo su voluntad divina.",
  ui_story_5084_50840601_67_dialog_content = "Debo entrar.",
  ui_story_5084_50840601_68_dialog_content = "¿Qué está haciendo ahora...? ¡Vamos, May!",
  ui_story_5084_50840601_69_dialog_content = "Quizás el antepasado Varaki pueda ofrecer más orientación...",
  ui_story_5084_50840601_70_dialog_content = "¡¿D-Dónde está el ataúd ancestral?! Se suponía que debía ser devuelto una vez que terminó la procesión...",
  ui_story_5084_50840601_71_dialog_content = "¿Quién se atrevería a perturbar el último lugar de descanso de los Varaki?! No...",
  ui_story_5084_50840601_72_dialog_content = "El ataúd ancestral, e incluso la Bloody Bible... Ambos se han ido...",
  ui_story_5084_50840601_73_dialog_content = "¿Los jefes de las familias ya han puesto sus planes en marcha?",
  ui_story_5084_50840601_74_dialog_content = "Victoria... ¡Ella está en peligro!",
  ui_story_5084_50840601_75_dialog_content = "¡Caballero de Invierno! ¡Llévame de vuelta al templo!",
  ui_story_5084_50840601_76_dialog_content = "¡Qué caballo negro tan genial... No, espera, necesitamos perseguirlo!",
  ui_story_5084_50840601_77_dialog_content = "¿Discípulos muertos? ¿Por qué están vagando por aquí?!",
  ui_story_5084_50840601_78_dialog_content = "Más cadáveres... ¡¿Qué demonios pasó en el pueblo?!",
  ui_story_5084_50840601_79_dialog_content = "¡Criatura sucia! ¿Cómo te atreves a invadir este lugar y dañar a los fieles!",
  ui_story_5084_50840601_80_dialog_content = "Estos seres desdichados no tienen mente propia. Su maestro debe haberlos soltado en la ciudad.",
  ui_story_5084_50840601_81_dialog_content = "¡Limpiaré el mundo de su existencia!",
  ui_story_5084_50840602_1_dialog_content = "¡Ah, Señor Wilhelm Varaki... Qué figura tan poderosa y cautivadora!",
  ui_story_5084_50840602_2_dialog_content = "A través de su sabiduría, se me concedió un vistazo a través de la puerta de la Verdad.",
  ui_story_5084_50840602_3_dialog_content = "Parece que los fieles están completamente inconscientes de los monstruos que amenazan la ciudad...",
  ui_story_5084_50840602_4_dialog_content = "La ceremonia del Advenimiento de la Verdad ha terminado, pero los jefes de las familias aún deberían estar en el templo...",
  ui_story_5084_50840602_5_dialog_content = "Huff, huff... F-Finalmente... nos pusimos al día...",
  ui_story_5084_50840602_6_dialog_content = "¡Mira, May! ¡Son esos dos discípulos a los que intentaste predicar antes! ¡Hemos vuelto a este tiempo otra vez!",
  ui_story_5084_50840602_7_dialog_content = "¡Lo que significa que deberíamos estar en el templo ahora mismo!",
  ui_story_5084_50840602_8_dialog_content = "Una vez que los discípulos se fueron, pensé que la ceremonia había concluido. No esperaba encontrarte esperándome aquí.",
  ui_story_5084_50840602_9_dialog_content = "Nails! ¡¿Qué estás haciendo aquí?!",
  ui_story_5084_50840602_10_dialog_content = "¿Y qué diablos estás vistiendo...?",
  ui_story_5084_50840602_11_dialog_content = "Una amable costurera y su familia hicieron estas túnicas a medida para mí. Estoy eternamente agradecido por su generosidad.",
  ui_story_5084_50840602_12_dialog_content = "También estoy agradecido a mi mentor por permitirme estar aquí hoy.",
  ui_story_5084_50840602_13_dialog_content = "Tú...",
  ui_story_5084_50840602_14_dialog_content = "¿Eh? ¿De qué estás hablando, Nails?",
  ui_story_5084_50840602_15_dialog_content = "Para ser honesto, tampoco entiendo realmente lo que dice la mitad del tiempo...",
  ui_story_5084_50840602_16_dialog_content = "Fue un inmenso honor para mí servir como el sacrificio para este Advenimiento de la Verdad.",
  ui_story_5084_50840602_17_dialog_content = "Perdóname, pero no tengo idea de lo que estás hablando.",
  ui_story_5084_50840602_18_dialog_content = "¡Porfirio! ¿Dónde está la Biblia sangrienta?!",
  ui_story_5084_50840602_19_dialog_content = "También tengo preguntas, Wilhelm. ¿Qué fue ese viento negro justo ahora? ¿Y dónde se ha ido Victoria?!",
  ui_story_5084_50840602_20_dialog_content = "¿Victoria?",
  ui_story_5084_50840602_21_dialog_content = "Even after offering your own niece, the Lord of Truth did not grace you with any revelations. Has your own failure finally driven you mad?",
  ui_story_5084_50840602_22_dialog_content = "It matters not. I've long since grown tired of your games, Wilhelm.",
  ui_story_5084_50840602_23_dialog_content = "The Bloody Bible is mine now! The Truth is within my reach!",
  ui_story_5084_50840602_24_dialog_content = "Sin embargo... Ahora que el ritual de este año ha concluido, creo que tenemos algo de qué hablar.",
  ui_story_5084_50840602_25_dialog_content = "Es tal como vi en la profecía... Jeje—No queda nada de qué hablar. ¡Sé que pretendes atacarme, Porfirio!",
  ui_story_5084_50840602_26_dialog_content = "No sirve de nada fingir ignorancia; ¡Ya he purgado la ciudad de tus sirvientes, a los que desataste sobre los inocentes fieles!",
  ui_story_5084_50840602_27_dialog_content = "Así que ha llegado a esto...",
  ui_story_5084_50840602_28_dialog_content = "Parece que Wilhelm Varaki no tiene intención de cedernos... La Verdad aún tiene mucho que decirme, así que debo despedirme de ambos.",
  ui_story_5084_50840602_29_dialog_content = "¡Ni un paso más, Porfirio!",
  ui_story_5084_50840602_30_dialog_content = "Es inútil resistirse, Wilhelm. Con la Bloody Bible en mis manos, el destino ahora está de mi lado...",
  ui_story_5084_50840602_31_dialog_content = "Es hora de trabajar, viejo amigo.",
  ui_story_5084_50840602_32_dialog_content = "¿Qué pretendes hacerle a mi mentor? Yo soy el Iniciado, no él.",
  ui_story_5084_50840602_33_dialog_content = "¿Y justo de dónde vienes, forastero?",
  ui_story_5084_50840602_34_dialog_content = "Ni siquiera los seguidores de Wilhelm se salvarán.",
  ui_story_5084_50840602_35_dialog_content = "Como líder de True Order, ¡no te permitiré hacerle daño a ninguno más de los fieles!",
  ui_story_5084_50840602_36_dialog_content = "¡Deberías preocuparte por ti mismo primero, tonto! ¡Jajajaja!",
  ui_story_5084_50840602_37_dialog_content = "¡Wilhelm...!",
  ui_story_5084_50840602_38_dialog_content = "Mi señor, concédeme tu dolor y permíteme sufrir en tu lugar. Trágalo, derrámalo y permite que La Verdad prevalezca sobre el mal...",
  ui_story_5084_50840602_39_dialog_content = "No, Sr. Nails! Tienes que correr—",
  ui_story_5084_50840602_40_dialog_content = "¡Para, May! No se nos permite interferir... ¡Recuerda lo que Sikare nos dijo!",
  ui_story_5084_50840602_41_dialog_content = "Todo esto es mi culpa. Nada de esto habría sucedido si me hubiera mantenido en silencio... Necesitamos pensar en otra forma de ayudarles. Todavía tenemos el candelabro, así que debe haber algo que podamos hacer.",
  ui_story_5084_50840602_42_dialog_content = "Hmph, qué sorpresa. Tus huesos son tan fuertes como tu fe, parece.",
  ui_story_5084_50840602_43_dialog_content = "¡Mueran!",
  ui_story_5084_50840602_44_dialog_content = "Señor de la Verdad, tus rituales son tan insoportablemente crueles. ¿Pueden tus creyentes realmente soportar esto? Si es así, ¿cómo pueden sobrevivir a tal inmenso dolor?",
  ui_story_5084_50840602_45_dialog_content = "¡Lo soportaré! Tragaré este sufrimiento y limpiaré mi cuerpo de sus pecados. Aceptaré esta maldición de dolor y quemaré las heridas de mi alma—",
  ui_story_5084_50840602_46_dialog_content = "Permíteme soportar este dolor en soledad, ¡para que ninguna otra persona deba experimentarlo! ¡Ven y borra mis pecados a través de la agonía!",
  ui_story_5084_50840602_47_dialog_content = "¡Una vida de sufrimiento a cambio de su redención!",
  ui_story_5084_50840602_48_dialog_content = "(A este ritmo, ¡Nails realmente va a morir en sus manos! Vamos, candelabro... Llévame donde pueda hacer una diferencia...!)",
  ui_story_5084_50840602_49_dialog_content = "¡Tonto!",
  ui_story_5084_50840602_50_dialog_content = "¡Esto no es un ritual, y ellos no te están ayudando a purificar tu alma! ¿¡No puedes ver que están tratando de matarte!?",
  ui_story_5084_50840602_51_dialog_content = "¿Te consideras un asceta? Si es así, ¡debes sobrevivir y dedicar el resto de tu vida a buscar La Verdad!",
  ui_story_5084_50840602_52_dialog_content = "¿Mi señor?",
  ui_story_5084_50840602_53_dialog_content = "¡Vive, tonto!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>Wilhelm agarra a Nails y lo lanza con una fuerza sorprendente. Se estrella contra las puertas del templo, abriéndolas de par en par y permitiendo que el viento negro entre.</color>",
  ui_story_5084_50840602_55_dialog_content = "¡Ah! ¡La vela se apagó!",
  ui_story_5084_50840602_56_dialog_content = "¡Wilhelm Varaki no será forzado a arrodillarse tan fácilmente! ¿Ahora qué más tienes preparado para mí?!",
  ui_story_5084_50840602_57_dialog_content = "¡Vosotros, traidores demonios, probaréis mi espada antes de que termine la noche!",
  ui_story_5084_50840602_58_dialog_content = "Despierta, <color=#FF0000>Corriente Carmesí</color>! Mi espada demoníaca, que bebe de mi sangre a cambio de derribar a mis enemigos!",
  ui_story_5084_50840602_59_dialog_content = "¿Qué está pasando? ¿Están a punto de pelear...?",
  ui_story_5084_50840602_60_dialog_content = "¡No sé! ¡No puedo ver nada!",
  ui_story_5084_50840602_61_dialog_content = "El mundo está empezando a cambiar a nuestro alrededor de nuevo, ¡pero tengo que ver esto hasta el final! No puedo permitirme... Ser teletransportado lejos—",
  ui_story_5084_50840602_62_dialog_content = "¡Agárrate a mí y retrocede todo lo que puedas, May!",
  ui_story_5084_50840602_63_dialog_content = "Maldita sea, no puedo ver nada aquí dentro.",
  ui_story_5084_50840602_64_dialog_content = "Aun así, no durará mucho más por su cuenta.",
  ui_story_5084_50840602_65_dialog_content = "¡Ah!",
  ui_story_5084_50840602_66_dialog_content = "¿Quién de ustedes es mi próxima víctima?",
  ui_story_5084_50840602_67_dialog_content = "¡Ven y párate a mi lado, Clavis! ¡Podemos derrotarlos juntos!",
  ui_story_5084_50840602_68_dialog_content = "...",
  ui_story_5084_50840602_69_dialog_content = "Es inútil, Wilhelm. Incluso si cortas mi cabeza, no moriré.",
  ui_story_5084_50840602_70_dialog_content = "¡Entonces seguiré cortándote hasta que ya no puedas soportar el dolor!",
  ui_story_5084_50840602_71_dialog_content = "Increíble... Aunque está luchando contra tantas personas en la oscuridad... No está en desventaja en absoluto.",
  ui_story_5084_50840602_72_dialog_content = "Lamentable... ¿Estás siquiera tratando de matarlo?",
  ui_story_5084_50840602_73_dialog_content = "Es más fácil decirlo que hacerlo...",
  ui_story_5084_50840602_74_dialog_content = "¿Sigues contando con los demás, Porfirio? Tu fin está cerca, ¡y nadie te salvará de él!",
  ui_story_5084_50840602_75_dialog_content = "¿Recuerdas nuestro trato... No es así?",
  ui_story_5084_50840602_76_dialog_content = "...",
  ui_story_5084_50840602_77_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840602_78_dialog_content = "¿Qué pasó? ¡Ya no puedo sentir su respiración! ¿Es él...",
  ui_story_5084_50840602_79_dialog_content = "¡Solo sigue aguantando! Estamos... ¡Estamos a punto de ser teletransportados a otro lugar!",
  ui_story_5084_50840602_80_dialog_content = "¿Por qué...? ¿Por qué tiene que ser así?",
  ui_story_5084_50840602_81_dialog_content = "(Si realmente muere... ¿Qué va a pasar con Victoria?)",
  ui_story_5084_50840602_82_dialog_content = "Oye, PlayerName? Lord Wilhelm no parece para nada un asesino despiadado, ¿verdad? ¿Realmente crees que sacrificó a Lady... Victoria...?",
  ui_story_5084_50840602_83_dialog_content = "También tengo mis dudas ahora... Desde que el candelabro nos teletransportó por primera vez, el Wilhelm que hemos estado viendo no se parece en nada al Wilhelm que vimos en la ceremonia del Advenimiento de la Verdad...",
  ui_story_5084_50840602_84_dialog_content = "¿Mis palabras realmente causaron que todos estos cambios sucedieran...?",
  ui_story_5084_50840602_85_dialog_content = "¿O está pasando algo más entre los Wilhelms que hemos visto...?",
  ui_story_5084_50840602_86_dialog_content = "Me pregunto dónde estará Lady Victoria ahora mismo...",
  ui_story_5084_50840602_87_dialog_content = "Durante la ceremonia, Victoria mencionó algo sobre la desaparición de Wilhelm. ¿Quizás está tratando de encontrar las respuestas detrás de su desaparición?",
  ui_story_5084_50840602_88_dialog_content = "Algo me dice que esta ceremonia de sacrificio no es tan simple como parece... Si está dispuesta a revisar todo esto, debe significar que está buscando algo.",
  ui_story_5084_50840602_89_dialog_content = "Parece que ella y Wilhelm se malinterpretaron durante mucho tiempo... Todavía tenían más que decirse el uno al otro.",
  ui_story_5084_50840700_1_dialog_content = "Vaya, mira todas estas velas y flores, PlayerName! Espera... ¿Eso es un ataúd?!",
  ui_story_5084_50840700_2_dialog_content = "Eso creo...",
  ui_story_5084_50840700_3_dialog_content = "¿Me pregunto dónde estamos ahora?",
  ui_story_5084_50840700_4_dialog_content = "Está tan oscuro y sombrío afuera también. Déjame echar un vistazo...",
  ui_story_5084_50840700_5_dialog_content = "¡Estamos en un antiguo castillo con vista a un acantilado! ¿Quién construiría su casa en un lugar como este...?",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>Pozo-pat, pozo-pat—</color>",
  ui_story_5084_50840700_7_dialog_content = "¡Ah—Es la Dama Victoria!",
  ui_story_5084_50840700_8_dialog_content = "¿Pero cómo...? ¿Es porque estaba pensando en ella justo ahora?",
  ui_story_5084_50840700_9_dialog_content = "Espera, hay alguien más.",
  ui_story_5084_50840700_10_dialog_content = "¿Así que también has venido en busca de Wilhelm?",
  ui_story_5084_50840700_11_dialog_content = "Aparte de la familia, parece que las únicas personas que vienen a su casa son sus enemigos.",
  ui_story_5084_50840700_12_dialog_content = "¿Sabes dónde está?",
  ui_story_5084_50840700_13_dialog_content = "Desafortunadamente, no lo sé. No dejó pistas sobre su paradero antes de desaparecer.",
  ui_story_5084_50840700_14_dialog_content = "Qué vergüenza. Pensé que al menos tendría uno o dos confidentes de confianza.",
  ui_story_5084_50840700_15_dialog_content = "Una vez estuvimos tan cerca, sí.",
  ui_story_5084_50840700_16_dialog_content = "Si tan solo Wilhelm no hubiera sido tan imprudente... Podría haberse mantenido así.",
  ui_story_5084_50840700_17_dialog_content = "Nunca entendiste muy bien a tu tío... ¿Verdad, Victoria?",
  ui_story_5084_50840700_18_dialog_content = "No tengo interés en conocer a personas como él, mucho menos entenderlas.",
  ui_story_5084_50840700_19_dialog_content = "Antes de que tu papá se convirtiera en líder de True Order, tu tío Wilhelm codiciaba el papel más que cualquier otra cosa.",
  ui_story_5084_50840700_20_dialog_content = "Cegado por la perspectiva de fortuna y gloria, persiguió fervientemente las creencias más radicales y las proclamó como La Verdad.",
  ui_story_5084_50840700_21_dialog_content = "Debido a esto, perdió el control repetidamente cada vez que intentaba heredar el poder de nuestros antepasados... Aunque ya se le veía como un paria, se negó a aceptar la derrota.",
  ui_story_5084_50840700_22_dialog_content = "Esa negativa, a su vez, lo convirtió en el títere de las ambiciones de otro, lo que finalmente resultó en su expulsión de la familia.",
  ui_story_5084_50840700_23_dialog_content = "... No me importa aprender su historia.",
  ui_story_5084_50840700_24_dialog_content = "De hecho, estoy bastante contento de estar libre de su control.",
  ui_story_5084_50840700_25_dialog_content = "Durante mis viajes, el Señor de la Verdad me reveló algo... Por eso he venido a despedirme.",
  ui_story_5084_50840700_26_dialog_content = "Me voy al lugar que me mostraron, donde esperaré la gloriosa llegada del Señor de la Verdad.",
  ui_story_5084_50840700_27_dialog_content = "Eres el sucesor de la línea de sangre Varaki. Eres libre de tomar cualquier decisión como creas conveniente.",
  ui_story_5084_50840700_28_dialog_content = "Pero antes de irme, ¿puedo preguntarte algo? Ese día, cuando visitamos tu casa... ¿Qué era lo que Wilhelm quería pedirte prestado?",
  ui_story_5084_50840700_29_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840700_30_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840700_31_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840700_32_dialog_content = "...! Es una llave para todas las puertas... Pero aquellos que arden con ambición solo serán consumidos por ella.",
  ui_story_5084_50840700_33_dialog_content = "... Cuídate, Victoria Varaki. Tú llevas una gran y pesada carga, y el camino a la Verdad es largo y arduo.",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>Victoria observa mientras Clavis se va. Una vez que está fuera de vista, ella gira y entra en la habitación de Wilhelm.</color>",
  ui_story_5084_50840700_35_dialog_content = "¿A dónde has ido, tú hombre incomprensible?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>Ella mira alrededor de la habitación antes de finalmente abrir el opulento ataúd de Wilhelm y acostarse dentro de él.</color>",
  ui_story_5084_50840700_37_dialog_content = "Si veo las cosas como mis padres una vez lo hicieron... ¿Podré entender tus ambiciones?",
  ui_story_5084_50840700_38_dialog_content = "(Este sentimiento... Ella está intentando recordar algo...)",
  ui_story_5084_50840700_39_dialog_content = "Nos hemos reunido aquí hoy para honrar a los líderes de la Familia Varaki mientras depositamos sus cuerpos a descansar.",
  ui_story_5084_50840700_40_dialog_content = "A medida que siguen los pasos de nuestros nobles antepasados, sobreviven gracias a su amada hija—Victoria Varaki.",
  ui_story_5084_50840700_41_dialog_content = "Ven, niño; coloca este anillo sobre la tumba de tu papá con tus propias manos. Era un símbolo de su honor, y debería ser tratado como tal en este momento.",
  ui_story_5084_50840700_42_dialog_content = "Padre... Madre...",
  ui_story_5084_50840700_43_dialog_content = "Tómate tu tiempo, querida. Entendemos que todavía estás abrumada por el dolor y la confusión.",
  ui_story_5084_50840700_44_dialog_content = "Pero no temas, mi lady, porque permaneceremos a tu lado mientras navegas por esta hora más oscura—Ah, pero ¿dónde están mis modales? Mi nombre es David Porfirio.",
  ui_story_5084_50840700_45_dialog_content = "Tu padre una vez me ayudó a domar el caos dentro de mi sangre, y restauró mi preciada cordura.",
  ui_story_5084_50840700_46_dialog_content = "Y yo soy Clavis Ibrahim. Nunca he olvidado la bondad que me mostró la Familia Varaki.",
  ui_story_5084_50840700_47_dialog_content = "Si alguna vez necesitas ayuda con cualquier cosa, solo tienes que pedirla.",
  ui_story_5084_50840700_48_dialog_content = "Lady Varaki... No necesitas saber mi nombre. No soy más que un humilde servidor, así que por favor dirígete a mí como tal.",
  ui_story_5084_50840700_49_dialog_content = "Mi padre... ¿Cómo te llamó?",
  ui_story_5084_50840700_50_dialog_content = "Graves, mi señora...",
  ui_story_5084_50840700_51_dialog_content = "El paso del tiempo puede ser cruel, tanto que casi he olvidado mi nombre... Todos me llaman <color=#FFB400>Adder</color>, así que siéntete libre de hacerlo también.",
  ui_story_5084_50840700_52_dialog_content = "El ritual ha terminado y los líderes de la Familia Varaki han sido puestos a descansar. Ahora ha llegado el momento de discutir el futuro.",
  ui_story_5084_50840700_53_dialog_content = "Todavía eres bastante joven, Lady Victoria. Me temo que aún no estás lista para soportar el poder de este anillo.",
  ui_story_5084_50840700_54_dialog_content = "Con gusto lo vigilaré en tu lugar, no temas, para alguien que no pertenece a los Varaki, no es más que un anillo normal.",
  ui_story_5084_50840700_55_dialog_content = "¿Es eso cierto? Entonces, ¿por qué insistes en quedártelo para ti, Porfirio?",
  ui_story_5084_50840700_56_dialog_content = "¡¿Wilhelm Varaki?!",
  ui_story_5084_50840700_57_dialog_content = "Hmph, no olvides que otro miembro de los Varaki aún vive, y que solo un Varaki puede asumir el liderazgo de la Orden Verdadera.",
  ui_story_5084_50840700_58_dialog_content = "...",
  ui_story_5084_50840700_59_dialog_content = "¡Cómo te atreves a hablar tal locura ante Lady Victoria! ¿Has olvidado que fuiste desterrado de la Familia Varaki?!",
  ui_story_5084_50840700_60_dialog_content = "¡Ja! ¡Sé testigo de cómo heredo la sabiduría y el poder de nuestros ancestros!",
  ui_story_5084_50840700_61_dialog_content = "Urgh...",
  ui_story_5084_50840700_62_dialog_content = "¡Jajajaja! ¿Por qué esa cara de decepción, Porfirio? ¿Te atormenta tanto la perspectiva de ver a otro Varaki ponerse ese anillo?",
  ui_story_5084_50840700_63_dialog_content = "¡Contemplad! Yo, Wilhelm Varaki, ahora me alzo sobre todos vosotros!",
  ui_story_5084_50840700_64_dialog_content = "¡Nuestro antepasado me ha considerado digno de convertirme en el nuevo jefe de la Familia Varaki!",
  ui_story_5084_50840700_65_dialog_content = "Wilhelm... Parece que tus ambiciones no se han extinguido.",
  ui_story_5084_50840700_66_dialog_content = "Je... ¡Jajajaja! Querido Victoria, parece que tu tío no está dispuesto a concederte lo que te pertenece por derecho.",
  ui_story_5084_50840700_67_dialog_content = "No tenemos derecho a interferir en los asuntos de Varaki. Tomemos nuestra partida.",
  ui_story_5084_50840700_68_dialog_content = "Wilhelm Varaki... Mi tío...",
  ui_story_5084_50840700_69_dialog_content = "¿A dónde deseas ir?",
  ui_story_5084_50840700_70_dialog_content = "Naturalmente, deseo dejar esta ciudad e ir al lugar que he heredado legítimamente.",
  ui_story_5084_50840700_71_dialog_content = "Victoria Varaki... A partir de este día, serviré como tu guardián. Mientras yo sea el jefe de la familia, debes hacer exactamente lo que digo.",
  ui_story_5084_50840700_72_dialog_content = "... Ese anillo pertenecía a mi padre, lo que significa que ahora debería pertenecerme a mí. Cuando La Verdad me hable y despierte mi poder, lo recuperaré.",
  ui_story_5084_50840700_73_dialog_content = "Como desees. Pero por ahora, se queda en mis manos.",
  ui_story_5084_50840700_74_dialog_content = "The honor of hearing The Truth... I dearly wish to hear the thoughts of one as precocious as you, Victoria Varaki. What, in your definition, is The Truth?",
  ui_story_5084_50840700_75_dialog_content = "The Truth... is knowledge.",
  ui_story_5084_50840700_76_dialog_content = "Humph, Victoria Varaki... Though we share the same bloodline, in terms of strength, wisdom, capability, and even beauty... I stand far above you.",
  ui_story_5084_50840700_77_dialog_content = "So what makes you think this ring is rightfully yours?",
  ui_story_5084_50840700_78_dialog_content = "I am a true Varaki, and the leader of the True Order!",
  ui_story_5084_50840700_79_dialog_content = "As for you... You must first demonstrate that you are worthy of our family name. Do not disappoint me.",
  ui_story_5084_50840700_80_dialog_content = "(Wilhelm está diciendo cosas tan horribles, y a un niño que acaba de perder a sus padres, ni más ni menos... ¿No está hablando en serio, verdad?)",
  ui_story_5084_50840700_81_dialog_content = "(De nuevo, ese niño todavía es Victoria... ¡Es tan extraño! El Wilhelm que hemos estado viendo no es casi esto...)",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>Un rayo de relámpago retumba en el cielo exterior mientras la joven Victoria abre el ataúd de sus padres y se mete dentro.</color>",
  ui_story_5084_50840700_83_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_84_dialog_content = "Dame tu guía... Dime qué hacer...",
  ui_story_5084_50840700_85_dialog_content = "¿Soy yo... Hogar? ¿Pero cómo?",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>Susurro, susurro—</color>",
  ui_story_5084_50840700_87_dialog_content = "¿Quién se atreve a entrometerse en la casa de los Varaki—",
  ui_story_5084_50840700_88_dialog_content = "... ¿Qué estás haciendo aquí? ¿Y dónde están mis sirvientes?",
  ui_story_5084_50840700_89_dialog_content = "Desaparecido. A partir de este momento, el tiempo será nuestro servidor eterno.",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>Wilhelm Varaki, el hombre que había irrumpido repentinamente en Victoria, estaba allí para quedarse y cuidarla como su tío.</color>",
  ui_story_5084_50840700_91_dialog_content = "Mi querido Victoria, tu difícil situación pesa mucho en nuestros corazones, y realmente, lo hace... Pero somos impotentes para cambiarlo. Por favor, perdónanos, niño.",
  ui_story_5084_50840700_92_dialog_content = "Mientras Wilhelm sea el jefe de los Varaki, debemos obedecerle. En realidad, él es quien nos mantiene a distancia...",
  ui_story_5084_50840700_93_dialog_content = "Esperando que nada estuviera mal, me apresuré a venir aquí lo más rápido que pude... Me alivia ver que efectivamente estás bien.",
  ui_story_5084_50840700_94_dialog_content = "Solo está siendo cauteloso conmigo. Teme que yo conspire contigo y con los demás para destronarlo.",
  ui_story_5084_50840700_95_dialog_content = "Sí, esto es lo que Wilhelm teme... Porque sabe que tu padre era un líder mucho más capaz. No es más que un marginado y un oportunista.",
  ui_story_5084_50840700_96_dialog_content = "Dama Victoria, debo preguntar... Tus talentos deberían ser tan impresionantes como los de tu padre. Dime, ¿pudiste resonar con el sagrado recipiente del antepasado?",
  ui_story_5084_50840700_97_dialog_content = "Si es así, ¿cómo se sintió?",
  ui_story_5084_50840700_98_dialog_content = "Se sentía como... Alguien había entrado en mi mente para contarme sobre el néctar que una vez contuvo.",
  ui_story_5084_50840700_99_dialog_content = "Algunas de sus historias se contaron en voz baja, como si quisieran decir...",
  ui_story_5084_50840700_100_dialog_content = "¡Porfirio! ¿Quién te concedió la entrada a mi dominio?!",
  ui_story_5084_50840700_101_dialog_content = "Jeje, solo vine a ver cómo le va a Lady Victoria, Wilhelm. Me despediré ahora.",
  ui_story_5084_50840700_102_dialog_content = "Lo está haciendo perfectamente bien. Si esperabas sangre fresca, te sugiero que deseches ese pensamiento de inmediato.",
  ui_story_5084_50840700_103_dialog_content = "¡No influyas en sus acciones con tus ambiciones desmedidas!",
  ui_story_5084_50840700_104_dialog_content = "Soy libre de hablar con quien me plazca, Wilhelm.",
  ui_story_5084_50840700_105_dialog_content = "Todavía eres demasiado ingenuo, Victoria. No aprenderás sobre el mundo sumergiéndote en textos antiguos; solo te alejarás de él.",
  ui_story_5084_50840700_106_dialog_content = "¿Sabes sobre la Biblia Sangrienta que yace dentro de la tumba de nuestros ancestros, sí? La sabiduría que proporciona nunca se puede encontrar en las páginas de ningún otro libro.",
  ui_story_5084_50840700_107_dialog_content = "Desde que tus padres fueron enterrados, ni una sola vez has visitado la cripta.",
  ui_story_5084_50840700_108_dialog_content = "Pero eso no importa. No te culpo por detestar a la True Order, pero tus emociones no son razón suficiente para hacerlo.",
  ui_story_5084_50840700_109_dialog_content = "De lo contrario, no te hace mejor que un niño caprichoso.",
  ui_story_5084_50840700_110_dialog_content = "Tuve que volverme más fuerte, para que nadie pudiera controlarme de nuevo.",
  ui_story_5084_50840700_111_dialog_content = "Con ese fin, busqué la Verdad intentando resonar con varias reliquias a través de rituales antiguos...",
  ui_story_5084_50840700_112_dialog_content = "¿Dónde está? ¿Dónde podría estar ese texto antiguo...?",
  ui_story_5084_50840700_113_dialog_content = "El Señor de la Verdad se me apareció en mi sueño, instándome a encontrar su texto sagrado antes de que Wilhelm Varaki se diera cuenta de que yo estaba desaparecido...",
  ui_story_5084_50840700_114_dialog_content = "¡Ah!",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>Las estrellas</color>... Está devorando las <color=#FFB400>estrellas</color>... ¡No hay tiempo! No hay tiempo en absoluto... Un <color=#FFB400>nuevo comienzo</color> está a la mano...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>¡El verdadero final se encuentra dentro de esa oscuridad—!</size>",
  ui_story_5084_50840700_117_dialog_content = "¡Suelta eso de inmediato, tonto! ¿Cómo te atreves a intentar resonar con esa antigua reliquia!",
  ui_story_5084_50840700_118_dialog_content = "La sabiduría de los días antiguos, las revelaciones de un loco — yo, Wilhelm Varaki, te ordeno que te mantengas alejado de ella!",
  ui_story_5084_50840700_119_dialog_content = "... ¡Ah!",
  ui_story_5084_50840700_120_dialog_content = "... Regresa a tu sueño eterno.",
  ui_story_5084_50840700_121_dialog_content = "¿Y-Tú me salvaste? Pero ¿cómo supiste que yo estaba...",
  ui_story_5084_50840700_122_dialog_content = "Aprende a distinguir entre las características de diferentes reliquias, o tu cadáver será lo único que recupere la próxima vez.",
  ui_story_5084_50840700_123_dialog_content = "Y no malinterpreten mis intenciones. Como líder de la True Order, lo último que necesito es que los fieles me acusen de dañar a la hija de mi difunto hermano.",
  ui_story_5084_50840700_124_dialog_content = "Mantenerlo vivo solo ayuda a asegurar la estabilidad de mi posición.",
  ui_story_5084_50840700_125_dialog_content = "Además, en lugar de salvar a alguien al borde de la muerte, la familia de sangre prefiere drenar hasta la última gota de sangre de su cuerpo.",
  ui_story_5084_50840700_126_dialog_content = "¡Wilhelm Varaki...!",
  ui_story_5084_50840700_127_dialog_content = "Ese hombre jactancioso, arrogante, despreciable... Me quitó la vida y la libertad, y sus razones para hacerlo siempre son tan extrañas.",
  ui_story_5084_50840700_128_dialog_content = "Pero en comparación con mi detestable tío, los demás apenas eran mejores.",
  ui_story_5084_50840700_129_dialog_content = "Los jefes de las familias eran tontos de corazón negro, hasta el último de ellos. Las personas a las que lideraban eran como gusanos o cadáveres reanimados, deambulando por la ciudad sin propósito ni conciencia.",
  ui_story_5084_50840700_130_dialog_content = "Sus sermones apestaban a maldad y necedad, y no ofrecían ninguna guía para los fieles de La Verdad. Tales personas no son aptas para guiar a los perdidos.",
  ui_story_5084_50840700_131_dialog_content = "Tenía que estar alerta con ellos... No podía permitirme caer presa de las malas tendencias de la True Order.",
  ui_story_5084_50840700_132_dialog_content = "Para acatar la voluntad del Señor de la Verdad, y resolver el \"final\" que se me mostró.",
  ui_story_5084_50840700_133_dialog_content = "Te has estado encerrando en la casa recientemente. ¿Finalmente has perdido interés en las reliquias?",
  ui_story_5084_50840700_134_dialog_content = "Para cuando teníamos tu edad, tu padre y yo ya habíamos despertado hace mucho el poder de nuestra línea de sangre, y nuestros corazones eran insaciables por la sabiduría de La Verdad.",
  ui_story_5084_50840700_135_dialog_content = "¿Podría ser que sigues siendo tan ignorante como antes? ¿Todavía eres incapaz de responder a mi pregunta sobre La Verdad?",
  ui_story_5084_50840700_136_dialog_content = "... He decidido viajar por el mundo en busca de La Verdad.",
  ui_story_5084_50840700_137_dialog_content = "Haz lo que quieras.",
  ui_story_5084_50840700_138_dialog_content = "Y así comencé mi viaje, y busqué la guía de La Verdad para mí mismo.",
  ui_story_5084_50840700_139_dialog_content = "En el momento en que puse un pie fuera de mi casa, comencé a adquirir un conocimiento más profundo del mundo.",
  ui_story_5084_50840700_140_dialog_content = "Y a medida que fortalecía mi comprensión de La Verdad, el poder de mi linaje comenzó a despertar gradualmente... Aun así, me negué a unirme a la True Order.",
  ui_story_5084_50840700_141_dialog_content = "Cuando finalmente encontré la respuesta que él había pedido, volví a la ciudad de Varaki para decírselo... Solo para descubrir que ya no lo esperaba de mí.",
  ui_story_5084_50840700_142_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840700_143_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840700_144_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840700_145_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840700_146_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840700_147_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840700_148_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840700_149_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840700_150_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840700_151_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840700_152_dialog_content = "...",
  ui_story_5084_50840700_153_dialog_content = "Hasta esta estancia, todavía no lo entiendo.",
  ui_story_5084_50840700_154_dialog_content = "Temo que también perdí mi última oportunidad para hacerlo.",
  ui_story_5084_50840700_155_dialog_content = "Wilhelm Varaki: mi arrogante, despreciable e inescrutable tío, así como mi último pariente vivo... ¿Dónde has ido?",
  ui_story_5084_50840700_156_dialog_content = "(Así es como Victoria ve a Wilhelm en sus recuerdos...)",
  ui_story_5084_50840700_157_dialog_content = "(Pero desde la perspectiva de Wilhelm, él siempre ha estado cuidando de ella...)",
  ui_story_5084_50840700_158_dialog_content = "(Él sufrió al perder el control por sí mismo, y se negó a beber la sangre de los fieles como el resto de los jefes de familias. Pensó en los demás hasta el final, e incluso logró salvar a Nails...)",
  ui_story_5084_50840700_159_dialog_content = "(Durante tantos años... Nunca lograron entenderse... Incluso cuando Wilhelm fue atacado...)",
  ui_story_5084_50840700_160_dialog_content = "(Me pregunto si Victoria puede ver lo que he visto...)",
  ui_story_5084_50840801_1_dialog_content = "La vela está empezando a parpadear de nuevo, ¿a dónde nos llevará esta vez?",
  ui_story_5084_50840801_2_dialog_content = "Es Victoria... Y el resto de los jefes de familias. ¿Qué están haciendo todos aquí?",
  ui_story_5084_50840801_3_dialog_content = "¿Eh? ¿Es ese Faust parado junto a ella? ¡Y creo que nos está mirando!",
  ui_story_5084_50840801_4_dialog_content = "¿Podría ser esto...?",
  ui_story_5084_50840801_5_option_content = "Enlace mental",
  ui_story_5084_50840801_6_dialog_content = "Faust! ¿Puedes escuchar mi voz?",
  ui_story_5084_50840801_7_dialog_content = "Por supuesto, y estoy plenamente consciente de tus dudas actuales.",
  ui_story_5084_50840801_8_dialog_content = "La persona que ves aquí es Lady Victoria, la que conoces tan bien.",
  ui_story_5084_50840801_9_dialog_content = "Pero si es la Victoria de nuestro tiempo... ¿Por qué está parada frente a estas personas...?",
  ui_story_5084_50840801_10_dialog_content = "Wilhelm ha estado desaparecido durante tres años. Los únicos descendientes restantes de los Varaki son el niño de Ibrahim y Victoria, la sobrina de Wilhelm.",
  ui_story_5084_50840801_11_dialog_content = "(Tres años... Wilhelm fue atacado en 1915, lo que significa que deberíamos estar en el año 1918 ahora, ¿verdad?)",
  ui_story_5084_50840801_12_dialog_content = "Sin embargo, Clavis Ibrahim no está dispuesto a permitir que su niño entre a la True Order, lo que significa que no tiene derecho a su liderazgo.",
  ui_story_5084_50840801_13_dialog_content = "Tal como está, el puesto sigue vacante y el anillo familiar no se encuentra por ningún lado. Sospechamos que desapareció junto con Wilhelm Varaki.",
  ui_story_5084_50840801_14_dialog_content = "Y dado que Victoria ya no tiene el privilegio de heredar la sabiduría de nuestros antepasados...",
  ui_story_5084_50840801_15_dialog_content = "¿Oh? ¿Todos ustedes se reunieron aquí hoy simplemente para decirme esto?",
  ui_story_5084_50840801_16_dialog_content = "Me han dicho que prefieres buscar La Verdad viajando por el mundo exterior. Respetamos tu elección.",
  ui_story_5084_50840801_17_dialog_content = "Eres libre de abandonar este lugar, o quedarte y convertirte en parte de la Familia Porfirio. En cualquier caso, ya no estás calificado para liderar la True Order.",
  ui_story_5084_50840801_18_dialog_content = "Con la llegada de la Verdad que tiene lugar esta noche, el liderazgo de la True Order debe recaer en...",
  ui_story_5084_50840801_19_dialog_content = "¿Las reuniones de la Orden realmente se han vuelto tan solitarias y depravadas en ausencia de Wilhelm?",
  ui_story_5084_50840801_20_dialog_content = "Incluso las familias de sangre deben pagar un alto precio por beber sangre que no está destinada a ser consumida.",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>Victoria vierte un vaso de vino rojo sangre en la mesa frente a ella. En el fondo del vaso yace el anillo que una vez llevó Wilhelm.</color>",
  ui_story_5084_50840801_22_dialog_content = "¿...?",
  ui_story_5084_50840801_23_dialog_content = "... el anillo de Wilhelm.",
  ui_story_5084_50840801_24_dialog_content = "Me lo confió poco antes de abandonar este lugar. Las palabras de nuestros antepasados han guiado mis pasos desde hace mucho tiempo.",
  ui_story_5084_50840801_25_dialog_content = "Ahora dime, ¿qué más tienes que decir sobre el liderazgo de la Orden Verdadera?",
  ui_story_5084_50840801_26_dialog_content = "¡Imposible!",
  ui_story_5084_50840801_27_dialog_content = "El plan debe ser cambiado...",
  ui_story_5084_50840801_28_dialog_content = "Parece que cada uno de ustedes está al tanto de algún tipo de plan.",
  ui_story_5084_50840801_29_dialog_content = "Este es el conocimiento que me fue revelado durante el Advenimiento de la Verdad hace tres años.",
  ui_story_5084_50840801_30_dialog_content = "Hace tres años...",
  ui_story_5084_50840801_31_dialog_content = "¡No, esto no puede ser!",
  ui_story_5084_50840801_32_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840801_33_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840801_34_dialog_content = "...",
  ui_story_5084_50840801_35_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840801_36_dialog_content = "Condenado a una muerte deshonrosa en tu propia ciudad natal... Qué lástima me das, Wilhelm Varaki.",
  ui_story_5084_50840801_37_dialog_content = "...",
  ui_story_5084_50840801_38_dialog_content = "Y sin descendientes de los que hablar, el anillo de Varaki ha perdido todo su significado.",
  ui_story_5084_50840801_39_dialog_content = "¿Qué has hecho? Al aplastar el anillo, has...",
  ui_story_5084_50840801_40_dialog_content = "Es inútil para ti o para mí ahora. Deja que los escombros descansen en paz con Wilhelm.",
  ui_story_5084_50840801_41_dialog_content = "A partir de este día, ya no se puede usar para amenazarnos nunca más.",
  ui_story_5084_50840801_42_dialog_content = "¡El grillete que son los jefes de Varaki está en el pasado!",
  ui_story_5084_50840801_43_dialog_content = "Ese anillo... Debería haber sido quemado hasta convertirse en cenizas, junto con Wilhelm...",
  ui_story_5084_50840801_44_dialog_content = "Parece que has descubierto la verdad.",
  ui_story_5084_50840801_45_dialog_content = "¿Oh? ¿Se suponía que debía permanecer en secreto?",
  ui_story_5084_50840801_46_dialog_content = "... Pero ¿realmente lo has usado? ¿Realmente te ha transmitido su sabiduría?",
  ui_story_5084_50840801_47_dialog_content = "A menos que nuestros antepasados te consideren digno, ¡nunca tendrás éxito Wilhelm!",
  ui_story_5084_50840801_48_dialog_content = "Nuestros antepasados me dieron el nombre de Varaki, y este anillo perdido hace mucho tiempo es un símbolo de su aprobación. Ahora me lo pondré para que todos lo vean.",
  ui_story_5084_50840801_49_dialog_content = "PlayerName ¡Ese anillo va a hacer que Lady Victoria pierda el control!",
  ui_story_5084_50840801_50_dialog_content = "No te preocupes May, estoy empezando a darme cuenta lentamente de por qué estoy aquí ahora. ¡Sé exactamente qué hacer!",
  ui_story_5084_50840801_51_option_content = "Mindlink—",
  ui_story_5084_50840801_52_dialog_content = "Urgh... No otra vez...",
  ui_story_5084_50840801_53_dialog_content = "Las voces... Las revelaciones antiguas...",
  ui_story_5084_50840801_54_dialog_content = "¡No te preocupes Victoria, te ayudaré a suprimirlos!",
  ui_story_5084_50840801_55_dialog_content = "¿Ya veo... Esto debe ser la voluntad del Señor de la Verdad. En ese caso, te lo dejo a ti.",
  ui_story_5084_50840801_56_dialog_content = "Ella lo lleva puesto... Realmente lo lleva puesto...",
  ui_story_5084_50840801_57_dialog_content = "¿Por qué estaban todos tan preocupados? Un verdadero Varaki no debería tener ningún problema para soportar las voces de nuestros antepasados, después de todo.",
  ui_story_5084_50840801_58_dialog_content = "Jejeje... Jajajaja—",
  ui_story_5084_50840801_59_dialog_content = "Esa risa...",
  ui_story_5084_50840801_60_dialog_content = "Behold! I, Wilhelm Varaki, now tower over all of you!",
  ui_story_5084_50840801_61_dialog_content = "Our ancestor has deemed me worthy of becoming the new head of the Varaki Family!",
  ui_story_5084_50840801_62_dialog_content = "Varaki...!",
  ui_story_5084_50840801_63_dialog_content = "¡Contempla, el sucesor de la familia Varaki!",
  ui_story_5084_50840802_1_dialog_content = "¡Limpiaré el mundo de tu existencia!",
  ui_story_5084_50840802_2_dialog_content = "¿Qué estoy viendo...?",
  ui_story_5084_50840802_3_dialog_content = "Hice todo lo posible para mantener a raya las voces, pero estas visiones aún lograron escapar del anillo.",
  ui_story_5084_50840802_4_dialog_content = "No parecen estar conectados con las voces, sin embargo. Si acaso, creo que provienen de un nivel de conciencia aún más alto.",
  ui_story_5084_50840802_5_dialog_content = "No parecen ser peligrosos. Permíteme verlos.",
  ui_story_5084_50840802_6_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840802_7_dialog_content = "¡Tu sangre y la autoridad que otorga ahora son mías, Wilhelm Varaki!",
  ui_story_5084_50840802_8_dialog_content = "¡Tú servirás como mi <color=#FFB400>llave</color> y desbloquearás la sabiduría de nuestros ancestros para mí! ¡Jajajaja!",
  ui_story_5084_50840802_9_dialog_content = "Wilhelm Varaki... ¡Él...!",
  ui_story_5084_50840802_10_dialog_content = "Wilhelm... Cuando me contaste tus planes de irte, asumí que habías encontrado un refugio seguro para Victoria y para ti.",
  ui_story_5084_50840802_11_dialog_content = "Entonces por qué... ¿Por qué volviste a este lugar, tú tonto...",
  ui_story_5084_50840802_12_dialog_content = "Jeje... Aunque supongo que también soy un tonto por creer en <color=#FFB400>ese hombre</color> tan fácilmente.",
  ui_story_5084_50840802_13_dialog_content = "Antepasados, les suplico que acepten a Wilhelm Varaki en su grupo. A pesar de la impura ambición que ardía en sus venas, ha hecho más que honrar el noble nombre de los Varaki.",
  ui_story_5084_50840802_14_dialog_content = "Ahora que ha sido traicionado por un pecador como yo, absuélvelo de sus crímenes y traspásalos a mí.",
  ui_story_5084_50840802_15_dialog_content = "Aunque mi alma pronto estará maldita, humildemente rezo para que mi esposa y Charon encuentren una manera de abandonar este lugar...",
  ui_story_5084_50840802_16_dialog_content = "Wilhelm Varaki, mi antiguo amigo... May encuentras paz eterna en este ataúd.",
  ui_story_5084_50840802_17_dialog_content = "¿Él... Realmente murió? Wilhelm Varaki... Ha estado muerto todo este tiempo...",
  ui_story_5084_50840802_18_dialog_content = "¿Es esta la verdad que el anillo desea mostrarme?",
  ui_story_5084_50840802_19_dialog_content = "El hombre que me lo dio hace tres años... ¿Realmente se ha ido?",
  ui_story_5084_50840802_20_dialog_content = "... ¿Qué vas a hacer ahora?",
  ui_story_5084_50840802_21_dialog_content = "Puedo sentir que me estoy acercando cada vez más a La Verdad.",
  ui_story_5084_50840802_22_dialog_content = "Como el líder actual de la True Order, pensé que el Señor de la Verdad me guió aquí simplemente para presenciar este momento una vez más.",
  ui_story_5084_50840802_23_dialog_content = "Pero tu presencia y el sacrificio anterior me han mostrado que debo participar. Aparte de la bendición de mi señor, también llevo un odio innegable en mi corazón.",
  ui_story_5084_50840802_24_dialog_content = "Esto es algo que solo yo puedo hacer, y solo con suficiente control sobre mi poder y mente.",
  ui_story_5084_50840802_25_dialog_content = "Bendito sea el Señor de la Verdad por disipar mis dudas y concederme el placer de la retribución.",
  ui_story_5084_50840802_26_dialog_content = "Esta noche es el Advenimiento de la Verdad. Nuestro resentimiento surgió de nuestra sed de la sabiduría de nuestros antepasados; que ellos observen mientras ponemos fin a todo.",
  ui_story_5084_50840802_27_dialog_content = "Habitantes de la ciudad de Varaki, por favor perdonenme por haberlos hecho esperar a todos.",
  ui_story_5084_50840802_28_dialog_content = "Después de recibir orientación del Señor de la Verdad, ahora entiendo mi propósito.",
  ui_story_5084_50840802_29_dialog_content = "¿No te causa ese anillo un dolor inmenso?",
  ui_story_5084_50840802_30_dialog_content = "Incluso Wilhelm no pudo ponérselo tan fácilmente.",
  ui_story_5084_50840802_31_dialog_content = "¿Qué revelación recibiste?",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>Victoria se levanta y camina hasta la cabecera de la mesa.</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>Purgar la orden.</color>",
  ui_story_5084_50840802_34_dialog_content = "¡¿Qué?!",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>Un viento negro irrumpe en el templo, sacudiendo violentamente sus puertas y ventanas. Empuñando un poder mucho más allá de su tiempo, la sucesora de Varaki parece emitir un ultimátum a los jefes de las casas.</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>Aplastar—</color>",
  ui_story_5084_50840802_37_dialog_content = "¿Dejaste caer tu vaso de sorpresa? Qué vergüenza tan grande.",
  ui_story_5084_50840802_38_dialog_content = "...",
  ui_story_5084_50840802_39_dialog_content = "Ese anillo... ¡Dime qué te mostró!",
  ui_story_5084_50840802_40_dialog_content = "¡Detente, David! ¿Has olvidado que estamos en el Templo de la Verdad?!",
  ui_story_5084_50840802_41_dialog_content = "¡...!",
  ui_story_5084_50840802_42_dialog_content = "Dado que todo comenzó con el festival de nuestros antepasados, es apropiado que todo termine esta noche.",
  ui_story_5084_50840802_43_dialog_content = "Ahora, si me disculpas, como el nuevo líder de los Varaki, debo prepararme para el Advenimiento de la Verdad.",
  ui_story_5084_50840802_44_dialog_content = "Cuando la luna de sangre cuelga en el cielo y los pasillos del templo resuenan con el sonido de las campanas, debemos reunirnos una vez más para presenciar el fin de esta larga noche.",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>En la tenue luz de la linterna, David Porfirio se encuentra en un charco de sangre. Aparte de sus seguidores enloquecidos, la única otra persona en la habitación es Clavis Ibrahim, cuyo cuerpo ha sido torturado hasta quedar irreconocible.</color>",
  ui_story_5084_50840900_2_dialog_content = "Dime... ¿Wilhelm sigue vivo?!",
  ui_story_5084_50840900_3_dialog_content = "Habla... ¡Ahora...!",
  ui_story_5084_50840900_4_dialog_content = "Te he contado todo lo que sé... Ya no tiene sentido torturarme más...",
  ui_story_5084_50840900_5_dialog_content = "Coloqué su cuerpo sin vida en ese ataúd con mis propias manos... No había forma de negar su muerte...",
  ui_story_5084_50840900_6_dialog_content = "Durante el Advenimiento de la Verdad hace tres años, Wilhelm ayudó a Victoria a escapar del ataúd.",
  ui_story_5084_50840900_7_dialog_content = "Incapaces de soportar su tiranía por más tiempo, finalmente nos levantamos contra él y destruimos el anillo que nos unía.",
  ui_story_5084_50840900_8_dialog_content = "Entonces, ¿por qué, después de tres años, Victoria ha aparecido con el mismo anillo en sus manos?!",
  ui_story_5084_50840900_9_dialog_content = "Esos dos deben estar tramando algo.",
  ui_story_5084_50840900_10_dialog_content = "La Biblia Sangrienta no contiene texto escrito. No te mostrará las palabras del divino que tanto buscas desesperadamente.",
  ui_story_5084_50840900_11_dialog_content = "Por otro lado, la chica Varaki ha demostrado ser muy parecida a su papá.",
  ui_story_5084_50840900_12_dialog_content = "Je... Jejejeje... Jajajaja—",
  ui_story_5084_50840900_13_dialog_content = "¿Qué te parece tan divertido?",
  ui_story_5084_50840900_14_dialog_content = "Fuimos tontos al acobardarnos ante la fanfarronería de Wilhelm, y ahora no nos queda más remedio.",
  ui_story_5084_50840900_15_dialog_content = "Deberíamos haberlo matado y Victoria el día que sus padres fallecieron.",
  ui_story_5084_50840900_16_dialog_content = "Los poderes de Wilhelm aún no estaban despertados en ese momento, y Victoria apenas era una amenaza.",
  ui_story_5084_50840900_17_dialog_content = "Después de inclinarnos ante los Varaki durante tanto tiempo, parece que todos hemos olvidado... Que la llamada \"Verdad\" no es más que los residuos de una fe externa.",
  ui_story_5084_50840900_18_dialog_content = "En efecto. ¡Consumir sangre fresca y extraer poder de ella es la única forma de que nuestro pueblo sobreviva!",
  ui_story_5084_50840900_19_dialog_content = "Sin nuestro verdadero poder, nos hemos visto obligados a mantener nuestra fe en el <color=#FFB400>Señor de la Verdad</color> a través de la afirmación, repetición, restricción y oración. ¡No es nada menos que herejía!",
  ui_story_5084_50840900_20_dialog_content = "Es muy tarde ahora, Porfirio... Con el poder del anillo en sus manos, ella se está preparando para destruirnos en este mismo momento.",
  ui_story_5084_50840900_21_dialog_content = "No importa cómo nos preparemos, tenemos menos de medio día antes de que todos estemos...",
  ui_story_5084_50840900_22_dialog_content = "¡Silencio! Wilhelm también llevaba ese anillo en el pasado, ¡y aún así pudimos desangrarlo!",
  ui_story_5084_50840900_23_dialog_content = "Mi único arrepentimiento es que beber su sangre no me permitió formar un pacto con la Bloody Bible. Para empezar, parece que nunca fue el sucesor de los Varaki.",
  ui_story_5084_50840900_24_dialog_content = "Pero gracias a mi inagotable suministro de creyentes, he recuperado gradualmente mi poder... ¡Y ahora finalmente puedo escuchar el débil llamado de la Bloody Bible!",
  ui_story_5084_50840900_25_dialog_content = "Sólo un poco más... ¡Y pronto su conocimiento se revelará ante mí!",
  ui_story_5084_50840900_26_dialog_content = "¡Los Varaki tienen la culpa de suprimir nuestra línea de sangre y evitar que alcancemos la verdadera superioridad!",
  ui_story_5084_50840900_27_dialog_content = "Nacimos para consumir la sangre de los vivos, sin embargo, los Varaki buscaron restringir nuestras tendencias naturales... Presumiblemente porque temían nuestro poder.",
  ui_story_5084_50840900_28_dialog_content = "¿Qué piensas hacer...?",
  ui_story_5084_50840900_29_dialog_content = "Lo mismo que hemos planeado todo el tiempo... Apareceré ante los fieles durante el ritual de esta noche y demostraré que la Bloody Bible me ha reconocido.",
  ui_story_5084_50840900_30_dialog_content = "Sin fuerza ni apoyo, Victoria no tiene forma de detenerme.",
  ui_story_5084_50840900_31_dialog_content = "La tumba de su familia y su humilde guardián son las únicas cosas en las que pueden confiar. Goblin, Viper, Undine... Dejo a los Vinekeepers a los tres.",
  ui_story_5084_50840900_32_dialog_content = "Entendido.",
  ui_story_5084_50840900_33_dialog_content = "Si pudiera matar a Wilhelm, entonces Victoria no debería ser un problema.",
  ui_story_5084_50840900_34_dialog_content = "Solo necesito reponer mis fuerzas y ver qué trucos tiene reservados para esta noche.",
  ui_story_5084_50840900_35_dialog_content = "Nngh... David...",
  ui_story_5084_50840900_36_dialog_content = "... Y eso es todo lo que sabemos. Después de viajar de un lado a otro en el tiempo tantas veces, apenas sabemos dónde estamos.",
  ui_story_5084_50840900_37_dialog_content = "Aunque las revelaciones de La Verdad pueden ser oscuras, sus planes no están sin su significado.",
  ui_story_5084_50840900_38_dialog_content = "Hace tres años, en nuestro tiempo actual, el año 1915, vi por última vez a Wilhelm. Fue durante ese Advenimiento de la Verdad que me ordenó entrar en el ataúd ancestral.",
  ui_story_5084_50840900_39_dialog_content = "Recuerdo haberlo visto retorciendo el anillo en su dedo en ese momento, algo que nunca lo había visto hacer antes. Fue entonces cuando supe...",
  ui_story_5084_50840900_40_dialog_content = "Estaba tratando de decirme algo. Por eso decidí participar en el ritual.",
  ui_story_5084_50840900_41_dialog_content = "Pero cuando volví en mí, me encontré en el \"presente\" actual.",
  ui_story_5084_50840900_42_dialog_content = "Habían pasado tres años, y me desperté en mi cama con el anillo de nuestra familia en mi mano.",
  ui_story_5084_50840900_43_dialog_content = "Wilhelm me lo había dado al final de ese ritual.",
  ui_story_5084_50840900_44_dialog_content = "Y cuando desperté, me encontré en esa mansión justo cuando alguien llegó con una carta. Me confió entregarla a Lady Victoria antes de tomar su partida.",
  ui_story_5084_50840900_45_dialog_content = "Justo cuando comencé a preguntarme sobre mi situación, la Dama Victoria emergió de la habitación cercana.",
  ui_story_5084_50840900_46_dialog_content = "La carta simplemente pedía que asistiera a la reunión de los jefes de familias antes del Advenimiento de la Verdad. Pero claramente, no estaban anticipando mi aparición.",
  ui_story_5084_50840900_47_dialog_content = "Quienquiera que vino a entregar esa carta sabía que yo estaba aquí. No solo eso, sino que sabían que era yo en el presente, no el Victoria, perteneciente a este punto.",
  ui_story_5084_50840900_48_dialog_content = "Eso me recuerda, Lady Victoria... Nos encontramos con Nails antes pero... Estaba actuando de manera muy extraña...",
  ui_story_5084_50840900_49_dialog_content = "Agradeció a Wilhelm por darle la oportunidad de estar allí, aunque Wilhelm no tenía idea de quién era.",
  ui_story_5084_50840900_50_dialog_content = "¿Podría ser la persona que organizó todo esto Wilhelm del Advenimiento de la Verdad hace tres años?",
  ui_story_5084_50840900_51_dialog_content = "Estaba muerto en las visiones que vimos antes, y sin embargo, de alguna manera todavía existe en el pasado.",
  ui_story_5084_50840900_52_dialog_content = "Debe haber hecho algo durante el Advenimiento de la Verdad hace tres años, algo que aún está más allá de nuestro entendimiento.",
  ui_story_5084_50840900_53_dialog_content = "Aun así, puedo sentir que nos estamos acercando aún más a La Verdad.",
  ui_story_5084_50840900_54_dialog_content = "Lady Victoria, debo preguntar... ¿Dónde exactamente estabas durante el Advenimiento de la Verdad de 1918?",
  ui_story_5084_50840900_55_dialog_content = "Si recuerdo correctamente... todavía estaba viajando durante el Advenimiento de la Verdad de ese año. Como tal, no tenía forma de estar presente en esa reunión.",
  ui_story_5084_50840900_56_dialog_content = "Pero esa misma noche, estaba durmiendo en el pueblo de Vortex cuando La Verdad me ordenó regresar por la Bloody Bible.",
  ui_story_5084_50840900_57_dialog_content = "Cuando desperté, me encontré en un <color=#FFB400>ataúd</color> en lo profundo de la tumba de Varaki, la Bloody Bible apretada fuertemente en mis manos.",
  ui_story_5084_50840900_58_dialog_content = "Después, me reveló que había reconocido a Vortex, y que yo iba a ser el líder de la True Order.",
  ui_story_5084_50840900_59_dialog_content = "Esta fue la memoria que me mostró el anillo antes de que partimos en nuestra búsqueda.",
  ui_story_5084_50840900_60_dialog_content = "¿Dijiste... Un <color=#FFB400>ataúd</color> en la tumba de Varaki? Pero, ¿por qué era un <color=#FFB400>ataúd</color>?",
  ui_story_5084_50840900_61_dialog_content = "Quizás fue porque... También tengo la costumbre de dormir en ellos.",
  ui_story_5084_50840900_62_dialog_content = "(Eso es verdad... Ella hizo eso en el ataúd de sus padres... También en el de Wilhelm...)",
  ui_story_5084_50840900_63_dialog_content = "¿Quizás los ataúdes en la tumba de la Familia Varaki poseen algún tipo de poder desconocido?",
  ui_story_5084_50840900_64_dialog_content = "¿Como el poder de viajar a diferentes épocas?",
  ui_story_5084_50840900_65_dialog_content = "Al igual que el candelabro de Caelestite, quizás también puedan transportarte a varios puntos en el tiempo.",
  ui_story_5084_50840900_66_dialog_content = "También ayudó a Wilhelm a abrir la puerta de la cripta durante el Advenimiento de la Verdad hace tres años...",
  ui_story_5084_50840900_67_dialog_content = "Sikare... ¿¡Pero cuántas de estas cosas tiene ella?!",
  ui_story_5084_50840900_68_dialog_content = "La familia de Sikare siempre ha protegido la cripta y ha impedido que Lady Victoria mire dentro.",
  ui_story_5084_50840900_69_dialog_content = "Siempre que preguntábamos, Sikare simplemente decía que aún no era el momento... Entonces, ¿por qué este es el momento adecuado?",
  ui_story_5084_50840900_70_dialog_content = "Quizás hay un significado más profundo detrás de la desaparición de Wilhelm, e incluso de su muerte.",
  ui_story_5084_50840900_71_dialog_content = "Parece que había sido consciente del peligro al que se enfrentaba ese día durante mucho tiempo, y simplemente estaba esperando que apareciéramos.",
  ui_story_5084_50840900_72_dialog_content = "Una vez exigió que le diera una explicación de La Verdad. Fue casi implacable al respecto... Pero ahora me doy cuenta de que nunca esperó una respuesta \"correcta\" de mí.",
  ui_story_5084_50840900_73_dialog_content = "Porque La Verdad no tiene una respuesta correcta, y nunca la tendrá.",
  ui_story_5084_50840900_74_dialog_content = "Es una fe inquebrantable que busca ofrecer respuestas infinitas.",
  ui_story_5084_50840900_75_dialog_content = "Y ahora que entiendo el poder de estas respuestas, ya no albergo ningún miedo o duda. Mi propósito es claro: debo purgar a los jefes de familias de la Orden Verdadera.",
  ui_story_5084_50840900_76_dialog_content = "Si tan solo hubiera podido hablar con franqueza conmigo hace tres años y entendido mi búsqueda...",
  ui_story_5084_50840900_77_dialog_content = "(Los dos han sido tan tercos durante tanto tiempo... ¿Realmente no hay forma de que se reconcilien después de todo este tiempo?)",
  ui_story_5084_50840900_78_dialog_content = "En cualquier caso, no me detendré... Hasta que haya descubierto el significado detrás de este anillo reapareciendo en mi posesión.",
  ui_story_5084_50840900_79_dialog_content = "(Después de saltar de un lado a otro en el tiempo tantas veces... También me gustaría una respuesta definitiva...)",
  ui_story_5084_50840900_80_dialog_content = "(¿Por qué Victoria y yo vemos a Wilhelm de manera tan diferente? Por lo que he visto, realmente le importa ella, pero no parece de esa manera en sus recuerdos.)",
  ui_story_5084_50840900_81_dialog_content = "(Algo sigue faltando... Sea lo que sea, estoy seguro de que las cosas serán mucho más claras una vez que lo encontremos. Victoria incluso podría tener la oportunidad de darle su respuesta a Wilhelm...)",
  ui_story_5084_50840900_82_dialog_content = "(... ¿Qué pasa, candelabro? Siempre me llevas a una respuesta cuando tengo preguntas, ¿por qué no estás funcionando esta vez?)",
  ui_story_5084_50840900_83_dialog_content = "(Ah... Creo que finalmente entiendo de dónde proviene la fe inquebrantable de la Orden Verdadera...)",
  ui_story_5084_50840900_84_dialog_content = "Ha caído la noche, y el Advenimiento de la Verdad está casi sobre nosotros. No nos queda mucho tiempo.",
  ui_story_5084_50840900_85_dialog_content = "Tiempo... Eso me recuerda, solo me queda aproximadamente un tercio de mi candelabro.",
  ui_story_5084_50840900_86_dialog_content = "No te preocupes, sé lo que debe hacerse ahora.",
  ui_story_5084_50840900_87_dialog_content = "Mis amenazas durante la reunión infundieron miedo en sus corazones, lo que solo ha avivado su deseo de más poder. No se detendrán ante nada para derrotarme ahora.",
  ui_story_5084_50840900_88_dialog_content = "¿Pero qué pasa si intentan escapar? Puedes ser bastante aterrador cuando quieres serlo, Victoria.",
  ui_story_5084_50840900_89_dialog_content = "La ambición de David Porfirio no le permitirá huir. Nunca estará satisfecho a menos que logre su objetivo.",
  ui_story_5084_50840900_90_dialog_content = "Parece que tiene en su posesión la Biblia Sangrienta de esta época.",
  ui_story_5084_50840900_91_dialog_content = "Para realizar su aspiración de convertirse en el líder de True Order, se quedará y hará todo lo que esté a su alcance para presidir el ritual de esta noche.",
  ui_story_5084_50840900_92_dialog_content = "La ambición puede ser una bestia aterradora. Así como consumió a Wilhelm, también consumirá a David.",
  ui_story_5084_50840900_93_dialog_content = "Entonces, ¿dónde deberíamos ir?",
  ui_story_5084_50840900_94_dialog_content = "A la tumba de mis antepasados, hay algo que necesito confirmar allí. Si las cosas proceden como se espera, David enviará a alguien allí también.",
  ui_story_5084_50840900_95_dialog_content = "Espera, Dama Victoria... ¿Qué deberíamos hacer acerca de Sr. Nails?",
  ui_story_5084_50840900_96_dialog_content = "Todavía está en alguna parte de la ciudad.",
  ui_story_5084_50840900_97_dialog_content = "No hay necesidad de preocuparse por él. Nuestro señor lo ha bendecido con protección, y la Verdad lo guiará a donde necesita estar.",
  ui_story_5084_50840900_98_dialog_content = "Pero Lady Victoria, vi con mis propios ojos cómo los jefes de las familias lo lastimaban gravemente...",
  ui_story_5084_50840900_99_dialog_content = "Todavía estoy preocupado por él, y he querido buscarlo todo este tiempo. Simplemente no estoy seguro si causará más problemas para todos.",
  ui_story_5084_50840900_100_dialog_content = "Sentir confusión no es motivo de alarma, y preocuparse por los demás es una cualidad noble. Haz lo que tu corazón te diga, May.",
  ui_story_5084_50840900_101_dialog_content = "Faust, por favor quédate con May y cuida de Nails.",
  ui_story_5084_50840900_102_dialog_content = "El Caelestite y yo te encontraremos en el templo esta noche.",
  ui_story_5084_50841001_1_dialog_content = "Las enredaderas en la entrada están cubiertas de sangre, y los ataúdes han sido forzados... ¿Estaban los jefes de las familias un paso adelante de nosotros?",
  ui_story_5084_50841001_2_dialog_content = "Molestando los restos de nuestros antepasados... Su desprecio por nuestras doctrinas no conoce límites.",
  ui_story_5084_50841001_3_dialog_content = "¡Creo que este es el lugar que vimos antes!",
  ui_story_5084_50841001_4_dialog_content = "Este es el lugar donde Clavis colocó a Wilhelm en ese ataúd...",
  ui_story_5084_50841001_5_dialog_content = "Sin embargo, su ataúd no está a la vista.",
  ui_story_5084_50841001_6_dialog_content = "Mi dama... Dama Victoria... ¿Eres tú?",
  ui_story_5084_50841001_7_dialog_content = "¿Tumbas? Gracias a Dios que todavía vives. Cuando vi las enredaderas afuera, temí lo peor...",
  ui_story_5084_50841001_8_dialog_content = "Tres años, mi lady... Durante tres años, no hubo un jefe de la Familia Varaki para defender este lugar, y por lo tanto, cayó en el caos.",
  ui_story_5084_50841001_9_dialog_content = "Con la muerte de Wilhelm y tu paradero desconocido, los jefes de las familias de la rama saquearon las reliquias de esta tumba con absoluta impunidad.",
  ui_story_5084_50841001_10_dialog_content = "Se llevaron a mi familia y los torturaron... Me torturaron...",
  ui_story_5084_50841001_11_dialog_content = "Fue David Porfirio... Busca llevarse todo, incluyendo mi poder como servidor de los Varaki...",
  ui_story_5084_50841001_12_dialog_content = "... Perdóname. No tenía idea de que mi ausencia te causaría a ti y a tu familia un daño indescriptible.",
  ui_story_5084_50841001_13_dialog_content = "Graves... ¿Wilhelm está realmente muerto?",
  ui_story_5084_50841001_14_dialog_content = "Clavis... ¿Qué has hecho?",
  ui_story_5084_50841001_15_dialog_content = "... Simplemente he venido para colocar otro cuerpo bajo tu cuidado.",
  ui_story_5084_50841001_16_dialog_content = "Por favor, cuida de mi amigo tonto.",
  ui_story_5084_50841001_17_dialog_content = "Llave... Llave...",
  ui_story_5084_50841001_18_dialog_content = "Lo vi con mis propios ojos, mi lady. Wilhelm estaba muerto... Y Clavis Ibrahim usó esa llave para entrar a la tumba y darle descanso.",
  ui_story_5084_50841001_19_dialog_content = "... Vamos adentro, Caelestite.",
  ui_story_5084_50841001_20_dialog_content = "Tienes mi palabra, Graves: Pondré fin a toda esta lucha esta noche.",
  ui_story_5084_50841001_21_dialog_content = "Por favor ten cuidado... Mi señora...",
  ui_story_5084_50841001_22_dialog_content = "En los confines más lejanos de la cripta... Continúan perturbando a los muertos... En busca de algo...",
  ui_story_5084_50841001_23_dialog_content = "Bueno, mira quién está aquí.",
  ui_story_5084_50841001_24_dialog_content = "La jovencita de los Varaki ella misma.",
  ui_story_5084_50841001_25_dialog_content = "... ¡Mi señora!",
  ui_story_5084_50841001_26_dialog_content = "Estoy sorprendido de que hayas sobrevivido, Vinekeeper...",
  ui_story_5084_50841001_27_dialog_content = "¿Porfirio desea deshacerse de la mujer Varaki, sí?",
  ui_story_5084_50841001_28_dialog_content = "Ahora es nuestra oportunidad.",
  ui_story_5084_50841001_29_dialog_content = "¡Secuaces tontos...!",
  ui_story_5084_50841001_30_dialog_content = "¡Cómo te atreves a irrumpir en la tumba de los Varaki y perturbar a nuestros antepasados durmientes!",
  ui_story_5084_50841001_31_dialog_content = "Tenía la intención de castigar a cada uno de ustedes durante el ritual de esta noche, pero parece que me han traído la pelea.",
  ui_story_5084_50841002_1_dialog_content = "Victoria... La llamada Undine se enterró bajo tierra y escapó...",
  ui_story_5084_50841002_2_dialog_content = "Hmph, eso solo deja a estos dos. ¿Estás listo para aceptar tus destinos?",
  ui_story_5084_50841002_3_dialog_content = "Espera, Dama Victoria... Como adulta y respetable miembro de los Varaki, ¿quizás deberías hablar con Porfirio antes de hacer algo precipitado?",
  ui_story_5084_50841002_4_dialog_content = "¡Imposible! Solo te fuiste por tres años... ¿De dónde obtuviste tal poder?!",
  ui_story_5084_50841002_5_dialog_content = "¿Tres años, dices? Parece que has estado atrapado en tu propio mundo estancado durante tanto tiempo que ya no puedes comprender cambios tan drásticos.",
  ui_story_5084_50841002_6_dialog_content = "He estado acumulando este poder durante mucho más tiempo que tres años... Pero no tengo intención de revelarte mis secretos.",
  ui_story_5084_50841002_7_dialog_content = "Por permitir que tus deseos te alejen de La Verdad, tus vidas deben ser ofrecidas como preludio a la Venida de la Verdad!",
  ui_story_5084_50841002_8_dialog_content = "(Sikare nos dijo que no cambiáramos nada, pero Victoria los mató a ambos... ¿Eso no cuenta como cambiar el pasado?!)",
  ui_story_5084_50841002_9_dialog_content = "(¿O podría ser... las acciones de Victoria fueron escritas en las páginas de la historia hace mucho tiempo?)",
  ui_story_5084_50841002_10_dialog_content = "¿Mmm?",
  ui_story_5084_50841002_11_dialog_content = "Parece que tampoco entiendes... el secreto de la víbora.",
  ui_story_5084_50841002_12_dialog_content = "Incluso si cortas mi cabeza, mudaré mi piel y naceré de nuevo...",
  ui_story_5084_50841002_13_dialog_content = "¡Entonces lo cortaré tantas veces como sea necesario!",
  ui_story_5084_50841002_14_dialog_content = "¡E-Espera! ¡No puedes matarme de esta manera!",
  ui_story_5084_50841002_15_dialog_content = "Nunca fue mi intención hacerlo. Simplemente tengo curiosidad por ver cuánto tiempo más puedes soportar el dolor de que te corten la cabeza.",
  ui_story_5084_50841002_16_dialog_content = "¡Ahora grita! ¡Suplica por misericordia! <size=45>¡Ruega que te libere de tu sufrimiento—!</size>",
  ui_story_5084_50841002_17_dialog_content = "(Vaya, Victoria... No me di cuenta de que ella podría ser tan cruel...)",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>De repente, uno de los ataúdes dentro de la cripta se abre violentamente, y una persona sale de él—</color>",
  ui_story_5084_50841002_19_dialog_content = "No hay necesidad de desperdiciar tu fuerza con alguien como él.",
  ui_story_5084_50841002_20_dialog_content = "¡¿?!",
  ui_story_5084_50841002_21_dialog_content = "... ¿¡W-Wilhelm?!?",
  ui_story_5084_50841002_22_dialog_content = "¡Imposible! ¡Se supone que debiste haber muerto hace mucho tiempo!",
  ui_story_5084_50841002_23_dialog_content = "... Así que todavía estás vivo después de todo.",
  ui_story_5084_50841002_24_dialog_content = "No exactamente. Tras mi muerte, pasé muchos años atravesando el flujo interminable de tiempo, y ahora finalmente tengo una leve idea de la voluntad de nuestro señor.",
  ui_story_5084_50841002_25_dialog_content = "La llegada de la Verdad hace tres años... Fuiste tú.",
  ui_story_5084_50841002_26_dialog_content = "Tres años... Un parpadeo en el gran esquema de la existencia. Fue el destino el que me guió aquí, y parece ser mi última parada.",
  ui_story_5084_50841002_27_dialog_content = "¡¿...?!",
  ui_story_5084_50841002_28_dialog_content = "(¡Lo sabía! ¡Realmente había dos Wilhelms todo el tiempo!)",
  ui_story_5084_50841002_29_dialog_content = "(Entonces, el que sacrificó a Victoria y arregló todo esto... ¿Fue Wilhelm después de su propia muerte?)",
  ui_story_5084_50841002_30_dialog_content = "Toma esto. Es un símbolo del deseo del destino de seguirte—",
  ui_story_5084_50841002_31_dialog_content = "... ¿La Biblia Sangrienta?",
  ui_story_5084_50841002_32_dialog_content = "No... Esto no se parece en nada a la reliquia que he llegado a conocer a lo largo de los años.",
  ui_story_5084_50841002_33_dialog_content = "Una nueva Biblia Sangrienta, destinada para aquel que guiará el futuro.",
  ui_story_5084_50841002_34_dialog_content = "Tómalo, porque tú eres el único que puede manejar su poder.",
  ui_story_5084_50841002_35_dialog_content = "Úsalo para derrotar a los tontos traidores que están frente a ti.",
  ui_story_5084_50841002_36_dialog_content = "... Me niego.",
  ui_story_5084_50841002_37_dialog_content = "¡¿...?!",
  ui_story_5084_50841002_38_dialog_content = "No necesito tu poder—Ellos fueron los que te mataron, así que tu venganza es tu propio asunto.",
  ui_story_5084_50841002_39_dialog_content = "¿Cuál es el significado de esto? ¿Por qué somos impotentes contra él?!",
  ui_story_5084_50841002_40_dialog_content = "Ese hombre no es el mismo hombre que matamos en el pasado.",
  ui_story_5084_50841002_41_dialog_content = "¡Maldito seas, Wilhelm! ¿Qué te sucedió exactamente después de que moriste?! Tienes que contarnos... ¡Al menos comparte esta Verdad con nosotros!",
  ui_story_5084_50841002_42_dialog_content = "...¡Silencio, traidores!",
  ui_story_5084_50841002_43_dialog_content = "¡La Verdad no necesita de tu comprensión!",
  ui_story_5084_50841002_44_dialog_content = "¡Solo exige tu sangre a cambio de tus crímenes contra los antepasados de los Varaki!",
  ui_story_5084_50841002_45_dialog_content = "Va... raki...",
  ui_story_5084_50841002_46_dialog_content = "(¡Wilhelm los destruyó a ambos con un solo ataque...!)",
  ui_story_5084_50841002_47_dialog_content = "Wilhelm Varaki... Se suponía que este ataúd contenía los restos de nuestros antepasados. ¿Qué te sucedió exactamente?",
  ui_story_5084_50841002_48_dialog_content = "¿Por qué desapareciste? ¿Y qué te hizo reaparecer ante nosotros hoy?",
  ui_story_5084_50841002_49_dialog_content = "¿Has renacido? ¿O eres solo un fantasma ahora?",
  ui_story_5084_50841002_50_dialog_content = "Eres tal como te recuerdo, Victoria: siempre tan lleno de preguntas.",
  ui_story_5084_50841002_51_dialog_content = "Desafortunadamente, ya no sirve de nada discutir estas cosas. El tiempo nos ha superado, y hace mucho que estamos muertos.",
  ui_story_5084_50841002_52_dialog_content = "Adiós, Victoria.",
  ui_story_5084_50841002_53_dialog_content = "(¿Se va así nomás...? Finalmente tienen la oportunidad de verse de nuevo y claramente se preocupan el uno por el otro... Entonces, ¿por qué no dicen nada?)",
  ui_story_5084_50841002_54_dialog_content = "¡P-Por favor espere, Sr. Wilhelm!",
  ui_story_5084_50841002_55_dialog_content = "Celestita...",
  ui_story_5084_50841002_56_dialog_content = "Y usted es...?",
  ui_story_5084_50841002_57_dialog_content = "Espera, esa voz...",
  ui_story_5084_50841002_58_dialog_content = "Ah... Ya veo...",
  ui_story_5084_50841002_59_dialog_content = "Esto debe ser el destino...",
  ui_story_5084_50841002_60_dialog_content = "Jejeje... Qué divertido...",
  ui_story_5084_50841002_61_dialog_content = "¡Señor Wilhelm! Puedes llamarlo \"destino\"-",
  ui_story_5084_50841002_62_dialog_content = "Pero cuando escuchaste sus palabras, aún decidiste perseguir La Verdad en tu corazón. Fuiste a la cripta porque estabas preocupado por Victoria!",
  ui_story_5084_50841002_63_dialog_content = "Y en lugar de aceptar su destino predeterminado, Victoria eligió llevar el anillo y soportar esas voces para encontrarte...",
  ui_story_5084_50841002_64_dialog_content = "Ya has logrado lo inimaginable al viajar de ida y vuelta en el tiempo; ¿realmente sería tan irrazonable que los dos tuvieran una conversación normal?",
  ui_story_5084_50841002_65_dialog_content = "Cuando luchaste hombro con hombro contra los jefes de las familias... pude ver las emociones que impulsaban tus acciones.",
  ui_story_5084_50841002_66_dialog_content = "Lo siento... No sé si estoy cambiando la historia al decir algo que no debería decir...",
  ui_story_5084_50841002_67_dialog_content = "Pero desde el fondo de mi corazón, creo en todo lo que estoy a punto de decir:",
  ui_story_5084_50841002_68_dialog_content = "Siempre he pensado que las palabras eran la mejor manera de guardar un secreto... Si no te abres el uno al otro ahora mismo, puede que nunca tengas la oportunidad de entenderos nunca más.",
  ui_story_5084_50841002_69_dialog_content = "...",
  ui_story_5084_50841002_70_dialog_content = "...",
  ui_story_5084_50841002_71_dialog_content = "Preguntas, respuestas... Ninguna de ellas realmente importa ahora. Todo lo que importa es que ustedes dos están aquí ahora mismo.",
  ui_story_5084_50841002_72_dialog_content = "Independientemente de si el \"destino\" lo decide o no, cada una de tus decisiones debería venir del corazón.",
  ui_story_5084_50841002_73_dialog_content = "Caelestita... Tú...",
  ui_story_5084_50841002_74_dialog_content = "Jeje, si tan solo el resto del mundo pudiera ser tan sincero como tú... Entonces quizás no se dejarían engañar tan fácilmente.",
  ui_story_5084_50841002_75_dialog_content = "Una sinceridad tan pura es uno de los mayores tesoros que pertenecen a los jóvenes Caelestitas.",
  ui_story_5084_50841002_76_dialog_content = "Ahora bien... ¿Por dónde empezar?",
  ui_story_5084_50841002_77_dialog_content = "He vagado a través del tiempo durante incontables eras... Y nunca he anhelado el final más de lo que lo hago ahora.",
  ui_story_5084_50841002_78_dialog_content = "Victoria... Finalmente entiendo el deseo de mi hermano por un sueño eterno, y creo que tú también lo entiendes.",
  ui_story_5084_50841002_79_dialog_content = "Las decisiones tomadas por nuestros corazones son más numerosas que las estrellas en el cielo.",
  ui_story_5084_50841002_80_dialog_content = "Debo agradecerte, Victoria... Algún día liberarás a los Varaki de su maldición de sangre, y finalmente podré descansar en paz.",
  ui_story_5084_50841002_81_dialog_content = "Es tan improbable que puedas expresar gratitud... ¿Seré realmente yo quien deshaga la maldición de nuestra familia...?",
  ui_story_5084_50841002_82_dialog_content = "Como dice el Caelestite, nuestras preguntas y respuestas...",
  ui_story_5084_50841002_83_dialog_content = "¡No son importantes ahora!",
  ui_story_5084_50841002_84_dialog_content = "La Verdad varía de persona a persona. No hay una respuesta final o absoluta; solo una creencia que debe ser perseguida constantemente.",
  ui_story_5084_50841002_85_dialog_content = "... Ahora puedes decir lo que piensas.",
  ui_story_5084_50841002_86_dialog_content = "Nuestro mundo está marcado por el sufrimiento y las diferencias. Aquellos bendecidos con la inmortalidad están consumidos por su deseo de muerte, mientras que sus contrapartes mortales anhelan futuros más largos.",
  ui_story_5084_50841002_87_dialog_content = "¿Realmente existe un salvador en <color=#FFB400>Eoria</color>?",
  ui_story_5084_50841002_88_dialog_content = "En mis visiones, he visto sufrimientos incontables, y sin embargo, mi creencia en la <color=#FFB400>salvación</color> solo se ha fortalecido debido a ello.",
  ui_story_5084_50841002_89_dialog_content = "Por lo tanto, La Verdad que busco debe llevar a la <color=#FFB400>salvación</color> del mundo, y la erradicación de cada semilla caída.",
  ui_story_5084_50841002_90_dialog_content = "Al trascender las limitaciones de la conciencia y la corporeidad, los Aurorianos alcanzarán su evolución final y se acercarán a las estrellas, donde la suprema Verdad espera su llegada.",
  ui_story_5084_50841002_91_dialog_content = "... Realmente has crecido y te has convertido en un líder digno, Victoria. Es tal como La Verdad me reveló.",
  ui_story_5084_50841002_92_dialog_content = "Mencionaste las estrellas... En el momento de mi desaparición, vi un río en la oscuridad.",
  ui_story_5084_50841002_93_dialog_content = "En él, la causalidad de toda existencia fluye sin fin. Incluso la perturbación más leve puede resultar en una catástrofe insondable.",
  ui_story_5084_50841002_94_dialog_content = "Como miembros de la familia inmortal de sangre, hemos pasado una cantidad desmesurada de tiempo persiguiendo algo que no es más que un grano de arena en este río.",
  ui_story_5084_50841002_95_dialog_content = "Aun así, mi obsesión implacable me llevó a ese río.",
  ui_story_5084_50841002_96_dialog_content = "Desde entonces he fortalecido La Verdad dentro de mi corazón, y aunque mi viaje ha sido uno de dificultades y sufrimiento, estoy convencido de que mis deseos eventualmente influirán en el flujo de la causalidad.",
  ui_story_5084_50841002_97_dialog_content = "¿Crees que tus convicciones son lo suficientemente poderosas para trascender las cadenas del destino?",
  ui_story_5084_50841002_98_dialog_content = "Sí. Los obedeceré, los practicaré y, finalmente... encontraré una forma de ver los diseños del destino y remodelarlos con mis propias manos.",
  ui_story_5084_50841002_99_dialog_content = "... Ahora ve, Victoria. Viaja por el camino de tu Verdad, y elimina cualquier obstáculo que se interponga en tu camino.",
  ui_story_5084_50841002_100_dialog_content = "Como seguramente lo haré.",
  ui_story_5084_50841002_101_dialog_content = "Entonces te dejo a David. Detenlo antes de que convierta nuestro pueblo en un lugar de muerte.",
  ui_story_5084_50841002_102_dialog_content = "¿A dónde vas a ir ahora?",
  ui_story_5084_50841002_103_dialog_content = "Ya soy un ser que existe fuera del flujo del tiempo. Solo puedo alterar los eventos de la historia si el destino lo permite...",
  ui_story_5084_50841002_104_dialog_content = "... Nunca esperé tener esta última discusión contigo, tío.",
  ui_story_5084_50841002_105_dialog_content = "Realmente has madurado, Victoria... Qué tranquilizador.",
  ui_story_5084_50841002_106_dialog_content = "Ahora, toma esta Biblia sangrienta en tus manos. La necesitarás.",
  ui_story_5084_50841002_107_dialog_content = "Ya tengo el poder que necesito para buscar la Verdad. No tengo razón para tomarlo.",
  ui_story_5084_50841002_108_dialog_content = "... Aun así, el destino te guiará hacia ello algún día.",
  ui_story_5084_50841002_109_dialog_content = "Adiós, Victoria Varaki.",
  ui_story_5084_50841002_110_dialog_content = "Tu discípulo, el llamado Nails... Se le puede enseñar mucho.",
  ui_story_5084_50841002_111_dialog_content = "Dejo el futuro de True Order en tus manos.",
  ui_story_5084_50841002_112_dialog_content = "... ¿Nos volveremos a ver alguna vez?",
  ui_story_5084_50841002_113_dialog_content = "Ya he completado la tarea que nuestro señor me asignó. Ahora, ha llegado el momento de atender mis propios asuntos.",
  ui_story_5084_50841002_114_dialog_content = "Cuando todas las cosas hayan terminado, ven a buscarme aquí.",
  ui_story_5084_50841002_115_dialog_content = "Y en cuanto a ti, Caelestite del futuro... Gracias por guiarme con tu sinceridad.",
  ui_story_5084_50841101_1_dialog_content = "Todo es culpa de la abuela... Insistió en hacerme escuchar sus oraciones al Señor de la Verdad antes de dejarme ir...",
  ui_story_5084_50841101_2_dialog_content = "¡Ahora estoy atrapado en la parte trasera de la multitud sin forma de ver la procesión!",
  ui_story_5084_50841101_3_dialog_content = "Tu abuela es demasiado mayor para participar en el Advenimiento de la Verdad, querida.",
  ui_story_5084_50841101_4_dialog_content = "Pero después de pasar toda su vida haciendo ropa para los fieles, todavía quiere que alguien presente sus deseos al Señor de la Verdad. Es por eso que te los confió.",
  ui_story_5084_50841101_5_dialog_content = "Te levantaré para ver el desfile, pero debes recordar las palabras de tu abuela. Esta es una ocasión sincera y debes tratarla como tal.",
  ui_story_5084_50841101_6_dialog_content = "... Entiendo.",
  ui_story_5084_50841101_7_dialog_content = "Esta calle es bastante familiar. Es donde me encontré con PlayerName antes.",
  ui_story_5084_50841101_8_dialog_content = "¿Pero cómo se supone que encontraremos Nails en una multitud enorme como esta?",
  ui_story_5084_50841101_9_dialog_content = "May... ¿Recuerdas haber visto a estas personas vestidas de manera extraña antes?",
  ui_story_5084_50841101_10_dialog_content = "D-Déjame pensarlo...",
  ui_story_5084_50841101_11_dialog_content = "¡¡¡Ah—!!!",
  ui_story_5084_50841101_12_dialog_content = "¿Qué fue eso? ¡Vamos a investigar, May!",
  ui_story_5084_50841101_13_dialog_content = "... ¡Son los no muertos! ¡Caminan entre nosotros—!",
  ui_story_5084_50841101_14_dialog_content = "Todopoderoso señor... Esto debe ser mi castigo por leer el diario secreto de mi hermana y revelar su hipocresía al público...",
  ui_story_5084_50841101_15_dialog_content = "Pero los líderes de la Orden Verdadera afirmaron que estaba enfermo y que nunca favorecerías mi sangre.",
  ui_story_5084_50841101_16_dialog_content = "¡Debo arrepentirme con mi carne...!",
  ui_story_5084_50841101_17_dialog_content = "Madre...?",
  ui_story_5084_50841101_18_dialog_content = "Pero te ruego que perdones a mi hija, señor. No es más que una niña inocente...",
  ui_story_5084_50841101_19_dialog_content = "¡Oh Señor de la Verdad!",
  ui_story_5084_50841101_20_dialog_content = "¿Son estos tus sirvientes? ¿Han venido... Para castigarme por mis pecados?",
  ui_story_5084_50841101_21_dialog_content = "Entiendo y me someto a tu voluntad divina. ¡Haz conmigo lo que debas!",
  ui_story_5084_50841101_22_dialog_content = "—!",
  ui_story_5084_50841101_23_dialog_content = "¡Madre—!",
  ui_story_5084_50841101_24_dialog_content = "¡¡¡Ah...!!!",
  ui_story_5084_50841101_25_dialog_content = "¡C-Corre, niño—!",
  ui_story_5084_50841101_26_dialog_content = "La sangre fluye por las calles. Estos monstruos con túnicas... ¡Están atacando a la gente del pueblo!",
  ui_story_5084_50841101_27_dialog_content = "¡May! ¡Prepárate para la batalla!",
  ui_story_5084_50841101_28_dialog_content = "Como pensé... Ahora que Lady Victoria ha tomado acción, el destino nos está permitiendo interferir.",
  ui_story_5084_50841101_29_dialog_content = "¡Me parece bien! ¡Hora de castigar a algunos niños traviesos!",
  ui_story_5084_50841101_30_dialog_content = "... ¡No siento dolor!",
  ui_story_5084_50841101_31_dialog_content = "¡Todavía hay tantos de ellos...!",
  ui_story_5084_50841101_32_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_33_dialog_content = "¡Mamá—!!!!",
  ui_story_5084_50841101_34_dialog_content = "No temas, mi corderito perdido... La Sangre Sagrada está a punto de condensarse y tomar forma...",
  ui_story_5084_50841101_35_dialog_content = "Eres tú... ¡El Iniciado! Pero, ¿por qué te estás lastimando?!",
  ui_story_5084_50841101_36_dialog_content = "Niño tonto... Este no es mi poder, y no soy este llamado \"Iniciado\". Yo soy Nails...",
  ui_story_5084_50841101_37_dialog_content = "El Señor de la Verdad me dijo que no sintiera ni piedad ni remordimiento.",
  ui_story_5084_50841101_38_dialog_content = "Aunque tu madre es una pecadora, igual que yo...",
  ui_story_5084_50841101_39_dialog_content = "¡Debo responder por todos los pecadores!",
  ui_story_5084_50841101_40_dialog_content = "¿Qué... qué es esto...?",
  ui_story_5084_50841101_41_dialog_content = "Es tanto un pecado... Como una bendición...",
  ui_story_5084_50841101_42_dialog_content = "Es el poder de la Sangre Sagrada... ¡El poder mencionado por mi mentor!",
  ui_story_5084_50841101_43_dialog_content = "Hierve con vida mientras corre por mis venas, quemándome con el calor infinito de nuestro señor!",
  ui_story_5084_50841101_44_dialog_content = "Mira, mi corderito perdido—",
  ui_story_5084_50841101_45_dialog_content = "¡El Señor de la Verdad nos absolverá de nuestros pecados!",
  ui_story_5084_50841101_46_dialog_content = "¡...!",
  ui_story_5084_50841101_47_dialog_content = "¡Eres tú... El Iniciado de antes hoy! Has ascendido y te has convertido en uno de los santos sagrados de nuestro señor!",
  ui_story_5084_50841101_48_dialog_content = "No... Por favor, no te refieras a mí de esa manera... Simplemente soy—",
  ui_story_5084_50841101_49_dialog_content = "Las túnicas que llevas puestas... Son las túnicas que mi madre y abuela confeccionaron solo para ti.",
  ui_story_5084_50841101_50_dialog_content = "Fue gracias a ti y a tu familia que pude convertirme en la persona que soy hoy.",
  ui_story_5084_50841101_51_dialog_content = "El Señor Wilhelm debió haber tenido sus razones en aquel entonces... ¡Pero este año, sin duda serás elegido como el Iniciado!",
  ui_story_5084_50841101_52_dialog_content = "Mi mentor me ha mostrado muchas verdades nobles, por las cuales estoy eternamente agradecido.",
  ui_story_5084_50841101_53_dialog_content = "Ahora por favor, abandona este lugar antes de que el peligro regrese. Todo estará bien, te lo aseguro.",
  ui_story_5084_50841101_54_dialog_content = "Muy bien. May Que la Verdad te bendiga ahora y siempre, Santo Nails!",
  ui_story_5084_50841101_55_dialog_content = "May Que la Verdad te bendiga, Santo Nails!",
  ui_story_5084_50841101_56_dialog_content = "May La Verdad te bendiga también.",
  ui_story_5084_50841101_57_dialog_content = "\"¿Santo Nails,\" eh?",
  ui_story_5084_50841101_58_dialog_content = "Vimos cómo derrotabas a esos monstruos desde lejos.",
  ui_story_5084_50841101_59_dialog_content = "¿Oh? May, Faust... Ha pasado bastante tiempo, ¿no?",
  ui_story_5084_50841101_60_dialog_content = "¡Yo... Yo solo me alegro de que estés bien!",
  ui_story_5084_50841101_61_dialog_content = "¡PlayerName y yo estábamos tan preocupados por ti!",
  ui_story_5084_50841101_62_dialog_content = "Fue mi culpa por sobreestimar mis habilidades... Te causé preocupación innecesaria... Y por eso debo arrepentirme...",
  ui_story_5084_50841101_63_dialog_content = "¡Tu poder de hace un momento fue increíble! ¿Tiene algo que ver con estas túnicas?",
  ui_story_5084_50841101_64_dialog_content = "Posiblemente... Durante los últimos tres años, he estado usando las túnicas confeccionadas para mí por esa familia de costureras.",
  ui_story_5084_50841101_65_dialog_content = "¿Q-Quieres decir que nunca fuiste a ningún otro lugar? En otras palabras... ¿Has estado sentado en la ciudad de Varaki durante tres años enteros?!",
  ui_story_5084_50841101_66_dialog_content = "No estando sentado, May, sino practicando con mi mentor... Me llevó a muchos lugares diferentes... No solo en la ciudad, tampoco.",
  ui_story_5084_50841101_67_dialog_content = "Tu mentor...",
  ui_story_5084_50841101_68_dialog_content = "¿Es por su entrenamiento que ahora puedes condensar y remodelar tu sangre de esta manera?",
  ui_story_5084_50841101_69_dialog_content = "En efecto... Mi mentor afirma que mi Sangre Rara es cualquier cosa menos una maldición...",
  ui_story_5084_50841101_70_dialog_content = "\"En donde pierdes, aquí ganas. En donde expías, aquí eres bendecido.\"",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>Hace tres años...</color>",
  ui_story_5084_50841102_2_dialog_content = "Oh Señor de la Verdad, tu humilde servidor Nails te suplica que lo liberes de su sufrimiento una vez más...",
  ui_story_5084_50841102_3_dialog_content = "Una vil presencia impregna mi sangre... Hace mucho tiempo que estoy listo para el final...",
  ui_story_5084_50841102_4_dialog_content = "Qué es esto...?",
  ui_story_5084_50841102_5_dialog_content = "Aunque Lady Victoria una vez dijo que mi piedad me guiaría... anhelo el sacrificio...",
  ui_story_5084_50841102_6_dialog_content = "Voy a...",
  ui_story_5084_50841102_7_dialog_content = "...",
  ui_story_5084_50841102_8_dialog_content = "... ¿Mi señor?",
  ui_story_5084_50841102_9_dialog_content = "¡Eres tú! ¡El todopoderoso Señor de la Verdad!",
  ui_story_5084_50841102_10_dialog_content = "¿Acabas de decir... Dama Victoria?",
  ui_story_5084_50841102_11_dialog_content = "Soy solo un pecador descarado... Pero mis faltas no preocuparon a Lady Victoria.",
  ui_story_5084_50841102_12_dialog_content = "Ella me acogió y me bendijo con la compañía de la True Order... Sin embargo, le devuelvo su bondad permitiendo que mi sangre manchada contamine este mundo.",
  ui_story_5084_50841102_13_dialog_content = "Entonces, esta Lady Victoria es la líder del Orden Verdadero, ¿y tú eres uno de sus miembros?",
  ui_story_5084_50841102_14_dialog_content = "Sí, mi señor... Mi nombre es Nails.",
  ui_story_5084_50841102_15_dialog_content = "¿Eres el único en esta cripta?",
  ui_story_5084_50841102_16_dialog_content = "No, mi señor. Estoy acompañado por Lady Victoria, Faust, May y el Celestita... Entramos juntos en la cripta, pero nos separamos poco después.",
  ui_story_5084_50841102_17_dialog_content = "Son valientes, amables y llenos de luz... Estoy seguro de que los guiaste a donde necesitaban estar, mi señor...",
  ui_story_5084_50841102_18_dialog_content = "\"Para servir como guía para La Verdad...\"",
  ui_story_5084_50841102_19_dialog_content = "Seguiste tus propios caminos... Me sorprende que un Celestita se haya unido al Orden Verdadero...",
  ui_story_5084_50841102_20_dialog_content = "\"La Verdad se ha revelado en su corazón y lo ha bendecido. Él es un agente de cambio dentro de True Order.\"",
  ui_story_5084_50841102_21_dialog_content = "Ser bendecido por la Verdad...",
  ui_story_5084_50841102_22_dialog_content = "¿Deseas confesar algo al Señor de la Verdad?",
  ui_story_5084_50841102_23_dialog_content = "Confieso... Que he pecado desde el mismo momento en que nací. Véalo por usted mismo, mi señor...",
  ui_story_5084_50841102_24_dialog_content = "Solo una criatura pecadora como yo estaría maldita con sangre tan manchada...",
  ui_story_5084_50841102_25_dialog_content = "Palabras tan tontas...",
  ui_story_5084_50841102_26_dialog_content = "¿M-Mi señor...?",
  ui_story_5084_50841102_27_dialog_content = "El sol aún brilla sobre la tierra. Tengo tiempo para escuchar tu pecaminoso pasado.",
  ui_story_5084_50841102_28_dialog_content = "No necesitas preocuparte por mis acciones, ahora habla.",
  ui_story_5084_50841102_29_dialog_content = "Solo te pido que guardes ese clavo. Esta es la tumba de los Varaki, y no te permitiré derramar tu sangre en ella.",
  ui_story_5084_50841102_30_dialog_content = "¡Como ordenes, Señor de la Verdad!",
  ui_story_5084_50841102_31_dialog_content = "Además, no soy el Señor de la Verdad.",
  ui_story_5084_50841102_32_dialog_content = "¿No? ¿Entonces quién eres tú—?",
  ui_story_5084_50841102_33_dialog_content = "Mi nombre es Wilhelm Varaki, aunque ese apellido apenas es adecuado para un hombre como yo.",
  ui_story_5084_50841102_34_dialog_content = "... ¿\"Varaki\"?! ¡Compartes el mismo glorioso apellido que Lady Victoria!",
  ui_story_5084_50841102_35_dialog_content = "\"¿Glorioso\", dices? Jeje, no es más que un nombre usado para intimidar a otros.",
  ui_story_5084_50841102_36_dialog_content = "La persona que ves ante ti es alguien con vínculos intrincados con la True Order, un ser que existe más allá del flujo del tiempo.",
  ui_story_5084_50841102_37_dialog_content = "Ahora dime, ¿quién es el que te ve como un monstruo?",
  ui_story_5084_50841102_38_dialog_content = "Mi hermano... Mis padres... Mi familia entera...",
  ui_story_5084_50841102_39_dialog_content = "¿Y todo esto es por la llamada \"Sangre Rara\" que fluye en tus venas?",
  ui_story_5084_50841102_40_dialog_content = "Si... Pero también porque mi mera existencia causó daño a mi hermano y vergüenza a mi familia.",
  ui_story_5084_50841102_41_dialog_content = "Mi hermano fue una vez un miembro amable y valiente de la Orden, al igual que mis compañeros...",
  ui_story_5084_50841102_42_dialog_content = "En el pasado, parecía estar en el camino hacia la riqueza y la gloria debido a mis poderes, que me permitieron superar a muchos otros caballeros en duelos.",
  ui_story_5084_50841102_43_dialog_content = "Mi hermano, sin embargo, no tuvo tanta suerte...",
  ui_story_5084_50841102_44_dialog_content = "Cuando el hijo de una familia rival lo atacó, intenté protegerlo sin darme cuenta del alcance de mis propios poderes...",
  ui_story_5084_50841102_45_dialog_content = "¡Y como resultado...!",
  ui_story_5084_50841102_46_dialog_content = "Mi pobre hermano... Sabía lo vergonzoso que habría sido para nuestra familia... Si un pecador como yo continuara viviendo en esa ciudad pura y noble.",
  ui_story_5084_50841102_47_dialog_content = "Así que decidió liberarme, dejando que mi \"sangre rara\" se manifestara y posteriormente... me desterró de Lumopolis.",
  ui_story_5084_50841102_48_dialog_content = "¿Dónde he visto eso antes...",
  ui_story_5084_50841102_49_dialog_content = "¿Entonces te moviste antes de que Victoria te reclutara en el True Order?",
  ui_story_5084_50841102_50_dialog_content = "Sí, aunque había esperado morir en la guerra entre Aurorians y Eclipsites.",
  ui_story_5084_50841102_51_dialog_content = "Pero el Señor debió haberme considerado un pecador, ya que la Sangre Rara me sacaba del coma una y otra vez para recordarme...",
  ui_story_5084_50841102_52_dialog_content = "Aún no he expiado... Todavía no puedo regresar al Señor de la Verdad.",
  ui_story_5084_50841102_53_dialog_content = "...",
  ui_story_5084_50841102_54_dialog_content = "¿Dijiste demasiado? Lo siento, Sr. Wilhelm, pensé, bastante ingenuamente, que había sido perdonado y estaba de nuevo en las buenas gracias del Señor.",
  ui_story_5084_50841102_55_dialog_content = "Tu historia suena como si hubieras nacido en una familia noble y muy talentosa para mí.",
  ui_story_5084_50841102_56_dialog_content = "Pero ese inepto hermano tuyo guardaba rencor contra ti y quería ser el patriarca, por lo tanto, planeaba eliminarte.",
  ui_story_5084_50841102_57_dialog_content = "Se ha hecho cargo como patriarca ahora, ¿no es así?",
  ui_story_5084_50841102_58_dialog_content = "Oh, se lo merecía, y no fue un \"complot para eliminar\".",
  ui_story_5084_50841102_59_dialog_content = "Bueno, tengo mis dudas... ¿Niño de Lumopolis, amable, valiente, optimista?",
  ui_story_5084_50841102_60_dialog_content = "El duodécimo jefe de True Order es un hereje rechazado por Lumopolis.",
  ui_story_5084_50841102_61_dialog_content = "Sin ese hereje, no existiría el actual True Order.",
  ui_story_5084_50841102_62_dialog_content = "En efecto, soy el hereje rechazado por Lumopolis, pero mi hermano...",
  ui_story_5084_50841102_63_dialog_content = "Dime, ¿qué emoción mostró ella cuando te fuiste?",
  ui_story_5084_50841102_64_dialog_content = "...",
  ui_story_5084_50841102_65_dialog_content = "Apuesto a que nunca olvidarías cómo te miraba él, a quien hizo todo lo posible para arruinarte, cuando te exiliaste.",
  ui_story_5084_50841102_66_dialog_content = "Sonrió y me deseó lo mejor.",
  ui_story_5084_50841102_67_dialog_content = "Je, siempre podrían encontrar algo de lo que culparte, cuando quieren intimidarte o perseguirte.",
  ui_story_5084_50841102_68_dialog_content = "Por lo tanto, pensaste que eras irredimible y te uniste al True Order, mientras te aferrabas a la culpa y tormento propios.",
  ui_story_5084_50841102_69_dialog_content = "La raíz de tu penitencia es el auto-odio. ¡Detestas la Sangre Rara!",
  ui_story_5084_50841102_70_dialog_content = "Y la raíz de mi odio es la esperanza que tienes para esos malhechores, que hablaron mal de ti y aún así tomaste eso por la verdad.",
  ui_story_5084_50841102_71_dialog_content = "Permíteme decirte, la Sangre Rara no es una maldición sino una bendición del Señor de la Verdad.",
  ui_story_5084_50841102_72_dialog_content = "El hecho de que te ayudaron a matar a los Eclipsites es prueba. No tengas ninguna duda al respecto. No tienes ninguna razón para odiarte a ti mismo.",
  ui_story_5084_50841102_73_dialog_content = "No merecía ser tu hermano, Nails. Pero lo triste es que eres un buen hermano.",
  ui_story_5084_50841102_74_dialog_content = "Los hermanos traicionan y se separan el uno del otro... El destino decretó que nos encontráramos aquí, Wilhelm Varaki.",
  ui_story_5084_50841102_75_dialog_content = "¡Realmente te aseguraste de burlarte de mí otra vez!",
  ui_story_5084_50841102_76_dialog_content = "Escucha con atención, Nails. Eres amable y valiente, pero un poco corto de dulzura. ¿Cómo suena Hails? Está cerca de tu nombre.",
  ui_story_5084_50841102_77_dialog_content = "Disfrutarás de la verdadera salvación si eliges proteger a otros con tu Sangre Rara.",
  ui_story_5084_50841102_78_dialog_content = "Eres muy atrevido para sentirte así, pero yo...",
  ui_story_5084_50841102_79_dialog_content = "Puedes manejarlo—",
  ui_story_5084_50841102_80_dialog_content = "...",
  ui_story_5084_50841102_81_dialog_content = "El Señor no muestra favoritismo hacia nadie. Si no puedes perdonarte a ti mismo, ¿cómo puede Él redimirte?",
  ui_story_5084_50841102_82_dialog_content = "Recuerda, solo cuando te reconozcas a ti mismo, el Señor te reconocerá.",
  ui_story_5084_50841102_83_dialog_content = "¿Por qué me dices todo esto, Sr. Wilhelm?",
  ui_story_5084_50841102_84_dialog_content = "Porque sé que nuestro encuentro aquí ha cambiado algo para siempre.",
  ui_story_5084_50841102_85_dialog_content = "Creo firmemente que es el Señor quien te envió aquí.",
  ui_story_5084_50841102_86_dialog_content = "Entonces esto no es el fin para ti, Nails, sino el comienzo de tu devoción. ¿Aprenderás conmigo?",
  ui_story_5084_50841102_87_dialog_content = "Haré cualquier cosa para limpiarme de los pecados.",
  ui_story_5084_50841102_88_dialog_content = "Bueno. Entonces comencemos. Tenemos mucho que hacer, pero no aquí.",
  ui_story_5084_50841102_89_dialog_content = "Este es el lugar donde termina el pasado, y tus tres años de cultivo comenzaron con la Venida de la Verdad a tu llegada.",
  ui_story_5084_50841102_90_dialog_content = "Tu líder ha regresado allí. Acuéstate dentro del ataúd detrás de mí y recuerda el Advenimiento de la Verdad en Varaki, donde encontrarás a tus compañeros.",
  ui_story_5084_50841102_91_dialog_content = "Cuando abras tus ojos de nuevo, encuéntrame en la Venida de la Verdad. Me aseguraré de que te inicies y recibas las bendiciones de la Verdad.",
  ui_story_5084_50841102_92_dialog_content = "¿Cómo llego allí?",
  ui_story_5084_50841102_93_dialog_content = "A través de tu fe, Nails.",
  ui_story_5084_50841102_94_dialog_content = "Es tu fe lo que te trajo aquí. Solo siéntelo con tu cuerpo.",
  ui_story_5084_50841102_95_dialog_content = "Cuando renaces con cualquier bendición o celebración, has descubierto La Verdad.",
  ui_story_5084_50841102_96_dialog_content = "¿Te refieres a la fe...?",
  ui_story_5084_50841102_97_dialog_content = "Sí. A partir de ahora, soy tu mentor.",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>At the entrance to a tailor's shop in Varaki Town</color>",
  ui_story_5084_50841102_99_dialog_content = "¿Como llegué aquí?",
  ui_story_5084_50841102_100_dialog_content = "Are you here for the ceremonial robe, sir?",
  ui_story_5084_50841102_101_dialog_content = "Ceremonial robe...?",
  ui_story_5084_50841102_102_dialog_content = "No es de extrañar que hablaras en palabras que no entendemos... Conoces al Sr. Wilhelm desde hace mucho tiempo, veo.",
  ui_story_5084_50841102_103_dialog_content = "Y el más enigmático de todos.",
  ui_story_5084_50841102_104_dialog_content = "No puedo creer que realmente pensé que fui elegido para la iniciación... y realmente entré en el salón con esa idea.",
  ui_story_5084_50841102_105_dialog_content = "Todavía no puedo creer todo lo que me está pasando. Ni siquiera sé cuándo fue la primera vez que vi a mi mentor.",
  ui_story_5084_50841102_106_dialog_content = "Pero cuando él me envió de regreso al Advenimiento de la Verdad, ese hombre no me reconoció...",
  ui_story_5084_50841102_107_dialog_content = "¿Y luego, Nails? ¿Qué pasó después de que Wilhelm te expulsó de la iglesia?",
  ui_story_5084_50841102_108_dialog_content = "...",
  ui_story_5084_50841102_109_dialog_content = "Oh, que toda la sangre pecaminosa se drene de mí... Nunca volveré a rezar por la redención del Señor...",
  ui_story_5084_50841102_110_dialog_content = "Soy un pecador... Pecados imperdonables...",
  ui_story_5084_50841102_111_dialog_content = "Soy un monstruo que trae la perdición a todos, incluso aquí.",
  ui_story_5084_50841102_112_dialog_content = "En mi prisa por llegar al Advenimiento de la Verdad, decepcioné a la costurera y a su hija.",
  ui_story_5084_50841102_113_dialog_content = "Perdieron la oportunidad de ganarse la vida porque me conocieron...",
  ui_story_5084_50841102_114_dialog_content = "Esas personas vieron a través de mí, no aprobaron mi iniciación y en cambio querían matarme...",
  ui_story_5084_50841102_115_dialog_content = "No soy un iniciado... Soy el culpable de los problemas entre mi mentor y la Orden.",
  ui_story_5084_50841102_116_dialog_content = "Dondequiera que vaya, soy rechazado...",
  ui_story_5084_50841102_117_dialog_content = "¡Aghhhh!",
  ui_story_5084_50841102_118_dialog_content = "Mis manos y pies se están entumeciendo... El frío que acabo de sentir ahora es un calor que he estado extrañando...",
  ui_story_5084_50841102_119_dialog_content = "También podría...",
  ui_story_5084_50841102_120_dialog_content = "Moriría en silencio con mis pecados. No más problemas para el mundo.",
  ui_story_5084_50841102_121_dialog_content = "Yo...",
  ui_story_5084_50841102_122_dialog_content = "Estoy reflexionando si no me he aclarado.",
  ui_story_5084_50841102_123_dialog_content = "¿...?",
  ui_story_5084_50841102_124_dialog_content = "¿Por qué odias tanto un regalo tan maravilloso como la Sangre Rara?",
  ui_story_5084_50841102_125_dialog_content = "¿Mentor? ¡Mi mentor! ¡Estás bien!",
  ui_story_5084_50841102_126_dialog_content = "No te muevas. Deja que eche un vistazo a tu herida.",
  ui_story_5084_50841102_127_dialog_content = "Fui yo a quien conociste, pero no el yo original ni el yo presente.",
  ui_story_5084_50841102_128_dialog_content = "He estado observando los eventos todo el tiempo y aún no puedo descifrar de qué eres culpable.",
  ui_story_5084_50841102_129_dialog_content = "Estoy seguro de que puedes notar que tengo monstruos dentro de mí...",
  ui_story_5084_50841102_130_dialog_content = "¿Monstruos? Incluso el yo del pasado podría reconocer cuán terriblemente poderoso eres y que estás destinado a estar con la True Order.",
  ui_story_5084_50841102_131_dialog_content = "Deberías saber que el futuro que veo para la Orden es una congregación de lo excéntrico pero elegante, sensato pero sabio.",
  ui_story_5084_50841102_132_dialog_content = "Mientras sigas descubriendo tu propia singularidad, el tiempo te llevará al lugar correcto y a las personas correctas.",
  ui_story_5084_50841102_133_dialog_content = "Te lo dije, estás aprendiendo conmigo. Todo lo que has experimentado también es parte de ese proceso.",
  ui_story_5084_50841102_134_dialog_content = "Veo que no me tomaste en serio e intentaste matarte por culpa.",
  ui_story_5084_50841102_135_dialog_content = "Castígame, por favor... No seguí lo que te prometí, mi mentor...",
  ui_story_5084_50841102_136_dialog_content = "Está bien. Fuiste humillado, lo que te hizo desviarte del camino. No es tu culpa.",
  ui_story_5084_50841102_137_dialog_content = "Pero ahora que has llegado al lugar correcto, debes brillar con tus habilidades únicas.",
  ui_story_5084_50841102_138_dialog_content = "¿Yo...?",
  ui_story_5084_50841102_139_dialog_content = "Piensa cuidadosamente. Dejando a todos los demás de lado, ¿ha intentado Rare Blood hacerte daño en algún momento?",
  ui_story_5084_50841102_140_dialog_content = "...",
  ui_story_5084_50841102_141_dialog_content = "La abundancia que hace caer en desgracia a los privilegiados es quizás lo que salvará a los desplazados.",
  ui_story_5084_50841102_142_dialog_content = "Eres tú quien ha estado dañando tu alma con los pecados de los demás, pasando por alto la misma cosa que intenta salvarte a ti y a ellos.",
  ui_story_5084_50841102_143_dialog_content = "¿Por qué no creerías que la Sangre Rara podría matar monstruos y salvar a otros?",
  ui_story_5084_50841102_144_dialog_content = "Ellos me evitarán... despreciarán mi...",
  ui_story_5084_50841102_145_dialog_content = "Ellos de nuevo... Escucha, esa idea pertenece al pasado. No caigas en ello nunca más.",
  ui_story_5084_50841102_146_dialog_content = "Para citarte, \"Haré cualquier cosa para limpiarme de los pecados.\" Entonces, el primer paso es creer que no tienes pecado.",
  ui_story_5084_50841102_147_dialog_content = "¿Puedes hacer eso?",
  ui_story_5084_50841102_148_dialog_content = "Señor Wilhelm...",
  ui_story_5084_50841102_149_dialog_content = "Sí, sé que definitivamente eres lo suficientemente inteligente para entender eso.",
  ui_story_5084_50841102_150_dialog_content = "Sígueme de vuelta a mi domicilio. Está perfectamente aislado.",
  ui_story_5084_50841102_151_dialog_content = "Desde allí, puedes llegar a muchos pueblos para buscar y ayudar a las ovejas perdidas.",
  ui_story_5084_50841102_152_dialog_content = "Sálvalos con tu poder. Guíalos para su alabanza de la Sangre Rara.",
  ui_story_5084_50841102_153_dialog_content = "La Sangre Rara es bendecida por la Verdad. Con el tiempo, podrás entenderlo a través de la meditación.",
  ui_story_5084_50841102_154_dialog_content = "Entiendo...",
  ui_story_5084_50841102_155_dialog_content = "Por lo tanto, he estado vagando durante los últimos tres años, controlando mi temperamento y escuchando lo que dicen los demás.",
  ui_story_5084_50841102_156_dialog_content = "Noté que mi Sangre Rara cambió lentamente después de curar el dolor de los demás.",
  ui_story_5084_50841102_157_dialog_content = "Pero no fue hasta que ayudé a la costurera y a su hija hace un momento que me di cuenta de que los tres años estuvieron bien invertidos.",
  ui_story_5084_50841102_158_dialog_content = "En todos estos años con la True Order, no escuchaba y simplemente reiteraba mi arrepentimiento.",
  ui_story_5084_50841102_159_dialog_content = "Fue mi mentor quien descubrió la raíz de mis pecados. Estaba demasiado ocupado hablando para escuchar La Verdad.",
  ui_story_5084_50841102_160_dialog_content = "Mis palabras negativas moldearon mis pensamientos y profundizaron mi culpa...",
  ui_story_5084_50841102_161_dialog_content = "No sabía lo que realmente era La Verdad. Por eso se negó a manifestarse en mí.",
  ui_story_5084_50841102_162_dialog_content = "Ahora me doy cuenta de que la Verdad ha sido parte de mi fe todo este tiempo.",
  ui_story_5084_50841102_163_dialog_content = "Al igual que el dolor, la Verdad nunca mostró prejuicios hacia nadie.",
  ui_story_5084_50841102_164_dialog_content = "Lo que perdí, se suponía que debía perder. Lo que gané, se suponía que debía ganar.",
  ui_story_5084_50841102_165_dialog_content = "Uno debe haber cometido pecado para arrepentirse. Las bendiciones de los discípulos me permitieron ser ungido con la Santa Sangre.",
  ui_story_5084_50841102_166_dialog_content = "Para ser honesto, no entiendo la mitad de lo que dijiste, Sr. Nails...",
  ui_story_5084_50841102_167_dialog_content = "Pero me siento reconfortado por tu comportamiento como si acabara de tomar un baño caliente.",
  ui_story_5084_50841102_168_dialog_content = "Es mi mentor quien me hizo creer que la Sangre Rara no es un pecado sino sagrado, porque el Señor de la Verdad está conmigo en todo momento.",
  ui_story_5084_50841102_169_dialog_content = "A Lady Victoria le complacerá conocer los cambios en ti.",
  ui_story_5084_50841102_170_dialog_content = "Pero no sé cómo le van las cosas a ella.",
  ui_story_5084_50841102_171_dialog_content = "¡Creo en Lady Victoria! Más importante aún, creo que puedo ser de gran ayuda para ella!",
  ui_story_5084_50841102_172_dialog_content = "Mi mentor ha puesto mi entrenamiento en pausa. Necesito hacer algo importante para la True Order con mi poder.",
  ui_story_5084_50841102_173_dialog_content = "Ven, quiero llevar mi alegría a Lady Victoria así como a más discípulos.",
  ui_story_5084_50841201_1_dialog_content = "Incluso si nadie más vuelve a montar en mi tren, te prometo que convenceré a Papá para que te lleve de viaje a Astra.",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>Chapoteo, chapoteo....</color>",
  ui_story_5084_50841201_3_dialog_content = "Espera, déjame cerrar la ventana.",
  ui_story_5084_50841201_4_dialog_content = "¡Whoa!",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5084_50841201_6_dialog_content = "Es raro. Estos repugnantes gusanos han estado rondando por aquí últimamente...",
  ui_story_5084_50841201_7_dialog_content = "Pero Papá solo me dijo que cerrara las ventanas y nada más. Ni siquiera sé dónde está ahora mismo.",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>La luna de sangre colgaba alta sobre la Ciudad de Varaki como un reloj eterno, sonando para la Venida de la Verdad a medianoche.</color>",
  ui_story_5084_50841201_9_dialog_content = "Esto es simplemente surrealista. ¿Por qué no puede suceder esto todos los días de mi vida...?",
  ui_story_5084_50841201_10_dialog_content = "¿Te refieres a la designación de un nuevo líder para True Order? Hay menciones de alguien que fue asesinado hace poco tiempo.",
  ui_story_5084_50841201_11_dialog_content = "No es inusual que el liderazgo cambie. Pero me preocupa más cómo los que están a cargo siempre excluyen a todos los que no son de herencia Varaki.",
  ui_story_5084_50841201_12_dialog_content = "Quizás el resplandor de esta luna de sangre brilla solo en esa línea de sangre.",
  ui_story_5084_50841201_13_dialog_content = "Nunca depende de nosotros llegar al ataúd en el Salón de la Verdad y escuchar la conferencia del Señor.",
  ui_story_5084_50841201_14_dialog_content = "No caigas en la teoría de conspiración de linaje. El Señor rechazó a la hija mayor de los Varakis hace tres años.",
  ui_story_5084_50841201_15_dialog_content = "Y eligió a otro seguidor en reclusión en su lugar. Ahora es un santo y redime a otros a través del poder del Señor.",
  ui_story_5084_50841201_16_dialog_content = "Se dice que él no es de aquí. Tal vez La Verdad puede proliferar fuera de la ciudad de Varaki.",
  ui_story_5084_50841201_17_dialog_content = "Esto es realmente motivador. El jefe del pueblo parece estar enfrentando una reforma también.",
  ui_story_5084_50841201_18_dialog_content = "Si es Porfirio esta noche, La Orden Verdadera va a tener dificultades por delante...",
  ui_story_5084_50841201_19_dialog_content = "El mundo está cambiando, y también lo está la Verdad. May bendiga nuestro hogar.",
  ui_story_5084_50841201_20_dialog_content = "Todavía no hay señales de Lady Victoria y PlayerName... Espero que no les pase nada.",
  ui_story_5084_50841201_21_dialog_content = "Lady Victoria nunca ha faltado a sus palabras. Quizás esté demasiado abarrotado ahora, y lo mostrará después de que los discípulos se dispersen.",
  ui_story_5084_50841201_22_dialog_content = "No. Dada la situación, no creo que ella tenga ninguna razón para ocultarse.",
  ui_story_5084_50841201_23_dialog_content = "PlayerName también está presente y debería destacarse en la multitud.",
  ui_story_5084_50841201_24_dialog_content = "¡El señor Faust tiene razón! Tengo la sensación de que presenciaré un milagro de la True Order esta noche!",
  ui_story_5084_50841201_25_dialog_content = "¡Qué historia tendré para Lenore!",
  ui_story_5084_50841201_26_dialog_content = "A pesar de la reciente ola de asesinatos en la ciudad, los seguidores aún acuden al evento.",
  ui_story_5084_50841201_27_dialog_content = "Supongo que esa es la tradición de True Order extendiéndose hasta el Calendario Matutino 2000 para ti.",
  ui_story_5084_50841201_28_dialog_content = "Permaneceré vigilante y me aseguraré de que todos los discípulos permanezcan seguros durante toda la ceremonia.",
  ui_story_5084_50841201_29_dialog_content = "Ha pasado mucho tiempo, y la Dama Victoria aún no está aquí.",
  ui_story_5084_50841201_30_dialog_content = "¿Viste que esa chica Varaki está en la ceremonia?",
  ui_story_5084_50841201_31_dialog_content = "Sí, y también llevar un atuendo hermoso... ¡Eso es una violación de las reglas de True Order!",
  ui_story_5084_50841201_32_dialog_content = "(¿Volvió y se cambió? ¿Dónde está ella?)",
  ui_story_5084_50841201_33_dialog_content = "Siempre hay problemas entre ella y su tío. Es normal que ella no siga las reglas.",
  ui_story_5084_50841201_34_dialog_content = "¿Los Varakis van a cambiar de líder?",
  ui_story_5084_50841201_35_dialog_content = "No puede ser... Escuché que Lady Victoria volvió específicamente para liderar el True Order.",
  ui_story_5084_50841201_36_dialog_content = "¿De verdad? Pero en el Advenimiento de la Verdad hace tres años, ¿no lo hizo ella...",
  ui_story_5084_50841201_37_dialog_content = "¿Quién sabe? Fue ella quien se metió en el ataúd, no nosotros.",
  ui_story_5084_50841201_38_dialog_content = "No puedo explicar esto, pero han pasado cientos de años y me siento más cómodo con un Varaki liderando el True Order.",
  ui_story_5084_50841201_39_dialog_content = "Lamento haberte hecho esperar.",
  ui_story_5084_50841201_40_dialog_content = "Vaya... ¿Te esforzaste en cambiarte a algo apropiado para el evento?",
  ui_story_5084_50841201_41_dialog_content = "No exactamente. Este vestido es un regalo de aquellos que aún extrañan a Varakis y saben que estoy en la ciudad.",
  ui_story_5084_50841201_42_dialog_content = "Algo tan fino no puede ser hecho por una o dos personas en tan poco tiempo.",
  ui_story_5084_50841201_43_dialog_content = "Quizás la parte involucrada está tratando de expresar su objeción al poderoso círculo de líderes a través de esto.",
  ui_story_5084_50841201_44_dialog_content = "Entonces, para apreciar su esfuerzo y demostrar que tienes lo que se necesita para liderar la Orden...",
  ui_story_5084_50841201_45_dialog_content = "¿Tienes que ponerte esto para la ceremonia de esta noche?",
  ui_story_5084_50841201_46_dialog_content = "La autoridad no tiene nada que ver con los trajes. Puedo exhibir mi poder en cualquier disfraz, viejo o nuevo.",
  ui_story_5084_50841201_47_dialog_content = "Pero los cambios emocionantes son exactamente lo que ha estado perdiendo este histórico pueblo.",
  ui_story_5084_50841201_48_dialog_content = "Como la Biblia Sangrienta, el anillo y la luna de sangre, todo es un medio para marcar los momentos que las personas creían que eran importantes.",
  ui_story_5084_50841201_49_dialog_content = "Si a los líderes les disgustan tales cambios notables, entonces eso es exactamente lo que les mostraré.",
  ui_story_5084_50841201_50_dialog_content = "Para ellos, una mujer que adopta una imagen extravagante está despidiendo a su sumiso pasado.",
  ui_story_5084_50841201_51_dialog_content = "Sí. Solo quiero decir que el atuendo te queda como un guante.",
  ui_story_5084_50841201_52_dialog_content = "¡PlayerName! ¡PlayerName!",
  ui_story_5084_50841201_53_dialog_content = "¡Eres tú!",
  ui_story_5084_50841201_54_dialog_content = "¡Sí, es Lady Victoria, alguien a quien puedo reconocer en cualquier multitud!",
  ui_story_5084_50841201_55_dialog_content = "No podía creer que eras tú cuando te vi desde la distancia.",
  ui_story_5084_50841201_56_dialog_content = "¿Cómo me veo?",
  ui_story_5084_50841201_57_dialog_content = "¡Es Lady Victoria! ¡Y más deslumbrante que antes!",
  ui_story_5084_50841201_58_dialog_content = "Parece que todo está bien contigo, Dama Victoria. Felicidades.",
  ui_story_5084_50841201_59_dialog_content = "Veo que Nails ha sufrido grandes cambios.",
  ui_story_5084_50841201_60_dialog_content = "Ha pasado mucho tiempo, Lady Victoria! Acredito a mi mentor por los resultados...",
  ui_story_5084_50841201_61_dialog_content = "¡Tengo tanto que quiero decirte!",
  ui_story_5084_50841201_62_dialog_content = "Sí, te vi en la calle. Espero escucharlo más tarde.",
  ui_story_5084_50841201_63_dialog_content = "Ya casi es la hora.",
  ui_story_5084_50841201_64_dialog_content = "Pero acabamos de ver a los muertos vivientes hiriendo a la gente, Dama Victoria...",
  ui_story_5084_50841201_65_dialog_content = "Ahora sé de qué trata el reciente rumor en la ciudad sobre el Jinete Negro.",
  ui_story_5084_50841201_66_dialog_content = "Ven, seguidores en la calle. Wilhelm garantizará que estén seguros.",
  ui_story_5084_50841201_67_dialog_content = "True Order debe mostrar su fuerza esta noche. Sígueme a la iglesia.",
  ui_story_5084_50841201_68_dialog_content = "¡Sí!",
  ui_story_5084_50841201_69_dialog_content = "May Que la Verdad bendiga para siempre al True Order.",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>¡Crujir!</color>",
  ui_story_5084_50841201_71_dialog_content = "Ellos están...",
  ui_story_5084_50841201_72_dialog_content = "Todos en el suelo como si...",
  ui_story_5084_50841201_73_dialog_content = "...",
  ui_story_5084_50841201_74_dialog_content = "Han dejado de respirar, Dama Victoria.",
  ui_story_5084_50841201_75_dialog_content = "¡...!",
  ui_story_5084_50841201_76_dialog_content = "Permíteme intentar ayudarlos... Estoy dispuesto a soportar el dolor por ellos.",
  ui_story_5084_50841201_77_dialog_content = "Oye, veo que la jefa de la familia Varaki y sus secuaces finalmente están aquí.",
  ui_story_5084_50841201_78_dialog_content = "Esta es una celebración de True Order, ¿cómo puedo no estar presente?",
  ui_story_5084_50841201_79_dialog_content = "Lady Victoria...",
  ui_story_5084_50841201_80_dialog_content = "...",
  ui_story_5084_50841201_81_dialog_content = "Gram está herido en muchos lugares...",
  ui_story_5084_50841201_82_dialog_content = "Esa es la consecuencia de traicionarme.",
  ui_story_5084_50841201_83_dialog_content = "Lo que hagas está bien... solo no lastimes a Charon y a su esposa...",
  ui_story_5084_50841201_84_dialog_content = "Lastimando a las personas en el Salón de la Verdad...",
  ui_story_5084_50841201_85_dialog_content = "¡Quédate donde estás, Varaki!",
  ui_story_5084_50841201_86_dialog_content = "¡Por qué tú...!",
  ui_story_5084_50841201_87_dialog_content = "Ponte detrás de mí, May.",
  ui_story_5084_50841201_88_dialog_content = "Debes haber olvidado muchas de las reglas para los vampiros. Dejaré que Abraham te explique cuáles violaste...",
  ui_story_5084_50841201_89_dialog_content = "No deberías haber vuelto, Victoria...",
  ui_story_5084_50841201_90_dialog_content = "Ni siquiera tú puedes hacer algo al respecto, ahora que el ritual ha terminado. Todos los \"sacrificios\" al Señor han sido hechos.",
  ui_story_5084_50841201_91_dialog_content = "Ahora, solo estoy enseñando a mis pequeños a no desperdiciar comida.",
  ui_story_5084_50841201_92_dialog_content = "Los Aurorians son un regalo del Señor de la Verdad. ¿Crees que son comida?",
  ui_story_5084_50841201_93_dialog_content = "Oh, dama de los Varaki, ¿no envías a tu gente a conseguir sangre fresca para ti cuando también sientes la sed en lo más profundo de la noche?",
  ui_story_5084_50841201_94_dialog_content = "Yo mismo no desperdicié ni una sola gota del sacrificio que me pertenecía.",
  ui_story_5084_50841201_95_dialog_content = "¡Pero lo mismo no se puede decir de Abraham, que no solo desperdició su parte sino que también me mintió!",
  ui_story_5084_50841201_96_dialog_content = "!",
  ui_story_5084_50841201_97_dialog_content = "Detente, Porfirio... ¡Detente!",
  ui_story_5084_50841201_98_dialog_content = "¿Dónde está Wilhelm?!",
  ui_story_5084_50841201_99_dialog_content = "¡Detente, David Porfirio!",
  ui_story_5084_50841201_100_dialog_content = "Entonces, ¿tomas las decisiones ahora?",
  ui_story_5084_50841201_101_dialog_content = "Tráelo aquí.",
  ui_story_5084_50841201_102_dialog_content = "Yes, Lady Victoria.",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5084_50841201_104_dialog_content = "¿Qué estás haciendo, Vine?",
  ui_story_5084_50841201_105_dialog_content = "Solo estoy siguiendo las órdenes de la Señorita Varaki para entregarte el ataúd del desfile, Lord Porfirio.",
  ui_story_5084_50841201_106_dialog_content = "No me digas que crees que los restos ancestrales de Varaki me asustarían.",
  ui_story_5084_50841201_107_dialog_content = "¿O estás intentando huir con el mismo truco que utilizó Wilhelm Varaki?",
  ui_story_5084_50841201_108_dialog_content = "Es Wilhelm en el ataúd.",
  ui_story_5084_50841201_109_dialog_content = "¿...?",
  ui_story_5084_50841201_110_dialog_content = "¿Ya lo has lastimado sin piedad tal como está y quieres más?",
  ui_story_5084_50841201_111_dialog_content = "Bueno, estoy en mi último hilo de paciencia...",
  ui_story_5084_50841201_112_dialog_content = "Después de terminar con la sangre en esta botella, creo que podría tener que alimentarme de ti.",
  ui_story_5084_50841201_113_dialog_content = "Acércate y dime qué travesuras estás haciendo tú y Wilhelm.",
  ui_story_5084_50841201_114_dialog_content = "Wilhelm está muerto.",
  ui_story_5084_50841201_115_dialog_content = "¡Mentiroso!",
  ui_story_5084_50841201_116_dialog_content = "¡Cuidado, Victoria!",
  ui_story_5084_50841201_117_dialog_content = "¡Sobre mi cadáver!",
  ui_story_5084_50841201_118_dialog_content = "Esto no es nuevo para alguien que intenta construir un grupo alrededor de La Verdad, pero es raro que tú, secuaces, protejas a tu superior de esta manera.",
  ui_story_5084_50841201_119_dialog_content = "No me tomes por tonto, sin embargo. Vi a los dos matar a Viper y Gold Rush.",
  ui_story_5084_50841201_120_dialog_content = "¿Estás asustado? Viper y Gold Rush, así como todos vosotros conspiradores, moriréis por su espada.",
  ui_story_5084_50841201_121_dialog_content = "Entonces, independientemente de cómo intentes atormentar, asesinar o enterrar a Wilhelm Varaki, nunca podrás matarlo.",
  ui_story_5084_50841201_122_dialog_content = "¿Wilhelm... no está muerto? ¿Está vivo...?",
  ui_story_5084_50841201_123_dialog_content = "...",
  ui_story_5084_50841201_124_dialog_content = "No muerto... ¿entonces Varaki podría convertirse en un espíritu después de morir?",
  ui_story_5084_50841201_125_dialog_content = "¡No hay espíritus en el mundo! Los revenants solo se convirtieron en lo que eran después de absorber el poder de Porfirio.",
  ui_story_5084_50841201_126_dialog_content = "¡Este es mi poder sobre los revenants... Único en la historia de las casas de vampiros!",
  ui_story_5084_50841201_127_dialog_content = "No bromees al respecto, no es una resurrección. De ninguna manera.",
  ui_story_5084_50841201_128_dialog_content = "¿Pensaste que el poder que poseían los Varakis era solo un regalo ancestral utilizado para ver el futuro?",
  ui_story_5084_50841201_129_dialog_content = "¿...?",
  ui_story_5084_50841201_130_dialog_content = "Hace un momento, hice un pacto con Bloody Bible para su aprobación como líder de la True Order.",
  ui_story_5084_50841201_131_dialog_content = "Los discípulos se inclinan y regresan a La Verdad con alabanzas piadosas...",
  ui_story_5084_50841201_132_dialog_content = "Debería saber a estas alturas que la selección de Varaki es solo el medio de los Varakis para mantenerse en el poder.",
  ui_story_5084_50841201_133_dialog_content = "Yo, Porfirio, debería haber tenido el honor hace mucho tiempo y asumir el deber de devolver la Orden a los seguidores.",
  ui_story_5084_50841201_134_dialog_content = "Los vampiros son los gobernantes de la sangre y la noche. ¿Por qué debería servir a las criaturas de la luz?",
  ui_story_5084_50841201_135_dialog_content = "El título debería ser mío, y dominaré al pueblo de acuerdo con lo que querían los antepasados. ¡Eso es lo que la Biblia Sangrienta me reveló!",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>La feroz y despiadada lucha llevó a un ataúd volcado para que todos los presentes fueran testigos...</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>Una nueva Biblia Sangrienta aterrizando a los pies de Victoria... como estaba destinado.</color>",
  ui_story_5084_50841301_3_dialog_content = "La Verdad quisiera terminar de pavimentar el camino hacia la redención, y aparentemente me prefiere a mí como su intermediario.",
  ui_story_5084_50841301_4_dialog_content = "¡Manifiesto del Códice de Calamidades!",
  ui_story_5084_50841301_5_dialog_content = "...",
  ui_story_5084_50841301_6_dialog_content = "¿Qué se supone que es eso?",
  ui_story_5084_50841301_7_dialog_content = "El profético Codex te ofreció vislumbres del futuro, pero no supiste aprovecharlo mientras te tambaleabas como un bebé aprendiendo a caminar.",
  ui_story_5084_50841301_8_dialog_content = "Este Códice, bautizado en el Río Prístino, lo sabe todo... Es omnisciente.",
  ui_story_5084_50841301_9_dialog_content = "¡El nuevo capítulo ha sido revelado, y yo pasaré la página!",
  ui_story_5084_50841301_10_dialog_content = "¿Te gustaría presenciar sus revelaciones de cuándo naciste, cuándo morirás y cuándo te arrepentirás?",
  ui_story_5084_50841301_11_dialog_content = "¡...!",
  ui_story_5084_50841301_12_dialog_content = "El resto de ustedes, líderes del clan que se relacionan con Porfirio, escuchen.",
  ui_story_5084_50841301_13_dialog_content = "El maestro de la tercera de las doce Grandes Casas, Porifiro..",
  ui_story_5084_50841301_14_dialog_content = "Ha caído presa de la sed de sangre bajo la luna de sangre, asesinó a numerosos discípulos, ingirió su sangre y controló a los muertos a través de una reliquia familiar, la Pipa Dorada.",
  ui_story_5084_50841301_15_dialog_content = "Se confabuló con el jefe de la decimotercera Gran Casa abolida de la Orden para liberar una entidad maligna en la Ciudad de Varaki y masacrar a los seguidores.",
  ui_story_5084_50841301_16_dialog_content = "¿Ese niño abandonado...?",
  ui_story_5084_50841301_17_dialog_content = "El jefe de la decimotercera casa buscó donde descendió el Señor de la Verdad en la Zona Oscura...",
  ui_story_5084_50841301_18_dialog_content = "Luego llevó a un falso dios a la ciudad, atacó a los discípulos y saboteó la ceremonia del Señor.",
  ui_story_5084_50841301_19_dialog_content = "David Porfirio creó y aprovechó la oportunidad para drenar sangre de los seguidores heridos.",
  ui_story_5084_50841301_20_dialog_content = "¿Es esa la perspectiva que quieres que lidere a todos ustedes y a la Orden?",
  ui_story_5084_50841301_21_dialog_content = "...",
  ui_story_5084_50841301_22_dialog_content = "¡Basta ya de todas estas tonterías!",
  ui_story_5084_50841301_23_dialog_content = "Por el poder del <color=#FFB400>Anillo de Varaki</color>, ¡muestra tu <color=#FFB400>verdadera naturaleza</color>!",
  ui_story_5084_50841301_24_dialog_content = "—!",
  ui_story_5084_50841301_25_dialog_content = "Pensé que aliándome con la decimotercera casa y bebiendo la sangre de los apóstoles aumentaría mi poder...",
  ui_story_5084_50841301_26_dialog_content = "El resto de los gobernantes recibió la bendición del Señor y cambió a otra alternativa.",
  ui_story_5084_50841301_27_dialog_content = "Excepto yo... Mi sed de sangre solo creció. Ahora debo confiar en este frasco de sangre levitante solo para mantenerme apenas.",
  ui_story_5084_50841301_28_dialog_content = "Aparentemente, no te das cuenta de que el jefe de la decimotercera casa nunca sintió que nada de esto estuviera en el pacto entre tú.",
  ui_story_5084_50841301_29_dialog_content = "Sacrificarte no es diferente a sacrificar a todas las criaturas para ella. Solo te estaba usando.",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>Ella</color> se unió a Eclipse y se convirtió en una de los <color=#FFB400>Espectros</color>. ¿Pensaste que podrías engañarla?",
  ui_story_5084_50841301_31_dialog_content = "¡Cállate!",
  ui_story_5084_50841301_32_dialog_content = "Tú, Victoria Varaki... ¿Cómo es posible que puedas controlarme con el anillo?",
  ui_story_5084_50841301_33_dialog_content = "No, esto no puede ser... Esto no es cómo el Anillo de Varaki actuó antes.",
  ui_story_5084_50841301_34_dialog_content = "Lo he dominado y lo he alineado con todos los antepasados de Varaki.",
  ui_story_5084_50841301_35_dialog_content = "Lo que estás enfrentando es el poder combinado del Clan Varaki. ¡Confiesa tus pecados ahora!",
  ui_story_5084_50841301_36_dialog_content = "Je, yo...",
  ui_story_5084_50841301_37_dialog_content = "¡Maté a Wilhelm!",
  ui_story_5084_50841301_38_dialog_content = "¡Pero lo hice para liberar a la True Order del verdadero obstáculo!",
  ui_story_5084_50841301_39_dialog_content = "¿Cómo podría un segundo hijo retorcido de Varaki, que vivía en reclusión y dañó a su hermano, liderar la Orden?",
  ui_story_5084_50841301_40_dialog_content = "¡Wilhelm no le hizo daño a nadie!",
  ui_story_5084_50841301_41_dialog_content = "¡No es tu lugar para hablar!",
  ui_story_5084_50841301_42_dialog_content = "—!",
  ui_story_5084_50841301_43_dialog_content = "La Biblia Sangrienta es una reliquia Varaki. Otorga poder al portador y me libera del miedo.",
  ui_story_5084_50841301_44_dialog_content = "Incluso cuando maté para saciar mi lujuria por la sangre, aún aprobó y me dio poder.",
  ui_story_5084_50841301_45_dialog_content = "¡Nadie en True Order podría esperar desafiarme!",
  ui_story_5084_50841301_46_dialog_content = "¡Biblia sangrienta, por favor concédeme el poder para erradicar a Varakis!",
  ui_story_5084_50841301_47_dialog_content = "...",
  ui_story_5084_50841301_48_dialog_content = "¡Biblia sangrienta...!",
  ui_story_5084_50841301_49_dialog_content = "Nunca entendiste la razón por la que los Varakis se convirtieron en líderes de la Orden.",
  ui_story_5084_50841301_50_dialog_content = "Nunca haríamos daño a nadie con la Biblia Sangrienta.",
  ui_story_5084_50841301_51_dialog_content = "Todo lo contrario, fue la Biblia la que extrajo la sangre de Varaki a cambio de revelar el futuro.",
  ui_story_5084_50841301_52_dialog_content = "¿...?",
  ui_story_5084_50841301_53_dialog_content = "Es lo mismo si se trata de los antepasados, mis padres, Wilhelm e incluso yo.",
  ui_story_5084_50841301_54_dialog_content = "Estas reliquias conservaron la voluntad de cada jefe de la casa, ya sea racional o de otro tipo.",
  ui_story_5084_50841301_55_dialog_content = "Aquellos que hacen un pacto deben tener la resolución de resistir los susurros tentadores para alcanzar la Verdad...",
  ui_story_5084_50841301_56_dialog_content = "¡Y interpreta las revelaciones del Señor de la Verdad en un nivel superior!",
  ui_story_5084_50841301_57_dialog_content = "¿Qué revelaciones has vislumbrado?",
  ui_story_5084_50841301_58_dialog_content = "...",
  ui_story_5084_50841301_59_dialog_content = "¿Qué vas a hacer...?!",
  ui_story_5084_50841301_60_dialog_content = "¿Te olvidaste de la reunión?",
  ui_story_5084_50841301_61_dialog_content = "What revelation did you receive?",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>To purge the order.</color>",
  ui_story_5084_50841301_63_dialog_content = "¡Por qué tú...!",
  ui_story_5084_50841301_64_dialog_content = "¡Discípulos de la Verdad, reciten el mantra conmigo!",
  ui_story_5084_50841301_65_dialog_content = "¡Yo, Nails, recitaré el mantra con mi vida!",
  ui_story_5084_50841301_66_dialog_content = "Yo, May, recitaré el mantra con el Sr. Beau!",
  ui_story_5084_50841301_67_dialog_content = "El discípulo Faust debe recitar el mantra con Lady Victoria!",
  ui_story_5084_50841301_68_dialog_content = "Cede, David.",
  ui_story_5084_50841301_69_dialog_content = "¡Cobarde! ¡El jefe de la Casa Porfirio debe liderar el True Order!",
  ui_story_5084_50841301_70_dialog_content = "Adiós.",
  ui_story_5084_50841301_71_dialog_content = "¡Todos ustedes me lo prometieron!",
  ui_story_5084_50841301_72_dialog_content = "Basta. Nuestro trato expira en luna de sangre. ¡Veo que hice la apuesta correcta! Diviértete bebiendo sangre.",
  ui_story_5084_50841301_73_dialog_content = "¡Mi no muerto!",
  ui_story_5084_50841301_74_dialog_content = "Gobernantes de todas las casas en la Orden, están invitados a presenciar—",
  ui_story_5084_50841301_75_dialog_content = "...",
  ui_story_5084_50841301_76_dialog_content = "El Espíritu de la Verdad fluye a través de todos los discípulos. ¡Por favor, levántense!",
  ui_story_5084_50841301_77_dialog_content = "¡Escucha la Verdad conmigo!",
  ui_story_5084_50841301_78_dialog_content = "El flujo ondulante que bailó conmigo rompió el vacío y emergió aquí.",
  ui_story_5084_50841301_79_dialog_content = "Soy la Runa sostenida por el Señor de la Verdad, esperando su llegada en tierra sagrada.",
  ui_story_5084_50841301_80_dialog_content = "Soy el Heraldo de la Luz, Conductor de la Oscuridad! May La muerte se manifiesta en el Reino de la Inmortalidad.",
  ui_story_5084_50841301_81_dialog_content = "¡Todopoderoso Señor de la Verdad, por favor otorga poderes divinos a través de las revelaciones de la sangre de Varaki en mí!",
  ui_story_5084_50841301_82_dialog_content = "La Sangre Sagrada tomará forma... ¡Escucharé todas las confesiones!",
  ui_story_5084_50841301_83_dialog_content = "La vid ha sido revivida. May ¡el Señor viene a mí!",
  ui_story_5084_50841301_84_dialog_content = "¡Ven a mí en esta verdadera pesadilla! ¡Desataré poderes antiguos!",
  ui_story_5084_50841301_85_dialog_content = "¡Préstanos tu poder, Navegador de la Verdad Universal que sirve como puente al Río Prístino!",
  ui_story_5084_50841301_86_dialog_content = "¿A qué te refieres con Verdad Universal y puente al Río Prístino?",
  ui_story_5084_50841301_87_dialog_content = "¡Por supuesto, ayudaré!",
  ui_story_5084_50841301_88_dialog_content = "Él verá tu contribución. El pacto se ha completado. ¡Espera la llegada de Dios conmigo!",
  ui_story_5084_50841302_1_dialog_content = "Viniste del mismo sediento de sangre, sucio, maldito desde el nacimiento que yo...",
  ui_story_5084_50841302_2_dialog_content = "¿Qué te hizo Varakis, merecedor de monopolizar el puesto?",
  ui_story_5084_50841302_3_dialog_content = "La respuesta debería ser clara para ti cuando hagas la pregunta.",
  ui_story_5084_50841302_4_dialog_content = "Varaki...",
  ui_story_5084_50841302_5_dialog_content = "La sed de sangre, inmortalidad, maldición... Los vampiros deben pagar un cierto precio por el poder.",
  ui_story_5084_50841302_6_dialog_content = "Esa noción ha estado conmigo y me ha formado desde que nací.",
  ui_story_5084_50841302_7_dialog_content = "Pero recientemente, he llegado a la conclusión iluminada de que todo lo que experimenté no es el costo, sino lo que me hace merecedor del regalo y la guía que recibo.",
  ui_story_5084_50841302_8_dialog_content = "El Señor de la Verdad nos eligió y nos otorgó el poder para liderar cambios y nuevas eras.",
  ui_story_5084_50841302_9_dialog_content = "Cualquiera de los Eclipsites, armas de una antigua civilización, o falsos dioses podrían representar amenazas para la supervivencia de los Aurorianos.",
  ui_story_5084_50841302_10_dialog_content = "Por no hablar de los Aurorianos malvados y heréticos como tú.",
  ui_story_5084_50841302_11_dialog_content = "Sin salir de la ciudad de Varaki para observar los ríos o las estrellas...",
  ui_story_5084_50841302_12_dialog_content = "Sin ver cómo este bendito planeta de Eoria opera bajo la vigilancia del Señor...",
  ui_story_5084_50841302_13_dialog_content = "Nunca entenderás cómo cayó la estrella solitaria, porque ha sucedido demasiadas veces.",
  ui_story_5084_50841302_14_dialog_content = "Cuando los Aurorianos enfrenten la extinción nuevamente, solo el Varaki elegido por el Señor puede prevenir la destrucción de Eoria.",
  ui_story_5084_50841302_15_dialog_content = "La capacidad de revertir el miedo a lo desconocido a través de una mayor compostura es la base para los Elegidos.",
  ui_story_5084_50841302_16_dialog_content = "David Porfirio, como un vampiro que recibió el honor pero no logró comprender La Verdad, debes devolver el poder que el Señor te ha otorgado.",
  ui_story_5084_50841302_17_dialog_content = "No tiene nada que ver con la comprensión o la elección del Señor. Los Varakis son los únicos que los vampiros reconocen.",
  ui_story_5084_50841302_18_dialog_content = "Porfirios comenzó como los descendientes de Varakis...",
  ui_story_5084_50841302_19_dialog_content = "Pero mis antepasados perdieron sus lugares debido a las opresiones de Varaki, lo que me impidió obtener la aprobación...",
  ui_story_5084_50841302_20_dialog_content = "Varios siglos después, sigue siendo igual. No tienes derecho a hablar sobre la iluminación.",
  ui_story_5084_50841302_21_dialog_content = "Tú—y los Varakis—nunca escaparán del destino de los vampiros.",
  ui_story_5084_50841302_22_dialog_content = "Jaja... Jajaja...",
  ui_story_5084_50841302_23_dialog_content = "...",
  ui_story_5084_50841302_24_dialog_content = "Srta. Varaki... quiero decir, Lady Victoria...",
  ui_story_5084_50841302_25_dialog_content = "¿Realmente recibiste revelaciones del Señor en tus viajes al extranjero?",
  ui_story_5084_50841302_26_dialog_content = "Siempre tenemos muchas reliquias antiguas en nuestra posesión.",
  ui_story_5084_50841302_27_dialog_content = "¿Cómo podemos juzgar lo que provino de los susurros y si somos aptos para el poder otorgado por el Señor de la Verdad?",
  ui_story_5084_50841302_28_dialog_content = "La Orden siempre ha sido conocida por los espíritus superiores de los vampiros, por lo tanto, la capacidad de resonar con las reliquias es un regalo.",
  ui_story_5084_50841302_29_dialog_content = "Pero con los años, las luchas de poder entre los jefes de las casas y la complacencia han confundido el mensaje en las reliquias transmitidas a través de las generaciones.",
  ui_story_5084_50841302_30_dialog_content = "Para muchas de las reliquias, no fue hasta que establecí la sintonización que me di cuenta de que no contenían nada más que dolor enloquecedor y gritos.",
  ui_story_5084_50841302_31_dialog_content = "El miedo es la base para el equilibrio entre los Aurorianos y los objetos.",
  ui_story_5084_50841302_32_dialog_content = "Todos los sucesores de Varaki caminaban todas las noches por ese miedo, causando que su cuerpo y mente se deterioraran bajo la carga...",
  ui_story_5084_50841302_33_dialog_content = "Es por eso que estudié minuciosamente tomos y pergaminos en busca de la sabiduría y el conocimiento Aurorianos para controlar nuestros instintos innatos.",
  ui_story_5084_50841302_34_dialog_content = "A través de lo cual, pude navegar las voces y al abrazo del Señor.",
  ui_story_5084_50841302_35_dialog_content = "Continuar haciendo preguntas y explorar, luego reprimir la debilidad hasta que nos teman y se sometan en cambio es, para mí, el camino.",
  ui_story_5084_50841302_36_dialog_content = "Estamos agradecidos por la perspicacia, Lady Victoria.",
  ui_story_5084_50841302_37_dialog_content = "Pero debo decir que no se aplica exclusivamente a los vampiros.",
  ui_story_5084_50841302_38_dialog_content = "En mi viaje, he encontrado Aurorianos no vampíricos con habilidades desconocidas para atraer objetos especiales.",
  ui_story_5084_50841302_39_dialog_content = "Podría ser simplemente una rueda, un radio...",
  ui_story_5084_50841302_40_dialog_content = "Una vid, un pedazo de papel...",
  ui_story_5084_50841302_41_dialog_content = "Una mascota, un maletín blanco...",
  ui_story_5084_50841302_42_dialog_content = "Dependiendo del propietario, se desbloquearon diferentes potenciales asombrosos.",
  ui_story_5084_50841302_43_dialog_content = "Creo que no has visto sangre maleable que pueda matar a los Eclipsites.",
  ui_story_5084_50841302_44_dialog_content = "Mis seguidores afirman haber conocido a un discípulo capaz de eso en las calles antes.",
  ui_story_5084_50841302_45_dialog_content = "...",
  ui_story_5084_50841302_46_dialog_content = "Discípulos como esos impregnan el mundo. La Orden debería integrarse en las sociedades Aurorianas y propagar La Verdad, trayendo tal poder a nuestro redil.",
  ui_story_5084_50841302_47_dialog_content = "Otros que también recibieron revelaciones existen pero están dispersos por todo el mundo, sin darse cuenta de lo que significan.",
  ui_story_5084_50841302_48_dialog_content = "Nosotros, como vampiros, debemos compilar las revelaciones para hacer saber al Señor de la Verdad que es hora de su llegada y guiar a los Aurorians hacia el futuro.",
  ui_story_5084_50841302_49_dialog_content = "Si ese es el caso, apruebo salir de la ciudad y difundir La Verdad entre los Aurorianos.",
  ui_story_5084_50841302_50_dialog_content = "Construye seguidores y acumula influencia...",
  ui_story_5084_50841302_51_dialog_content = "¿Pero cómo podemos hacer llegar el mensaje al Señor?",
  ui_story_5084_50841302_52_dialog_content = "Si te dijera que hay un Navegante capaz de llegar al Río Prístino a través de reliquias e incluso comandar esas mismas reliquias...",
  ui_story_5084_50841302_53_dialog_content = "¿No esperarías con ansias también el futuro de The Order?",
  ui_story_5084_50841302_54_dialog_content = "¿Qué Navegante?",
  ui_story_5084_50841302_55_dialog_content = "¡Oye, nunca dije que me uniría a la Orden Verdadera!",
  ui_story_5084_50841302_56_dialog_content = "Pásame el candelabro, Caelestite.",
  ui_story_5084_50841302_57_dialog_content = "¿Eh? Pero hay tanta gente aquí...",
  ui_story_5084_50841302_58_dialog_content = "Entrégamelo.",
  ui_story_5084_50841302_59_dialog_content = "...",
  ui_story_5084_50841302_60_dialog_content = "Esto es... un Caelestite, un aliado de La Orden.",
  ui_story_5084_50841302_61_dialog_content = "Uh, hola a todos.",
  ui_story_5084_50841302_62_dialog_content = "He oído hablar de los Caelestites. Podían pilotar Colosos y eran telepáticos.",
  ui_story_5084_50841302_63_dialog_content = "¿Has estado aquí todo el tiempo, Caelestite?",
  ui_story_5084_50841302_64_dialog_content = "Bueno, para ser preciso, estoy presente mucho tiempo, pero no me muestro por varias razones.",
  ui_story_5084_50841302_65_dialog_content = "Telepático... ¿No es eso idéntico a la habilidad del vampiro para resonar?",
  ui_story_5084_50841302_66_dialog_content = "No, no es lo mismo.",
  ui_story_5084_50841302_67_dialog_content = "Como mencioné, los vampiros se comunican con las reliquias a través del linaje.",
  ui_story_5084_50841302_68_dialog_content = "La telepatía de Caelestite comparte en realidad el poder poseído por los vampiros de un nivel superior, y ese mismo poder es también la base para todos los Aurorians.",
  ui_story_5084_50841302_69_dialog_content = "¿El Río Prístino?",
  ui_story_5084_50841302_70_dialog_content = "¡Oh, cielos! ¿Has rastreado el Pergamino Antiguo, Lady Victoria?",
  ui_story_5084_50841302_71_dialog_content = "No. Nadie tiene el pergamino ni sabe dónde está.",
  ui_story_5084_50841302_72_dialog_content = "Pero al parecer ya han visitado el Río Prístino detrás de los Pergaminos Antiguos.",
  ui_story_5084_50841302_73_dialog_content = "Buscaré esa ubicación, por lo tanto, me gustaría confiarles la ciudad a todos ustedes.",
  ui_story_5084_50841302_74_dialog_content = "Seguiremos tus palabras y el estándar que has establecido.",
  ui_story_5084_50841302_75_dialog_content = "¿De verdad? ¿Alguien visitó el Río Prístino?",
  ui_story_5084_50841302_76_dialog_content = "Cleves Abraham, ¿estás pensando si decirme la verdad sobre el asesinato de Wilhelm?",
  ui_story_5084_50841302_77_dialog_content = "...",
  ui_story_5084_50841302_78_dialog_content = "Estoy aquí para pedirte prestado un objeto, Cleves.",
  ui_story_5084_50841302_79_dialog_content = "¿Faria la caja negra?",
  ui_story_5084_50841302_80_dialog_content = "Sí.",
  ui_story_5084_50841302_81_dialog_content = "¿Estás tomando la Biblia sangrienta?!",
  ui_story_5084_50841302_82_dialog_content = "Solo es cuestión de tiempo antes de que el vampiro lo arrebate de la tumba.",
  ui_story_5084_50841302_83_dialog_content = "Él no tiene derecho a llevárselo.",
  ui_story_5084_50841302_84_dialog_content = "Eso se debe a que la sucesión de líderes de Varaki dejó una marca en la mente de los gobernantes de la casa.",
  ui_story_5084_50841302_85_dialog_content = "Pero incluso ahora, Victoria no ha reconocido el poder significativo que corre por sus venas.",
  ui_story_5084_50841302_86_dialog_content = "Añade el hecho de que mi historia ha manchado la santidad de los Varakis, los gobernantes han estado observando mi posición desde hace mucho tiempo.",
  ui_story_5084_50841302_87_dialog_content = "Si ya no estuviera, seguramente irán tras Victoria.",
  ui_story_5084_50841302_88_dialog_content = "Y una Orden Verdadera liderada por Porfirio seguramente traerá desastre al mundo.",
  ui_story_5084_50841302_89_dialog_content = "Sobre esto, Wilhelm...",
  ui_story_5084_50841302_90_dialog_content = "Solo cuando la luz de una luna de sangre se proyecte sobre la hiedra en la noche del Advenimiento de la Verdad, la tumba estará abierta para los gobernantes de la casa.",
  ui_story_5084_50841302_91_dialog_content = "Pero será demasiado tarde para entonces. Hemos discutido las posibilidades con respecto a Faria la caja negra.",
  ui_story_5084_50841302_92_dialog_content = "Quizás mi hermano confió el libro a ti, su amigo cercano, con la intención de dejarme tomarlo cuando el momento fuera el correcto.",
  ui_story_5084_50841302_93_dialog_content = "...",
  ui_story_5084_50841302_94_dialog_content = "¿Por qué la pausa embarazosa, Cleves?",
  ui_story_5084_50841302_95_dialog_content = "Wilhelm, suponiendo que la caja puede abrir la tumba, está prohibido por el pacto común tomar el libro sin la presencia de todos los gobernantes.",
  ui_story_5084_50841302_96_dialog_content = "Lo se.",
  ui_story_5084_50841302_97_dialog_content = "Y aun así expresaste completamente la decisión de romper el pacto conmigo... ¿Qué estás pensando, Wilhelm?",
  ui_story_5084_50841302_98_dialog_content = "¿Cuántos años tiene Victoria ahora?",
  ui_story_5084_50841302_99_dialog_content = "¿Por qué preguntas?",
  ui_story_5084_50841302_100_dialog_content = "Has estado cuidando de ella durante muchos años. Ese tú más joven, ambicioso y egoísta...",
  ui_story_5084_50841302_101_dialog_content = "Se ha convertido en un anciano vigilante de los demás.",
  ui_story_5084_50841302_102_dialog_content = "Si solo supieras lo bien que Victoria y yo normalmente nos llevamos, probablemente no dirías eso.",
  ui_story_5084_50841302_103_dialog_content = "Lo que quiero decir es, ¿sabes por qué me mudé a la Ciudad Vieja?",
  ui_story_5084_50841302_104_dialog_content = "Para Charon, sin duda alguna.",
  ui_story_5084_50841302_105_dialog_content = "Sí, Wilhelm. La madre de Charon y yo ya no queremos preocuparnos por la Orden, mucho menos dejar que Charon se una a ella.",
  ui_story_5084_50841302_106_dialog_content = "Te echaste para atrás.",
  ui_story_5084_50841302_107_dialog_content = "No, Wilhelm, di un paso difícil adelante por el bien de Charon.",
  ui_story_5084_50841302_108_dialog_content = "¿Y si te dijera que debes darme la caja para que Charon y su mamá se mantengan alejados de los problemas?",
  ui_story_5084_50841302_109_dialog_content = "...",
  ui_story_5084_50841302_110_dialog_content = "La Orden solo puede beneficiarse cuando la Biblia está en manos de Varaki. ¡En todos mis recuerdos heredados, ese es el único medio para lograr la reforma!",
  ui_story_5084_50841302_111_dialog_content = "Parece que has vuelto a tus formas ambiciosas.",
  ui_story_5084_50841302_112_dialog_content = "¿No te han castigado suficiente las voces enloquecedoras que intentan corromperte?",
  ui_story_5084_50841302_113_dialog_content = "¡Así es, tengo ambiciones! ¿¡Pero qué importa?!",
  ui_story_5084_50841302_114_dialog_content = "¿Debería seguir lamentándome en la autocompasión de ser eclipsado por un hermano talentoso y poderoso? ¡No! ¡Nunca!",
  ui_story_5084_50841302_115_dialog_content = "...",
  ui_story_5084_50841302_116_dialog_content = "Lo siento, Cleves. No quise decir eso.",
  ui_story_5084_50841302_117_dialog_content = "Lo que quise decir es que no lo estoy haciendo por mí esta vez. Es por Victoria.",
  ui_story_5084_50841302_118_dialog_content = "I cannot agree with that, Wilhelm...",
  ui_story_5084_50841302_119_dialog_content = "¿De qué tienes miedo exactamente? ¿No ves que las cosas están empeorando?",
  ui_story_5084_50841302_120_dialog_content = "Porfirio and the house rulers have stopped following the rules after branching off the Varaki bloodline.",
  ui_story_5084_50841302_121_dialog_content = "¿Qué tan bueno es para ti seguir las reglas solo?",
  ui_story_5084_50841302_122_dialog_content = "Las reglas para los vampiros siempre han sido una grillete. Es un impedimento para The True Order ahora, para ti, para mí, para todos en el pueblo.",
  ui_story_5084_50841302_123_dialog_content = "Esa es la naturaleza de los vampiros, excepto que tú eres más afortunado que nosotros.",
  ui_story_5084_50841302_124_dialog_content = "¿Cuándo decidiste inclinarte también ante el destino?",
  ui_story_5084_50841302_125_dialog_content = "Do not fault me for this, Wilhelm. I simply cannot deny what I know to be true...",
  ui_story_5084_50841302_126_dialog_content = "Esa llave solo te traerá daño.",
  ui_story_5084_50841302_127_dialog_content = "Pero tú tampoco planeas ayudar, ¿verdad?",
  ui_story_5084_50841302_128_dialog_content = "...",
  ui_story_5084_50841302_129_dialog_content = "Está bien, Cleves. Pensaré en algo.",
  ui_story_5084_50841302_130_dialog_content = "No le di la Caja Negra a Wilhelm, y tampoco tenía la intención de matarlo en ese momento.",
  ui_story_5084_50841302_131_dialog_content = "Pensé que podría simplemente observar a los gobernantes... matarlo en la víspera del Advenimiento de la Verdad.",
  ui_story_5084_50841302_132_dialog_content = "...",
  ui_story_5084_50841302_133_dialog_content = "<size=45>¡Aahhhh!</size>",
  ui_story_5084_50841302_134_dialog_content = "Jaja, jajaja...",
  ui_story_5084_50841302_135_dialog_content = "Cleves...",
  ui_story_5084_50841302_136_dialog_content = "Lo siento, Wilhelm...",
  ui_story_5084_50841302_137_dialog_content = "Debo ofrecer a Charon una hoja en blanco.",
  ui_story_5084_50841302_138_dialog_content = "Sé que entenderás al cuidar de Victoria.",
  ui_story_5084_50841302_139_dialog_content = "Victoria...",
  ui_story_5084_50841302_140_dialog_content = "Je...",
  ui_story_5084_50841302_141_dialog_content = "Lo siento...!",
  ui_story_5084_50841302_142_dialog_content = "Pensé que nunca vendrías, Cleves.",
  ui_story_5084_50841302_143_dialog_content = "¿Pensaste que esconderla con tus trucos cambiaría algo, Wilhelm?",
  ui_story_5084_50841302_144_dialog_content = "Doomed to a disgraceful death in your very own hometown... How I pity you, Wilhelm Varaki.",
  ui_story_5084_50841302_145_dialog_content = "...",
  ui_story_5084_50841302_146_dialog_content = "Bueno, es irrelevante que el Anillo de Varaki se transmita ahora.",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>David Porfirio empujó el contenedor ensangrentado detrás de él y aplicó la mayor fuerza que jamás había ejercido entre sus dedos.</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>Aplastó el Anillo de Varaki mientras el polvo plateado y rojo salpicaba a Wilhelm.</color>",
  ui_story_5084_50841302_149_dialog_content = "What have you done? By crushing the ring, you've...",
  ui_story_5084_50841302_150_dialog_content = "It's useless to you or me now. Let the debris rest with Wilhelm in peace.",
  ui_story_5084_50841302_151_dialog_content = "From this day forth, it cannot be used to threaten us ever again.",
  ui_story_5084_50841302_152_dialog_content = "¡El grillete que es el Gran Gobernante Varaki está en el pasado!",
  ui_story_5084_50841302_153_dialog_content = "¡Debo decir, seguro que preparaste un festín delicioso para la Venida de la Verdad, David!",
  ui_story_5084_50841302_154_dialog_content = "¡Pero Wilhelm está muerto...!",
  ui_story_5084_50841302_155_dialog_content = "Sí, con tu ayuda. Aún debemos seguir la jerarquía al probar la sangre de Varaki.",
  ui_story_5084_50841302_156_dialog_content = "Después de mí, por supuesto, es mi amigo más cercano—Cleves.",
  ui_story_5084_50841302_157_dialog_content = "Una vez que mis chicos estén alimentados, Wilhelm es todo tuyo.",
  ui_story_5084_50841302_158_dialog_content = "Dado que ustedes dos son viejos amigos, puedes darle un entierro.",
  ui_story_5084_50841302_159_dialog_content = "Quiero decir, descansar eternamente en un ataúd es una de nuestras tradiciones, después de todo.",
  ui_story_5084_50841302_160_dialog_content = "Pero no olvides suplicarle perdón. Quizás aún pueda escuchar las palabras de un amigo que lo apuñaló por la espalda.",
  ui_story_5084_50841302_161_dialog_content = "Entonces, ¿dejarás de dificultarle las cosas a Charon y a mi esposa ahora?",
  ui_story_5084_50841302_162_dialog_content = "Por supuesto. Pero Cleves, hay algo que no entiendo del todo... ¿Es cierto que mis chicos te vieron planeando mudarte?",
  ui_story_5084_50841302_163_dialog_content = "...",
  ui_story_5084_50841302_164_dialog_content = "Eso dificultaría que te pidiera más favores, ¿verdad?",
  ui_story_5084_50841302_165_dialog_content = "¡Por qué tú...!",
  ui_story_5084_50841302_166_dialog_content = "¡Jajaja!",
  ui_story_5084_50841302_167_dialog_content = "Tonto.",
  ui_story_5084_50841302_168_dialog_content = "Tienes oídos en el suelo, Fiebre del Oro. No olvides rastrear Victoria para mí.",
  ui_story_5084_50841302_169_dialog_content = "¿Qué he hecho... ¡¿Qué he hecho?!",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>Cleves llevó al difunto Wilhelm a la Tumba Varaki.</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>Sin embargo, el guardián rechazó su solicitud de enterrar a Wilhelm dentro.</color>",
  ui_story_5084_50841302_172_dialog_content = "La llave universal—<color=#FFB400>Faria la caja negra</color>!",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>La reliquia apareció y desgarró una grieta. A través de la fisura en El Flujo, Cleves entró en la cripta.</color>",
  ui_story_5084_50841302_174_dialog_content = "Esta es la Tumba de Varaki, Wilhelm. Aunque no hay otro lugar más seguro para ti, debo irme lo más pronto posible.",
  ui_story_5084_50841302_175_dialog_content = "Espero que descanses en paz y regreses al Señor de la Verdad como lo hicieron tus antepasados.",
  ui_story_5084_50841302_176_dialog_content = "La llave solo me traerá problemas.",
  ui_story_5084_50841302_177_dialog_content = "Es inevitable que Porfirio descubra si debería guardarlo.",
  ui_story_5084_50841302_178_dialog_content = "Si los antepasados vieran el evento, que la agonía de la traición sea mi castigo.",
  ui_story_5084_50841302_179_dialog_content = "El True Order... Varaki... Lo intentamos, pero no pudimos controlar su destino.",
  ui_story_5084_50841302_180_dialog_content = "Wilhelm... Vampiros... ¿Hemos permanecido todos como prisioneros del destino al final, de todos modos?",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>Mientras el guardián de la tumba observaba en silencio, Cleves colocó la Caja Negra dentro del ataúd con Wilhelm.</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>Ninguno era consciente de que la llave universal abrió arbitrariamente una puerta llamada \"Destino\".</color>",
  ui_story_5084_50841302_183_dialog_content = "No intentaré defenderme. Me merezco todo esto.",
  ui_story_5084_50841302_184_dialog_content = "Por la traición, debes arrepentirte ante el Señor de la Verdad inmediatamente, Sr. Cleves.",
  ui_story_5084_50841302_185_dialog_content = "No pediré el perdón del Señor, porque ni siquiera puedo enfrentar a Wilhelm.",
  ui_story_5084_50841302_186_dialog_content = "...",
  ui_story_5084_50841302_187_dialog_content = "Nadie sabe sobre ese lugar aparte de tú y yo. Y Wilhelm está muerto.",
  ui_story_5084_50841302_188_dialog_content = "El día que decidí dejar la ciudad de Varaki, no estabas buscando a Wilhelm. Me estabas buscando a mí.",
  ui_story_5084_50841302_189_dialog_content = "Si te quedaras, te confesaría todo. Pero si te fueras...",
  ui_story_5084_50841302_190_dialog_content = "No habrías dicho una palabra.",
  ui_story_5084_50841302_191_dialog_content = "Francamente, no pasó un día sin que sintiera el tormento...",
  ui_story_5084_50841302_192_dialog_content = "Puedes quitarme la vida cuando quieras. Todo lo que pido es que me dejes hacer una última cosa.",
  ui_story_5084_50841302_193_dialog_content = "...",
  ui_story_5084_50841302_194_dialog_content = "¿Se encuentra bien, señor Cleve?",
  ui_story_5084_50841302_195_dialog_content = "Charon y mi esposa no tienen nada que ver con todo esto. Debo darles un borrón y cuenta nueva.",
  ui_story_5084_50841302_196_dialog_content = "Pero incluso si sigo vivo, Charon probablemente todavía me odiará seguro...",
  ui_story_5084_50841302_197_dialog_content = "¿Qué puedo hacer? Tal vez esto sea otro castigo para mí.",
  ui_story_5084_50841302_198_dialog_content = "Recuerdo a Charon hablándome sobre su papá. De hecho, tienen una relación complicada.",
  ui_story_5084_50841302_199_dialog_content = "...",
  ui_story_5084_50841302_200_dialog_content = "Oye, la vela casi se apaga, Victoria.",
  ui_story_5084_50841400_1_dialog_content = "Acerca de esta \"Llave Universal\", Lady Victoria...",
  ui_story_5084_50841400_2_dialog_content = "El Maestro Cleves lo enterró con el Sr. Wilhelm, quien ahora no se ve por ningún lado, así que esto es todo lo que pude encontrar.",
  ui_story_5084_50841400_3_dialog_content = "¿No es esta la Caja Negra...?",
  ui_story_5084_50841400_4_dialog_content = "PlayerName...",
  ui_story_5084_50841400_5_dialog_content = "Oh, lo siento, olvidé que tal información no pertenece aquí.",
  ui_story_5084_50841400_6_dialog_content = "¡Sé que te irás, así que se lo estoy pasando al líder de la Hermandad de la Verdad, Lady Victoria!",
  ui_story_5084_50841400_7_dialog_content = "No, ninguno de nosotros puede esperar controlarlo. Solo déjalo aquí.",
  ui_story_5084_50841400_8_dialog_content = "Asegúrate de que nadie lo toque, ni siquiera yo. Todo debe seguir la voluntad del Señor.",
  ui_story_5084_50841400_9_dialog_content = "Tengo una solicitud, Lady Victoria. ¿Es posible que no me hagas su guardián?",
  ui_story_5084_50841400_10_dialog_content = "Se supone que debes ser su guardián. Cuando mi padre se lo dio a Cleves, probablemente ya vio cómo se desarrollaría su destino.",
  ui_story_5084_50841400_11_dialog_content = "No sé cuánto tiempo podré guardar la Tumba de Varaki.",
  ui_story_5084_50841400_12_dialog_content = "Con permiso, me gustaría abdicar de mi posición como gobernante de la casa y ser una vid a tiempo completo que protege la tumba y espera tu llegada.",
  ui_story_5084_50841400_13_dialog_content = "Puedo lanzar magia para hacer desaparecer la tumba de la mente de los gobernantes, pero ¿hay una verdad que mantienes resoluta en tu corazón?",
  ui_story_5084_50841400_14_dialog_content = "La verdad es que quería dejar el mundo desde el principio, y esta tumba resultó ser la elección perfecta.",
  ui_story_5084_50841400_15_dialog_content = "No tiene nada que ver con quién lidera la Orden. Por supuesto, no estoy cuestionando tu decisión, Lady Victoria.",
  ui_story_5084_50841400_16_dialog_content = "¿Todavía prefieres proteger la tumba en lugar de la libertad?",
  ui_story_5084_50841400_17_dialog_content = "Mi familia ya no existe. Estaré solo dondequiera que esté.",
  ui_story_5084_50841400_18_dialog_content = "Entonces, te concederé el derecho de buscar tu paz aquí.",
  ui_story_5084_50841400_19_dialog_content = "Eres el amigo más leal de los Varakis. Tienes el derecho de reemplazar a David Porfirio y vigilar la ciudad mientras estoy fuera.",
  ui_story_5084_50841400_20_dialog_content = "¡No me atrevería a soñar eso...!",
  ui_story_5084_50841400_21_dialog_content = "Pero ese es el final que esperabas. Puedes comenzar una nueva familia y futuro.",
  ui_story_5084_50841400_22_dialog_content = "Recuerdo que abandonaste todas las asociaciones pasadas con Lumopolis, incluyendo tu apellido.",
  ui_story_5084_50841400_23_dialog_content = "Adelante, elige un nuevo apellido y que sea la base de un nuevo comienzo.",
  ui_story_5084_50841400_24_dialog_content = "Entiendo, Mi Señora.",
  ui_story_5084_50841400_25_dialog_content = "Elijo... Dantes.",
  ui_story_5084_50841400_26_dialog_content = "A partir de este punto, se me conocerá como Glave Dantes.",
  ui_story_5084_50841400_27_dialog_content = "(¿¡Dantes?! ¿Es el antepasado de Sikare Dantes?)",
  ui_story_5084_50841400_28_dialog_content = "Ya que has elegido tu destino, continuemos.",
  ui_story_5084_50841400_29_dialog_content = "Tu clan ha sido y siempre será un aliado de confianza para los Varakis. La Caja Negra vigilará tu linaje.",
  ui_story_5084_50841400_30_dialog_content = "Entendido. Me despediré ahora.",
  ui_story_5084_50841400_31_dialog_content = "Uf, parece que ha terminado.",
  ui_story_5084_50841400_32_dialog_content = "Hemos terminado con el Advenimiento de la Verdad aquí, pero hay otro esperándonos de vuelta en Vortex.",
  ui_story_5084_50841400_33_dialog_content = "No, eso significa tres Advenimiento de la Verdad! Estoy empezando a extrañar Lenore...",
  ui_story_5084_50841400_34_dialog_content = "Oye, la vela realmente se va a apagar esta vez.",
  ui_story_5084_50841400_35_dialog_content = "...",
  ui_story_5084_50841400_36_dialog_content = "(Victoria parece estar esperando a Wilhelm de la forma en que mira a la distancia...)",
  ui_story_5084_50841400_37_dialog_content = "Vamos.",
  ui_story_5084_50841400_38_dialog_content = "¿Llevarás contigo ambas biblias, Lady Victoria?",
  ui_story_5084_50841400_39_dialog_content = "Irán a donde se supone que deben ir en nuestro camino de regreso. Preparémonos.",
  ui_story_5084_50841400_40_dialog_content = "¡La vela está apagada! Oye, todavía estás sosteniendo la vieja biblia.",
  ui_story_5084_50841400_41_dialog_content = "Nos llevó hasta aquí para que conozca su nueva versión, así que es hora de devolverlo a la mano del destino.",
  ui_story_5084_50841400_42_dialog_content = "Victoria?",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>En la oscuridad que regresa, apareció una grieta en el torrente del tiempo. Un largo y extraño fragmento se podía vislumbrar en la bruma.</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>Victoria soltó la biblia que había estado con ella durante muchos años y la vio nadar en la corriente.</color>",
  ui_story_5084_50841400_45_dialog_content = "¿A dónde fue?",
  ui_story_5084_50841400_46_dialog_content = "Mira dentro del torrente, y podrías ver La Verdad.",
  ui_story_5084_50841400_47_dialog_content = "Cualquiera de nosotros no es más que arena en el río. Finalmente, volveremos al Señor de la Verdad.",
  ui_story_5084_50841400_48_dialog_content = "Ve y cumple tu destino.",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>La biblia fluyó \"aguas abajo\" y dejó a los \"extraños futuros\".</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>Flotaba pacíficamente en el Río Prístino mientras innumerables imágenes aparecían en las ondulaciones de su curso, mostrando el pasado y el futuro.</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>Sus páginas se abrieron por sí solas y conjuraron letras en las hojas anteriormente en blanco.</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>Así, se escribió el destino...</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>El reflejo de la biblia se proyectó en las historias y el tomo comenzó a recibir reconocimiento. Finalmente, era parte del río.</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>\"Wilhelm recogió la Biblia Sangrienta que venía de partes desconocidas. Sintió la presencia de revelaciones dentro y decidió llevarla a un Victoria durmiendo.\"</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>\"La joven Victoria hojeó el tomo en blanco y escuchó la profecía de La Verdad por primera vez.\"</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>El libro continuó fluyendo río abajo. El tiempo no tenía ni principio ni fin en el río, sino un ciclo sin fin.</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>\"Por lo tanto, Victoria soltó la biblia que había estado con ella durante muchos años y la vio nadar en el torrente.\"</color>",
  ui_story_5084_50841400_58_dialog_content = "Todos los viajeros han regresado a sus respectivos tiempos. También debería terminar mi trabajo.",
  ui_story_5084_50841400_59_dialog_content = "Victoria del año 1918, todavía estás en el camino para descubrir La Verdad. Todavía estabas perdido y todo debió parecerte confuso.",
  ui_story_5084_50841400_60_dialog_content = "Está bien. El tiempo te llevará a ello.",
  ui_story_5084_50841400_61_dialog_content = "Te embarcarás en un largo viaje antes de alcanzar la iluminación.",
  ui_story_5084_50841400_62_dialog_content = "Entonces tú los llevarás de vuelta a este mismo punto y nos encontraremos de nuevo.",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>Wilhelm entregó el Victoria dormido de Vortex a ella y puso la Bloody Bible en su mano.</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>Luego se acostó dentro del ataúd en el que llegó y reflexionó sobre su pasado.</color>",
  ui_story_5084_50841400_65_dialog_content = "Cuando tú, como un niño pequeño, me conociste por primera vez, fue porque tu hermano deseaba confiarte a mí, ya que estaba a punto de morir.",
  ui_story_5084_50841400_66_dialog_content = "¿Para que yo pueda convertirme en el líder?",
  ui_story_5084_50841400_67_dialog_content = "Sí, y luego cuida de Victoria.",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>Victoria se quedó en silencio junto a sus padres, sin comprender la razón de su contento a pesar de que estaban muriendo.</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>Pero Wilhelm Varaki, quien había soportado innumerables humillaciones, no podía soportar liderar el destrozado Victoria por el fatídico camino de los vampiros.</color>",
  ui_story_5084_50841400_70_dialog_content = "Deja de perder el aliento. No lo haré.",
  ui_story_5084_50841400_71_dialog_content = "...",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>Pero el día del funeral, Wilhelm todavía vestía el atuendo de un discípulo y vio a su hermano y cuñada salir de la ciudad de Varaki en ataúdes.</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>Wilhelm se quedó fuera de la Tumba Varaki, escuchando los \"saludos\" de los maestros para Victoria.</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>Las fuerzas de la tormenta y el rayo que parecían destinadas a desgarrar el mundo reflejaban las emociones de Wilhelm.</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>Se lanzó al corazón de la tumba solo para ponerse el Anillo de Varaki que podría corromperlo frente a los maestros...</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>Solo para proteger a la chica que estaba a punto de embarcarse en la búsqueda de La Verdad con él.</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>No había sido una relación feliz entre ellos, pero Wilhelm debe obligar a Victoria a dejar de resistir la Orden y a volverse más fuerte.</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>Todo el tiempo buscando cualquier opción para mantenerlos a salvo.</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>También sobre su propia muerte...</color>",
  ui_story_5084_50841400_80_dialog_content = "Cleves...",
  ui_story_5084_50841400_81_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841400_82_dialog_content = "Victoria...",
  ui_story_5084_50841400_83_dialog_content = "Je...",
  ui_story_5084_50841400_84_dialog_content = "(Según las tradiciones vampíricas, la muerte es quizás una bendición.)",
  ui_story_5084_50841400_85_dialog_content = "(Pero este yo ya no siente el dolor de la traición de los demás.)",
  ui_story_5084_50841400_86_dialog_content = "(Entiendo lo difícil que es para ti, pero ¿qué será de Victoria ahora?)",
  ui_story_5084_50841400_87_dialog_content = "(¿Le he transmitido toda la Verdad que he aprendido?)",
  ui_story_5084_50841400_88_dialog_content = "(¿Iba a decirme que está en un camino inquebrantable hacia La Verdad antes de que se fuera?)",
  ui_story_5084_50841400_89_dialog_content = "(...)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>Wilhelm nunca dejó de hacer preguntas a La Verdad cuando su mente se trasladó a un río claro.</color>",
  ui_story_5084_50841400_91_dialog_content = "¿Qué está pasando? ¿No estaba yo en la iglesia...? Debería estar muerto ahora mismo.",
  ui_story_5084_50841400_92_dialog_content = "¿Dónde estoy?",
  ui_story_5084_50841400_93_dialog_content = "¿El Reino de los Muertos, o el Templo del Señor de la Verdad?",
  ui_story_5084_50841400_94_dialog_content = "¿Qué es este río?",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>Wilhelm flotaba sin cesar sin moverse, pero su mente absorbía toda la información del mundo.</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>¿Una década? ¿Un siglo? ¿Cuánto tiempo ha pasado...?</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>Eoria oscureció y volvió a brillar, mientras el conflicto entre Aurorianos y Eclipsites continuaba.</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>Pero él se desplazó a través de todo eso.</color>",
  ui_story_5084_50841400_99_dialog_content = "¿Ese soy yo?",
  ui_story_5084_50841400_100_dialog_content = "Ese no es su deseo pero sí su destino. Pon esta nueva Bloody Bible en el ataúd para mí. Le será útil.",
  ui_story_5084_50841400_101_dialog_content = "Sí, señor Wilhelm.",
  ui_story_5084_50841400_102_dialog_content = "Y cuando llegue ese momento...",
  ui_story_5084_50841400_103_dialog_content = "¿Por qué estás triste? Simplemente puedes formar una familia y terminar con eso.",
  ui_story_5084_50841400_104_dialog_content = "¿Formar una familia y criar niños? Qué aburrido.",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>Muchas versiones de Wilhelm estaban esparcidas por todas partes, pero apiladas unas encima de otras. Era un caos puro hasta que vio presencias aparte de él mismo.</color>",
  ui_story_5084_50841400_106_dialog_content = "No tomaré crédito por ello. Esta es una bendición del Señor de la Verdad.",
  ui_story_5084_50841400_107_dialog_content = "¿Qué es esto?",
  ui_story_5084_50841400_108_dialog_content = "El <color=#FFB400>Río Prístino</color>, fuera del tiempo y del espacio. La única diferencia con el mundo exterior es que fluye.",
  ui_story_5084_50841400_109_dialog_content = "¡No podremos controlar nuestras vidas si esto continúa! ¿Por qué nos trajiste aquí?",
  ui_story_5084_50841400_110_dialog_content = "Victoria?!",
  ui_story_5084_50841400_111_dialog_content = "Je, ¡jajaja!",
  ui_story_5084_50841400_112_dialog_content = "Sabía que podrías hacerlo, Victoria Varaki.",
  ui_story_5084_50841400_113_dialog_content = "Y Charon también.",
  ui_story_5084_50841400_114_dialog_content = "Lo hicimos como su anciano, Cleves.",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>Mientras los recuerdos se desvanecían, Wilhelm se levantó solo para darse cuenta de que no estaba en su ataúd, sino observando e inmerso en el siempre fluyente Río Prístino.</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>Todo con lo que él había interferido lo enredaría y lo llevaría a la Afirmación de la Verdad.</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>Entonces...</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>El tomo que dejó caer Victoria dejó de flotar porque chocó con una barrera, un \"muerto\" yacía en el río.</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>Este traicionado cadáver de Wilhelm, el hombre al que la Puerta del Destino llamó, despertó en la maravillosa corriente.</color>",
  ui_story_5084_50841400_120_dialog_content = "¡¿...?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>El desconcertado Wilhelm logró notar que la Biblia sangrienta se detuvo a sus pies en el río.</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>Como si respondiera a una llamada silenciosa, hojeó el tomo totalmente en blanco y comenzó a ver...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>\"La Biblia sangrienta flota y se detiene junto a los pies del muerto Wilhelm. El joven vampiro despierta debido a una gota de sangre en los escombros de un anillo.\"</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>\"El confundido Wilhelm logra notar que la Biblia sangrienta se detiene a sus pies en el río.\"</color>",
  ui_story_5084_50841400_125_dialog_content = "¿Qué?",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>\"Sobresaltado, Wilhelm tropieza hacia atrás en el río, empapándose en el agua que ha perturbado y contaminando sus causas y efectos.\"</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>\"Sentado en el río, Wilhelm se da cuenta de que tiene algo en su mano. Al recogerlo con un escalofrío, se da cuenta de que es...\"</color>",
  ui_story_5084_50841400_128_dialog_content = "¿El anillo ancestral de Varaki?",
  ui_story_5084_50841400_129_dialog_content = "¿Qué significa todo esto?",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>\"Habiendo recibido la llamada, Wilhelm está destinado a vagar y guiar a otros hacia La Verdad.\"</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>\"Cuando llegue el momento adecuado, la Tumba Varaki se abrirá para Victoria. Wilhelm, Servidor de La Verdad, será su guía.\"</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>\"Wilhelm entonces se acuesta dentro del ataúd en el que llegó y reflexiona sobre su pasado.\"</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>\"Cuando se dé cuenta de que su propósito se ha cumplido y Victoria está listo, ¿finalmente descansará en paz?\"</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>\"Pero cuando toca el anillo, una gota de sangre de Varaki dentro de él recorre su cuerpo. Cae en un sueño profundo a medida que regresa la sensación familiar.\"</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>\"Cuando Wilhelm despierte de nuevo, será guiado a la encrucijada del destino.\"</color>",
  ui_story_5084_50841400_136_dialog_content = "Dónde estoy...",
  ui_story_5084_50841400_137_dialog_content = "Aunque Lady Victoria me dijo que la piedad me mostraría el camino...",
  ui_story_5084_50841400_138_dialog_content = "Pero yo sacrificaré...",
  ui_story_5084_50841400_139_dialog_content = "I will...",
  ui_story_5084_50841400_140_dialog_content = "...",
  ui_story_5084_50841400_141_dialog_content = "... My lord?",
  ui_story_5084_50841400_142_dialog_content = "¡El gran Señor de la Verdad!",
  ui_story_5084_50841400_143_dialog_content = "Did you just say... Lady Victoria?",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>\"El tiempo no tiene ni principio ni fin en el río, sino un ciclo sin fin.\"</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>\"Así, Victoria suelta la biblia que ha estado con ella durante muchos años y la observa nadar en el torrente.\"</color>",
  ui_story_5084_50841400_146_dialog_content = "Estás de vuelta.",
  ui_story_5084_50841400_147_dialog_content = "Sí. La vela se ha ido.",
  ui_story_5084_50841400_148_dialog_content = "Ese tipo de poder pertenecía a Faria.",
  ui_story_5084_50841400_149_dialog_content = "Cierra, Faria.",
  ui_story_5084_50841400_150_dialog_content = "(Entiendo... Así que la Cripta Estrellada era la Tumba Varaki en aquel entonces.)",
  ui_story_5084_50841400_151_dialog_content = "Nos encontramos de nuevo, \"Llave Universal.\"",
  ui_story_5084_50841400_152_dialog_content = "¿Srta. Victoria?",
  ui_story_5084_50841400_153_dialog_content = "Je, por favor disculpa mi murmullo para mí mismo.",
  ui_story_5084_50841400_154_dialog_content = "Seguro.",
  ui_story_5084_50841400_155_dialog_content = "¿May?",
  ui_story_5084_50841400_156_dialog_content = "¿Qué haces aquí, May?",
  ui_story_5084_50841400_157_dialog_content = "No estabas en casa después de hacer el pan, así que supuse que viniste a ver a Sikare. No esperaba ver a la señorita Victoria y a todos los demás aquí también.",
  ui_story_5084_50841400_158_dialog_content = "Espera, creo que escuché que se mencionaba comida...",
  ui_story_5084_50841400_159_dialog_content = "Pan agradable y vino... todos preparados personalmente por May para la Venida de la Verdad!",
  ui_story_5084_50841400_160_dialog_content = "Ahora que lo dijiste, tengo hambre.",
  ui_story_5084_50841400_161_dialog_content = "Vendrás a la celebración con nosotros, ¿verdad, Sikare?",
  ui_story_5084_50841400_162_dialog_content = "Sí. Ciertamente responderé a la invitación de Victoria.",
  ui_story_5084_50841400_163_dialog_content = "Es hora. Los miembros de la Orden deberían estar reuniéndose en la ciudad, Lady Victoria.",
  ui_story_5084_50841400_164_dialog_content = "¿Estarán todos de la Orden allí?",
  ui_story_5084_50841400_165_dialog_content = "Estabas reacio cuando te invitamos. ¿Estás lleno de anticipación ahora?",
  ui_story_5084_50841400_166_dialog_content = "No puedo decir que veo a mis amigos de la Orden muy a menudo, pero siempre es bueno estar en su compañía.",
  ui_story_5084_50841400_167_dialog_content = "Bienvenidos, todos, a la celebración trienal de True Order.",
  ui_story_5084_50841400_168_dialog_content = "En los tres años desde entonces, estamos un paso más cerca de entender a Eoria así como al Señor de la Verdad.",
  ui_story_5084_50841400_169_dialog_content = "Aparte del Señor inmortal, no seguimos ningún precepto fijo, independientemente de nuestro origen.",
  ui_story_5084_50841400_170_dialog_content = "Ya sea nuestras individualidades únicas, escapar de las ataduras del pasado, o cumplir un cierto propósito...",
  ui_story_5084_50841400_171_dialog_content = "Debido a la transformación continua, brillamos intensamente en el viaje hacia La Verdad.",
  ui_story_5084_50841400_172_dialog_content = "El True Order que ves ahora está en el camino bendecido por La Verdad.",
  ui_story_5084_50841400_173_dialog_content = "Puedo asegurarte que esos vampiros fuera de Astra con estrechos lazos con la Orden están listos.",
  ui_story_5084_50841400_174_dialog_content = "Y yo guiaré a todos ustedes para presenciar la llegada del Señor de la Verdad.",
  ui_story_5084_50841400_175_dialog_content = "En la crisis de Darkover, la Bloody Bible reveló una gran revolución por venir.",
  ui_story_5084_50841400_176_dialog_content = "Los revolucionarios que estaba fomentando en aquel entonces han madurado.",
  ui_story_5084_50841400_177_dialog_content = "El candado aparecerá en la Zona Oscura. Traeré la llave al destino y reconstruiré el reino con el Señor.",
  ui_story_5084_50841400_178_dialog_content = "Será un viaje traicionero a través de la Zona Oscura. Una vez más, la True Order guiará a los Aurorians a través de la crisis como su aliado.",
  ui_story_5084_50841400_179_dialog_content = "Ahora por favor disfruten del festín.",
  ui_story_5084_50841400_180_dialog_content = "Fue Él quien me honró y otorgó el Alimento de la Verdad a ti.",
  ui_story_5084_50841400_181_dialog_content = "También eres bienvenido a intercambiar tu iluminación personal con otros.",
  ui_story_5084_50841400_182_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50841400_183_dialog_content = "Que la Verdad te bendiga.",
  ui_story_5084_50841400_184_dialog_content = "Has estado echando un vistazo a Faust durante un tiempo, Pasolo. ¿Hay algo mal con él?",
  ui_story_5084_50841400_185_dialog_content = "Bueno, Sr. Faust, se trata de las almas de mis padres fallecidos. La señorita Sikare pensó que quizás usted podría ofrecerme una nueva perspectiva...",
  ui_story_5084_50841400_186_dialog_content = "Si es una nueva perspectiva la que buscas, intenta con Nails. Él ha evolucionado más que nadie últimamente.",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>Retumbar, retumbar...</color>",
  ui_story_5084_50841400_188_dialog_content = "Ayúdame a detener la cosa, PlayerName!",
  ui_story_5084_50841400_189_dialog_content = "¡Oh no, es demasiado rápido... y está rodando hacia Nails!",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5084_50841400_191_dialog_content = "Lo siento, Sr. Nails! Hunting Stone no te lastimó, ¿verdad?",
  ui_story_5084_50841400_192_dialog_content = "No, señorita Pact. Si deseas hacerme sentir dolor, puedes apuñalarme con espinas aquí.",
  ui_story_5084_50841400_193_dialog_content = "¡Sr. Nails! ¿No prometiste que no te lastimarías esta noche? ¿Eso tiene algo que ver con tu nuevo atuendo?",
  ui_story_5084_50841400_194_dialog_content = "Señor. Nails, el Señor. Faust me dijo que podrías darme una nueva perspectiva sobre las almas.",
  ui_story_5084_50841400_195_dialog_content = "Ah, perspectiva... Mi mentor de hecho me ofreció algo de eso.",
  ui_story_5084_50841400_196_dialog_content = "Creo que el alma es la concentración del espíritu de uno. Mientras el espíritu permanezca, uno nunca se ha ido realmente.",
  ui_story_5084_50841400_197_dialog_content = "Ya veo... Entonces, ¿podré ver a los difuntos de nuevo?",
  ui_story_5084_50841400_198_dialog_content = "Quizás Victoria tenga la respuesta a eso.",
  ui_story_5084_50841400_199_dialog_content = "Oye, ha pasado mucho tiempo y puedo sentir el santo aura golpeándome.",
  ui_story_5084_50841400_200_dialog_content = "¿Cómo está, Sr. Telamont?",
  ui_story_5084_50841400_201_dialog_content = "¿Recogiste algo en tu tiempo con la Dama Victoria?",
  ui_story_5084_50841400_202_dialog_content = "Fue un honor para mí conocer a un mentor importante. Fue él quien me llevó a mi transformación bajo el Señor.",
  ui_story_5084_50841400_203_dialog_content = "No pensé que los ascetas pudieran venir alguna vez. ¿Está aquí tu mentor ahora?",
  ui_story_5084_50841400_204_dialog_content = "Me avergüenza admitir que no sé...",
  ui_story_5084_50841400_205_dialog_content = "Lady Victoria, dijo el Sr. Nails, \"Mientras el espíritu permanezca, uno nunca se ha ido realmente.\"",
  ui_story_5084_50841400_206_dialog_content = "¿Eso significa que mis padres muertos han estado conmigo todo este tiempo?",
  ui_story_5084_50841400_207_dialog_content = "Los Aurorianos nacieron de la luz de la fe. Su poder espiritual provenía de un río alto.",
  ui_story_5084_50841400_208_dialog_content = "Deberías rezar para que algunos de los espíritus de tus padres hayan regresado allí.",
  ui_story_5084_50841400_209_dialog_content = "Debería rezar por ellos...",
  ui_story_5084_50841400_210_dialog_content = "Gracias por la respuesta, Lady Victoria. Reflexionaré más sobre ello...",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>Victoria se emocionó al ver cuán fuerte se ha vuelto la Orden.</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>Fue el resultado del pasado Wilhelm y su yo actual despejando las barreras para que el joven Victoria pudiera avanzar.</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>La orientación que recibieron podría provenir de alguien en el pasado o en el futuro, haciendo todo lo posible para transmitir su intención en el flujo del tiempo y el espacio.</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>Victoria vio a innumerables viajeros en el Río del Destino, cada uno representando el coraje para buscar La Verdad.</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>Todo sería visto por cierta persona a la deriva en el flujo del tiempo.</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>Las corrientes alternarían como estaba escrito en el tomo, pero Victoria no tenía deseos de pasar la página tan rápidamente.</color>",
  ui_story_5084_50841400_217_dialog_content = "¿Significa eso que crees en el aislamiento tanto como yo?",
  ui_story_5084_50841400_218_dialog_content = "Aunque puedo entender por qué no asistirían a ninguna celebración, siempre es así con los reclusos.",
  ui_story_5084_50841400_219_dialog_content = "¿Los reclusos tienen su propia organización?",
  ui_story_5084_50841400_220_dialog_content = "No exactamente, pero se dice que la secta fue fundada por un misterioso discípulo masculino en la ciudad de Varaki alrededor de 1915.",
  ui_story_5084_50841400_221_dialog_content = "¿Lady Victoria nunca te lo ha dicho?",
  ui_story_5084_50841400_222_dialog_content = "En comparación con tu presencia en las ciudades aurorianas, solo he conocido a un puñado de ermitaños autoproclamados en la naturaleza.",
  ui_story_5084_50841400_223_dialog_content = "¿Qué sueles hacer?",
  ui_story_5084_50841400_224_dialog_content = "Busca espacios vacíos o explora rincones ocultos.",
  ui_story_5084_50841400_225_dialog_content = "Then what?",
  ui_story_5084_50841400_226_dialog_content = "Quédate ahí y no hagas nada.",
  ui_story_5084_50841400_227_dialog_content = "Esta llamada reclusión me suena a no querer aprender de los libros...",
  ui_story_5084_50841400_228_dialog_content = "Probablemente eso se debe a que no había ningún libro que un maestro ermitaño no hubiera leído.",
  ui_story_5084_50841400_229_dialog_content = "Pero, ¿por qué tengo la sensación de que, en tu caso, tienes los libros pero eliges no leerlos...",
  ui_story_5084_50841400_230_dialog_content = "¡Debe ser una gran figura! May ¿Puedo preguntar su nombre?",
  ui_story_5084_50841400_231_dialog_content = "Nadie sabe su nombre, pero yo lo he visto.",
  ui_story_5084_50841400_232_dialog_content = "Esbelto, con un cierto aire de nobleza tradicional...",
  ui_story_5084_50841400_233_dialog_content = "Porque a menudo lleva un sombrero de copa negro, una capa negra rojiza y un caballo negro.",
  ui_story_5084_50841400_234_dialog_content = "¿...?",
  ui_story_5084_50841400_235_dialog_content = "Es inescrutable y viaja mucho. Algunos afirmaron que esperaba la oportunidad de encontrarse con un viejo amigo.",
  ui_story_5084_50841400_236_dialog_content = "¿Podría ser ese mi mentor?",
  ui_story_5084_50841400_237_dialog_content = "¿Quién?",
  ui_story_5084_50841400_238_dialog_content = "El viejo amigo que le gustaría conocer...",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>\"Cuando todas las cosas hayan terminado, ven a buscarme aquí,\" eso fue lo que él dijo.</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>Victoria seguía junto a la ventana mientras veía a través del tiempo y se quedaba fascinada con las figuras que perseguían La Verdad.</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>Como las estrellas en el cielo nocturno, algunas eran brillantes, otras tenues, pero cada una de ellas interpretó la Verdad a su manera.</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>Victoria entendió que buscar la Verdad es como perseguir estrellas lejanas y exigió perspicacia de los ojos de la mente.</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>Pero él era simplemente el guía que los llevaba hacia adelante.</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>Desde la ventana, él suspiró. Ha llegado a ver a cada miembro de True Order como su niño.</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>Sabía que, independientemente de lo arduo que fuera el camino para ellos, Victoria siempre proporcionaría luz en la hora más oscura.</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>Pero solo él sabía que la mujer junto a la ventana también era una buscadora solitaria.</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>Victoria cerró los ojos y dejó que su corazón resonara a través de la noche.</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>Ella entendió que hay diferentes caminos hacia La Verdad, ya sea en soledad o en un Orden bullicioso.</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>\"La Verdad es una búsqueda interminable,\" murmuró.</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>\"Y yo te vigilaré y te guiaré en tu viaje.\"</color>"
}
return config
